-- ============================================================
-- Gurcu3c (3/4): Günə-özəl push bildirişlərinin KA tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498'::uuid, '20-წუთიანი ფეხსაცმელი 👟', 'თავად სურს ფეხსაცმლის ჩაცმა და სახლიდან გასვლა გიგვიანდებათ? მოთმინებას ნუ დაკარგავთ.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'წინადადებები გრძელდება 🗣️', 'უკვე სიტყვებს ერთმანეთს უკავშირებს და საინტერესო წინადადებებს ქმნის, რომლებიც სრულად მის საკუთარ ლოგიკას შეესაბამება. არ გამოტოვოთ ეს მომენტები — „ბავშვის ფოტოსესიის“ მეშვეობით მისი ეს საყვარელი დიალოგები ვიდეოზე გადაიღეთ.'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'თამაშები სიბნელეში 🐰', 'შუქის ჩაქრობისას ეშინია? ოთახი მთლიანად დააბნელეთ და ფანრით კედელზე ჩრდილების თეატრი მოაწყვეთ. შიში გართობად აქციეთ და დაეხმარეთ, სიბნელეს შეეგუოს.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'სიმაღლისა და წონის ნახტომი 📏', 'შარვლები ისევ დაუმოკლდა? სწრაფად იზრდება! „განვითარების მონიტორში“ მიმდინარე მონაცემები შეიყვანეთ და ამაყად შეხედეთ აღმავალ განვითარების მრუდს — თქვენი უძილო ღამეების შედეგს.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'უმიზეზო გაღვიძებები 😭', 'შუაღამისას ყვირილით გაიღვიძა. ნუ შეშინდებით. „ტირილის ანალიზის“ ხელსაწყოთი შეამოწმეთ, მიზეზი ზრდის ტკივილია თუ ღამის ტერორი, შემდეგ კი მოთმინებით ჩაიხუტეთ.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'ყინულივით ცივი ყავა ☕', 'ყავის მომზადებიდან 3 საათის შემდეგ დალევა დედობის ოფიციალური დაუწერელი კანონია. დღეს გამონაკლისი დაუშვით. ბავშვი სათამაშოებთან ცოტა ხნით მარტო დატოვეთ და ეს ყავა 10 წუთში, ჯერ კიდევ ცხელი დალიეთ!'),
  ('1e03f3e4-2305-4ae5-883c-39581f248697', 'რიცხვებს აღმოაჩენს 🔢', 'კიბეზე ასვლისას ან სათამაშოების დალაგებისას ცდილობს, ერთი, ორი, სამი დაითვალოს. შემეცნებითი განვითარების ამ მათემატიკურ ეტაპზე მხარი დაუჭირეთ და მასთან ერთად დაითვალეთ.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'მამის საიდუმლო იარაღი 🤡', 'როცა თქვენი ხერხები აღარ ჭრის, მამის უცნაური ხმები და სასაცილო მიმიკები მდგომარეობას მყისიერად შველის. საღამოს ჭირვეულობის დროს საქმე მაშინვე მას გადააბარეთ.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'დღის ძილთან დაკავშირებული სირთულეები 🥱', 'დაწოლა არაფრით უნდა? 2.5 წლის ასაკში ზოგი ბავშვი დღის ძილზე უარის თქმას იწყებს. ნუ დააძალებთ ძილს — მის ნაცვლად 30-წუთიანი მშვიდი კითხვის დრო შესთავაზეთ.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'დაბლა ჩაიხედე, იქ რა არის? 👣', 'განსაკუთრებით სიამოვნებს ფეხშიშველი სიარული და სხვადასხვა ზედაპირთან (ქვიშა, ხალიჩა, ქვა) შეხება. ტერფებზე არსებული ნერვული დაბოლოებების სტიმულირება მისი ნევროლოგიური განვითარებისთვის ძალიან მნიშვნელოვანია.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა მკვეთრი განათება და ლურჯი ეკრანი გამორთეთ. მელატონინის გამომუშავების ხელშესაწყობად სახლში ბინდით მოცული გარემო შექმენით.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'ექიმთან დაკავშირებული ღელვა 🤖', '2.5 წლის ასაკში საჭირო ვაქცინებთან ან ვიტამინებთან დაკავშირებით კითხვები გაგიჩნდათ? ინტერნეტში შემაშინებელ ფორუმებზე ნუ დაიკარგებით — ზუსტი პასუხი დაუყოვნებლივ Anacan AI-სგან მიიღეთ.'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'მცირე კამათები 🗣️', 'არა, მე უკვე დიდი ვარ, თავად ვიცი! ახლა უკვე არგუმენტების მოყვანით ცდილობს, არ დაგეთანხმოთ. ხმის აწევის გარეშე, თანასწორად, მაგრამ მტკიცედ უპასუხეთ.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'საკუთარი თავისთვის დროის დათმობა დანაშაული არ არის 💆‍♀️', 'სინდრომი „ბავშვთან ცოტა დროს ვატარებ“ ყველა დედას აწუხებს. მაგრამ ნუ დაგავიწყდებათ, რომ გამოფიტულ დედას ბავშვისთვის აღარაფერი რჩება. დღისით საკუთარი თავისთვის 20-წუთიანი შესვენება მოიწყვეთ.'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'ყველაზე ძვირფასი ტვირთი 🫂', 'მთელი დღე ჭკუიდან გადაგიყვანათ და ყველაფერზე ტიროდა. მაგრამ საღამოს, დაძინებისას, თქვენს მკერდზე მოკრული იმ თბილი, პატარა სხეულის სურნელი... აი, ეს არის მსოფლიოში ყველაზე მშვენიერი შეგრძნება.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'სივრცე დედებისთვის ☕', 'მოგბეზრდათ ყოველდღე ერთსა და იმავე პარკში სიარული? დედებისთვის მეგობრულ სივრცეებს შორის აღმოაჩინეთ მშვიდი და განსხვავებული კაფე, სადაც ბავშვებიც თავისუფლად ითამაშებენ, და დღეს საკუთარი თავი გაანებივრეთ.'),
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80', 'ფორმისა და სივრცის აღქმა 🧩', 'დაჟინებით ცდილობს, ფაზლები და სხვადასხვა ფორმა შესაბამის ჭრილებში მოათავსოს. შეცდომაც რომ დაუშვას, ნუ ჩაერევით. პრობლემების გადაჭრის უნარს სწორედ ცდისა და შეცდომის გზით სწავლობს.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'ბუნებრივი თეთრი ხმაური 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ტვინის ყველაზე აქტიური პერიოდია. ხმის საზომის დახმარებით ოთახში ხმაურის დონე დაარეგულირეთ. ზოგჯერ მსუბუქი წვიმის ხმაც კი შეიძლება ბავშვს ღრმად დააძინოს.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'მადლობა გადაუხადეთ საკუთარ თავს 🎈', 'ღამეები უძილოდ, დღეები კი გაუთავებელ სირბილში... მაგრამ თქვენ ეს შეძელით. დღეს შეაქეთ საკუთარი თავი იმისთვის, რომ ბავშვი ხმის აუწევლად გაზარდეთ!'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'მაღაზიაში სიის გარეშე წასვლა? არასოდეს! 🛒', 'მეხსიერების იმედად მიდიხართ მაღაზიაში და სახლში ყველაზე საჭირო ნივთის გარეშე ბრუნდებით. უარი თქვით ამ ჩვევაზე. მიეჩვიეთ, რომ სახლში ნაკლებობა მაშინვე საყიდლების სიაში ჩაიწეროთ.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'მიეცით ემოციებს თავისუფლება 📝', 'ვინმეს თქვენი არ ესმის? თქვენს დაღლილობას ვერ ამჩნევს? განწყობის დღიური საუკეთესო მესაიდუმლეა. ჩაწერეთ იქ მთელი თქვენი სტრესი, ტკივილი და მარტოობის განცდა — ნახავთ, როგორ შეგიმსუბუქდებათ გული.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'ბოსტნეულთან ბრძოლა გრძელდება 🥦', 'წვნიანში ისევ ის პატარა სტაფილოს ნაჭერი დაინახა და ჭამაზე უარი თქვა? შეამცირეთ ულუფები და შეუცვალეთ საკვებს ფორმა. კრეატიულობა დედის ყველაზე ძლიერი იარაღია.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', '„გიპოვე!“ — სიურპრიზი 🙈', 'დამალობანას წესები შეიცვალა. ახლა ბავშვი იმალება, შემდეგ კი ყვირილით — „აქ ვარ!“ — თავად გამოდის. მიეცით საშუალება, თამაშის წესები თვითონ მოიგონოს და ერთად გულიანად იცინეთ.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'საღამოს სიმშვიდე 🛀', 'თუ ბავშვი საღამოს განსაკუთრებით ჭირვეულობს და გაღიზიანებულია, თბილ წყალში აბანავეთ. აბაზანაში უბრალოდ წყლით თამაში და წყლის თერაპიული ძალა მას მთელ უარყოფით ენერგიას ჩამორეცხავს.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'სიმღერების ღიღინი 🎶', 'თამაშის დროს თავისთვის გაუგებარი სიტყვებით სიმღერებს მღერის. ეს მეტყველებისა და სმენის განვითარების ნიშანია. აუცილებლად დაამატეთ ეს ახალი ეტაპი განვითარების მონიტორინგში.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'მამიკოს კითხვის საათი 📖', 'მოდი, ამ საღამოს ოთახში განსხვავებული ატმოსფერო შევქმნათ. წიგნის კითხვა მამიკოს ბოხ და დამაჯერებელ ხმას მიანდეთ, თავად კი გვერდით ჩამოჯექით და სრული სიჩუმით დატკბით.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'დედების მხარდაჭერის ჯგუფი 💬', 'რთული გადაწყვეტილება გაქვთ მისაღები? (საბავშვო ბაღი, ქოთანი, ძილი). Anacan-ის საზოგადოებაში გამოცდილი დედების რჩევები ყველაზე რეალური გამოსავალია, რომელსაც ვერცერთ წიგნში ვერ იპოვით.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'დატოვეთ სახლი არეული 🌪️', 'დაიღალეთ ყოველ საღამოს ერთი და იმავე სათამაშოების ყუთში ჩალაგებით? დღეს ნუ აალაგებთ! სახლი მუზეუმი კი არა, სიცოცხლით სავსე სივრცეა, სადაც პატარა მკვლევარი იზრდება.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'მიზანში სროლა და ბურთის დაჭერა ⚾', 'თქვენ მიერ ნასროლ დიდ ბურთს უკვე უბრალოდ კი აღარ ატარებს, არამედ მის დაჭერას ცდილობს. თვალისა და ხელის კოორდინაცია სწრაფად ვითარდება. დერეფანში ერთად ითამაშეთ მარტივი სპორტული თამაშები.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'ზღაპრის გარეშე არ ვიძინებთ 🪄', 'ოთახში შუქი მთლიანად ჩააქრეთ. ჭკვიან ზღაპრებში ფონად მხოლოდ ბუნების ხმები (ქარი, ტყე) ჩართეთ, რათა სიტყვების გარეშე მშვიდი გარემო შექმნათ და ბავშვს ჩაძინება გაუადვილოთ.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'კვებასთან დაკავშირებული კრიზისები 🥣', 'ორ კოვზს შეჭამს, ამბობს, რომ დანაყრდა და გარბის? ნუ დააძალებთ. საკვებთან ჯანსაღი დამოკიდებულების ჩამოყალიბება უფრო მნიშვნელოვანია, ვიდრე თეფშის ბოლომდე მოსუფთავება.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'კადრი, რომელიც დროს აჩერებს 📸', 'როცა ოთახში ტკბილად თამაშობს, მაშინვე გახსენით ბავშვის ფოტოსესია და ეს შეცვლილი, უკვე წამოზრდილი სახე და მოციმციმე თვალები ყოველგვარი ფილტრის გარეშე აღბეჭდეთ სამომავლო მოგონებად.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'კვლავ განშორების შფოთვა? 🥺', 'ტუალეტშიც კი რომ შედიხართ, კარს მიღმა გელოდებათ და ტირის. განშორების შფოთვა ზოგჯერ ბრუნდება. ყოველ ჯერზე გამოეხმაურეთ და სხვა ოთახიდანაც უთხარით, რომ იქვე ხართ და დაბრუნდებით.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'ენერგიის დახარჯვა აუცილებელია 🌳', 'ოთხ კედელში ყოფნა მას გაღიზიანებულს ხდის. ჩასვით ეტლში ან ხელი ჩაჰკიდეთ და სუფთა ჰაერზე გაიყვანეთ. ბუნების სიმშვიდე შესანიშნავად იმოქმედებს როგორც ბავშვზე, ისე თქვენს ფსიქოლოგიურ მდგომარეობაზე.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'სიბნელესთან შეგუება 🌙', 'იმისთვის, რომ უფრო სწრაფად ჩაეძინოს, ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ მშვიდ და ბნელ გარემოში გამოიყოფა.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', '„ეს რა არის?“ პერიოდი ☝️', 'ყველაფერზე თითით მიგითითებთ და სახელს გეკითხებათ? მას სურს, რომ სამყარო სიტყვებით გააცნოთ. ეს კომუნიკაციის განვითარებაში დიდი ნახტომია! მოთმინებით გაუმეორეთ თითოეული ნივთის სახელი, რომელზეც მიგითითებთ.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'გუნდური სიამაყე 🥂', 'რთული დღე უკან მოიტოვეთ. ბავშვის დაძინების შემდეგ პარტნიორთან ერთად ჩაი დაისხით და ერთმანეთი გაამხნევეთ სიტყვებით: „ჩვენ ამას მართლაც შესანიშნავად ვუმკლავდებით“.'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'ამინდი ცვალებადია ⛅', 'სასეირნოდ გასვლისას ამინდმა შეცდომაში არ შეგიყვანოთ და ბავშვი არ გააციოთ. მხოლოდ ფანჯრიდან გახედვით ნუ გადაწყვეტთ — ამინდისა და ჩაცმულობის დამხმარის მეშვეობით გარესამყაროს პირობებისთვის ყველაზე შესაფერისი სამოსი შეურჩიეთ.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'გაბედული ნახტომები 🧗‍♂️', 'დივნიდან ბალიშებზე ხტება. ის მიზიდულობის ძალასა და საკუთარ გამბედაობას ცდის. აკრძალვის ნაცვლად, ოთახში უსაფრთხო სახტომი სივრცე მოუწყვეთ.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'შეეგუეთ უძილობას 😭', 'შუაღამისას გაიღვიძა და დაძინება არ სურს. ნუ გაუბრაზდებით. გაარკვიეთ მიზეზი, მოეფერეთ და აგრძნობინეთ, რომ მის გვერდით ხართ.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'მოთმინება კრიზისულ მომენტში 🛒', 'მაღაზიაში ყვირის, რადგან სასურველი სათამაშო არ უყიდეთ. გარშემო მყოფი „იდეალური მშობლების“ მზერას ყურადღებას ნუ მიაქცევთ. მშვიდად დაამყარეთ თვალით კონტაქტი, აუხსენით და თქვენს გადაწყვეტილებაზე მყარად იდექით.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', '31-ე თვეზე გადასვლა!  🎉', 'ის უკვე ბავშვობის ყველაზე ინტელექტუალურ და, ამავდროულად, ყველაზე რთულ ეტაპზეა. მისი ყოველი წინადადება და ყოველი შეკითხვა თქვენთვის დიდი აღმოჩენაა.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'ტაშის დაკვრის სიხარული 👏', 'როცა რამეს ახერხებს, საკუთარ თავს ტაშს უკრავს და ამაყობს? მას თქვენი მოწონება სურს! თქვენც დიდი სიხარულით აღნიშნეთ მისი ეს პატარა წარმატება და წაახალისეთ.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'კითხვა გაქვთ? 🤖', '2.5 წლის შემდეგ ბავშვის სიმაღლისა და წონის გრაფიკი გაშფოთებთ? ინტერნეტში შემაშინებელი სტატიების კითხვის ნაცვლად, მიიღეთ ზუსტი და მეცნიერულად დასაბუთებული ინფორმაცია Anacan AI-სგან.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'მამის უცნაური ხმები 🤡', 'როცა თქვენი მცდელობები აღარ ჭრის, მამის მიერ გამოცემული უცნაური ხმები სიტუაციას იხსნის. საღამოს ჭირვეულობის დროს საქმე მაშინვე მას გადააბარეთ, თქვენ კი გვერდიდან ღიმილით უყურეთ.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'ღამის მელოდია 🛀', 'მთელი დღის სირბილმა ისიც დაღალა და თქვენც. თბილი აბაზანა და ფონად ჩართული მსუბუქი, ნაზი მელოდია მის ნერვულ სისტემას სრულად დაამშვიდებს.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'სურათებს აზრს ანიჭებს 📖', 'როცა წიგნში ცხოველებს ან ბავშვებს ხედავს, მათ ეხება და გეკითხებათ: „რას აკეთებს?“ მისი მხედველობითი აღქმა გასაოცარია. მოუყევით ვრცელი და საინტერესო ამბები ამ პერსონაჟების შესახებ.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'დრო დედისთვის 🥑', 'ყოველდღიურ აურზაურში სადილი ფეხზე მდგომმა არ მიირთვათ. ჯანსაღი რეცეპტებიდან აირჩიეთ ენერგიის მომცემი წასახემსებელი, სულ მცირე 10 წუთით დივანზე მოკალათდით და საკუთარ კვებას პრიორიტეტი მიანიჭეთ.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'ჩურჩულით საუბრები 🌙', 'ოთახში სინათლე მთლიანად ჩააქრეთ. გვერდით მიუწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ჩურჩულით უამბეთ. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი საუკეთესო მეთოდია.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'რკინა და ენერგია 🥩', 'ფერმკრთალია ან სწრაფად იღლება? ხორცთან ერთად ლიმონიანი ან პომიდვრიანი სალათი მიეცით, რათა რკინის შეწოვა გაუმჯობესდეს.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'სიების ძალა 🛒', 'მაღაზიაში წასვლისას ყოველთვის რაღაც გავიწყდებათ? საყიდლების სია აპლიკაციაში გელოდებათ. საჭირო პროდუქტები იქ ჩაინიშნეთ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ყველაფერი ზუსტად იყიდოს.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'ჩაიწერეთ თქვენი ემოციები 📝', 'ვინმეს არ ესმის თქვენი? ვერავინ ამჩნევს თქვენს დაღლილობას? განწყობის დღიური საუკეთესო მესაიდუმლეა. ჩაწერეთ იქ მთელი თქვენი სტრესი, ტკივილი და მარტოობის განცდა და ნახავთ, რამდენად სწრაფად იგრძნობთ შვებას.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'ჩემია 🧸', 'თქვენი ბავშვი სტუმრად მოსულ ბავშვს საკუთარ სათამაშოს არ აძლევს? ეს ეგოიზმი კი არა, პირადი საზღვრების დაცვაა. გაზიარება იძულებით კი არა, საკუთარი მაგალითით ასწავლეთ.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'თავისუფალი თამაში 🧸', 'არ ხართ ვალდებული, ყოველ წუთს გაართოთ ან თამაშები მოუფიქროთ. მოწყენილობა ბავშვებში შემოქმედებითობის საწყისია. მიეცით საშუალება, ოთახში დამოუკიდებლად აღმოაჩინოს რაიმე ახალი.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'დასვრაზე სრული ნებართვა 🏖️', 'ტალახით ან წყლით თამაში სურს? მიეცით დასვრის უფლება! ამ სენსორული განვითარების ხელშემწყობი აქტივობებისთვის ადვილად გასაწმენდი ნივთები რეკომენდებულ პროდუქტებში იპოვეთ.'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'გაფილტრეთ ხმები 🤫', 'ჩაძინებისას მისი მგრძნობელობა იმატებს. ფანჯრიდან შემოსული ხმების გასანეიტრალებლად ოთახში მსუბუქი თეთრი ხმაურის (white noise) მოწყობილობა ან ბუნების ხმები ჩართეთ.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'დაბლა ჩაიხედეთ — რას აღმოაჩენს? 👣', 'მას უკვე სიამოვნებს ფეხშიშველი სიარული და ხალიჩასთან ან ოთახში განთავსებულ ქვებთან შეხება. ტერფებზე არსებული ნერვული დაბოლოებების სტიმულირება მისი წონასწორობისა და მოტორული უნარებისთვის ძალიან მნიშვნელოვანია.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც თამაშია საჭირო, არც წიგნი და არც ზღაპარი. ამ საღამოს უბრალოდ გულში ჩაიკარით, შეიგრძენით მისი სურნელი და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'გამოცდილების გაზიარება 💬', 'ბავშვის ყველაფრის გაჯიუტებამ შეგაშინათ? ინტერნეტში შემაშფოთებელ სტატიებს ნუ მოძებნით. ისარგებლეთ Anacan-ის საზოგადოებაში გამოცდილი დედების რეალური გამოცდილებით.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'მიზანმიმართული სირბილი 🐢', 'სიარული აღარ ჰყოფნის — სწრაფად გარბის და გემალებათ. ოთახიდან სახიფათო დაბრკოლებები მოაშორეთ და თქვენც დიდი ენერგიით ჩაერთეთ ამ დაჭერობანას თამაშში.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'მამის ზღაპარი 📖', 'ამ საღამოს თქვენს ხმას დასვენების საშუალება მიეცით. ბავშვის საყვარელი წიგნების სხვადასხვა ხმითა და სახალისოდ წაკითხვა მამას მიანდეთ.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'მტკიცე „არა“ იწყება 🛑', 'როდესაც ვინმეს მისი კოცნა სურს, თავს არიდებს და მტკიცედ ამბობს „არას“? პატივი ეცით მისი სხეულის საზღვრებს. უნებართვო შეხების გაპროტესტება მომავალში თავდაჯერებულობისთვის აუცილებელია.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'როცა დედა იღლება 🛑', 'თქვენ რკინისგან არ ხართ. თუ დღეს საჭმლის მომზადების ძალა არ გაქვთ, მოხარშეთ მაკარონი ან საკვები გამოიძახეთ. იდეალური დედობა ყველაფრის მარტო კეთებას არ ნიშნავს.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'შეკრულობის სიგნალი 💩', 'ბევრს დარბის, მაგრამ წყლის დალევა ავიწყდება? ქოთანში განავალს დააკვირდით. მენიუს აუცილებლად დაამატეთ ბოჭკოვანი შვრია და ქლიავი.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'დაუსრულებელი შოუ საწოლში 🛌', 'ძილის ნაცვლად საწოლზე ხტუნავს და დარბის? ჩართეთ ძილის ტაიმერი და სიყვარულით დაიცავით საზღვრები. თეთრი ხმებიდან ტყის შრიალი ჩართეთ და ოთახი მშვიდ ძილის ზონად აქციეთ.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'კალციუმის ფარი 🦴', 'რძეს არ სვამს? ძვლებისთვის კალციუმი აუცილებელია. კვების კონტროლის ხელსაწყოთი გამოთვალეთ, რამდენი ყველი, იოგურტი ან ბროკოლი მიიღო დღეს და შეავსეთ დანაკლისი.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა არ მოგატყუოთ და ბავშვი არ გააციოთ. მხოლოდ ფანჯრიდან გახედვით ნუ გადაწყვეტთ — ამინდისა და ჩაცმულობის დამხმარის საშუალებით შეარჩიეთ გარეთ არსებული პირობებისთვის ყველაზე შესაფერისი სამოსი და ისე გადით სახლიდან.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'ღამის ქარიშხალი 😭', 'შუაღამისას თითქოს უმიზეზოდ ტირილით გაიღვიძა? გაზები აწუხებს თუ უბრალოდ ღამის შიშია? მშვიდად ჩაიხუტეთ და ხმის აუწევლად დაამშვიდეთ, რათა კვლავ ჩაეძინოს.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'განშორების შიში 🥺', 'ტუალეტშიც კი რომ შედიხართ, კარს უკან გელოდებათ და ტირის. განშორების შფოთვა ზოგჯერ მძაფრდება. ყოველ ჯერზე გამოეხმაურეთ და უთხარით, რომ აქ ხართ და მალე დაბრუნდებით.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'ახალი მეგობრების ძიება 👫', 'პარკში თანატოლებთან ერთად სირბილსა და მათთან მიახლოებას ცდილობს? სოციალიზაცია ოფიციალურად დაიწყო! უსაფრთხო დისტანციიდან თვალი ადევნეთ და სიამაყით უყურეთ მის პირველ მცდელობებს.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'პიჟამასთან ჭიდილი 👕', 'საღამოს ჩაცმა დიდ ომად იქცევა? არჩევანი მას დაუტოვეთ: წითელი პიჟამა გინდა თუ ლურჯი? ეს პატარა ხრიკი აგრძნობინებს, რომ გადაწყვეტილებას თავად იღებს.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'სიმშვიდის საათი ☕', 'თუ დღისით აღარ სძინავს, მინიმუმ 1-საათიანი სიმშვიდის საათი (quiet time) დაუწესეთ. მან თავის საწოლში წიგნი ფურცლოს, თქვენ კი ჩაი მიირთვით და გონება განიტვირთეთ.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'ურჩხული სიბნელეში 🌌', 'შუქის ჩაქრობისას ჩრდილების ეშინია? წარმოსახვის განვითარებასთან ერთად შიშებიც უფრო რეალური ხდება. თეთრი ხმებიდან ჩაურთეთ დედის საშვილოსნოს ხმა და აგრძნობინეთ ის უძველესი სიმშვიდე და დაცულობა, რომელიც ასე სჭირდება.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'უეცარი ცრემლები 😭', 'თვალის გახელისთანავე უმიზეზოდ ტირის? გაესაუბრეთ ჩვენს Anacan AI ექსპერტს და გაიგეთ, როგორ დაამშვიდოთ ემოციებით გადატვირთული პატარა მშვიდად და თავდაჯერებულად.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'სუფთა ჰაერი სჭირდება 🌳', 'ოთხ კედელში ყოფნა მასაც აწუხებს და თქვენც? სანამ ყველაფერი თავდაყირა დადგება, დედებისთვის მეგობრულ ადგილებში იპოვეთ ახლომდებარე პარკი. სუფთა ჰაერი ორივესთვის საუკეთესო წამალია.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'მეც დაგეხმარებით! 🧹', 'როცა იატაკს წმენდთ ან მტვერს იღებთ, ცდილობს ნივთი ხელიდან გამოგართვათ? ის თავს უკვე დიდად გრძნობს. მიეცით პატარა ტილო და მიეცით საშუალება, თქვენს გუნდს შეუერთდეს და განვითარდეს.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'ენერგიის დახარჯვა აუცილებელია 🌳', 'ოთხ კედელში ყოფნა მას აგრესიულს ხდის. ჩასვით ეტლში ან ხელი მოჰკიდეთ და სუფთა ჰაერზე გაიყვანეთ. ბუნების სიმშვიდე შესანიშნავად იმოქმედებს როგორც ბავშვზე, ისე თქვენს ფსიქოლოგიურ მდგომარეობაზე.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'სიბნელესთან შეგუება 🌙', 'დაძინება რომ გაუადვილდეს, ოთახში ყველა დამატებითი სინათლის წყარო, განსაკუთრებით კი პლანშეტის ეკრანი, გამორთეთ. მელატონინი მხოლოდ ბნელ გარემოში გამოიყოფა.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'ბალიშების ციხესიმაგრე 🏰', 'ამ საღამოს ოთახი სათამაშო მოედნად აქციეთ. დივნის ბალიშებით პატარა ციხესიმაგრე ააშენეთ და შიგნით შეძვერით. ცოტა არეულობა იქნება, მაგრამ ეს მხიარული სიცილი ნამდვილად ღირს ამად.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'დაჟინებით თავად ჭამს 🥄', 'კოვზს იღებს და ყველაფერს სვრის? ჩართეთ კვების ტაიმერი. დაყრილ საკვებზე კი ნუ იდარდებთ, არამედ იამაყეთ მისი მზარდი დამოუკიდებლობითა და თავდაჯერებულობით.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'დილის ჭირვეულობა ☁️', 'თვალის გახელისთანავე ყველაფერზე ტირის და არაფერი მოსწონს? შესაძლოა, სწორედ ზრდის ნახტომის შუა ეტაპზე იყოს. ხშირად ჩაეხუტეთ და თავი უსაფრთხოდ აგრძნობინეთ — ასე დღესაც გადაარჩენთ.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'მამის ღამის მორიგეობა 👨‍🍼', 'დღის განმავლობაში დაღლაც საკმარისია თქვენთვის. საღამოს ბავშვის დასაძინებლად მომზადება და პიჟამის ჩაცმა მამას მიანდეთ, თავად კი უბრალოდ გვერდიდან უყურეთ.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'სიტყვების გამეორება 🗣️', 'თქვენ მიერ წარმოთქმულ ყოველ ახალ სიტყვას თუთიყუშივით მაშინვე იმეორებს? მისი ლექსიკური მარაგი მდიდრდება. განსაკუთრებული ყურადღება მიაქციეთ მის გვერდით ნათქვამ სიტყვებსა და გამოხატულ ემოციებს — ის ყველაფერს იმეორებს.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'დამალეთ ბოსტნეული 🥦', 'კვლავ შეამჩნია წვნიანში სტაფილოს პატარა ნაჭერი და ჭამაზე უარი თქვა? კვების გეგმის დახმარებით ბოსტნეულის პიურედ ქცევა და კატლეტში დამალვა დედების ერთ-ერთი უძველესი და სასარგებლო ხრიკია.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'შეეგუეთ უძილობას 😭', 'შუაღამისას იღვიძებს და დაძინება აღარ სურს. ნუ გაუბრაზდებით. გაარკვიეთ მიზეზი (ტკივილი, აირები, შიში), მოთმინებით ჩაიხუტეთ და დაელოდეთ, სანამ ისევ ჩაეძინება.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'ჯიუტი ლაქები 👗', 'ტანსაცმელზე მუდმივად გაჩენილი ლაქები გღლით? ნუ გაბრაზდებით. ბავშვი საკვებს ეცნობა. გამოიყენეთ სილიკონის წინსაფრები და უბრალოდ დატკბით ამ ფერადი, არეული მომენტებით.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'მეგობარი სარკეში 👀', 'მიიყვანეთ სარკესთან. დააკვირდით, როგორ უყურებს გაოცებული საკუთარ ანარეკლს და როგორ იღებს სხვადასხვა გამომეტყველებას. ეს შესანიშნავი აქტივობაა საკუთარი თავის აღქმის გასავითარებლად.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'მუსიკით ძილისთვის მომზადება 🛀', 'საღამოს რუტინა გართულდა? თბილი აბაზანის მიღებისას ფონად დამამშვიდებელი მუსიკა ჩართეთ. წყლისა და მელოდიის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ამშვიდებს.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'კბილების გახეხვის ბრძოლა 🦷', 'კბილის ჯაგრისს პირთან არ გაკარებინებთ? იძულების ნაცვლად, ეს თამაშად აქციეთ. მიეცით საშუალება, ჯერ თქვენი კბილები გახეხოს, შემდეგ კი თქვენი ჯერი დადგეს.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'საჭმელზე უარის თქმა 🥣', 'ორ კოვზს შეჭამს, გეუბნებათ, რომ დანაყრდა და გარბის? ნუ დააძალებთ. საკვებთან ჯანსაღი ურთიერთობის ჩამოყალიბება უფრო მნიშვნელოვანია, ვიდრე ძალით კვება. კვების სიხშირე გაზარდეთ, ულუფები კი შეამცირეთ.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'ჰორმონების ქარიშხალი 🩸', 'უეცრად ტკბილეული მოგინდათ და გაღიზიანებული ხართ? შეამოწმეთ მენსტრუაციის ტრეკერი. შესაძლოა, ეს PMS-ია. თავს ნუ დაიდანაშაულებთ — ჯანსაღ რეცეპტებში მოძებნეთ მაგნიუმითა და ფინიკით მომზადებული წასახემსებელი და ასე დაეხმარეთ თქვენს ორგანიზმს.'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'უმიზეზო დილის კრიზისები 🛑', 'თვალის გახელისთანავე ყველაფერზე ყვირის და ტირის? გაესაუბრეთ ჩვენს Anacan AI ექსპერტს და ახლავე გაიგეთ, როგორ დაამშვიდოთ ემოციებით გადატვირთული პატარა მშვიდად.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'ზღაპრის დასასრული მან თქვას 📖', 'დღეს საღამოს, ზღაპრის კითხვისას, წინადადებები დაუსრულებელი დატოვეთ და მიეცით ბავშვს მათი დასრულების საშუალება! ჰკითხეთ Anacan AI-ს დიალოგის იმ გზების შესახებ, რომლებიც ენის საოცარ განვითარებას უწყობს ხელს.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'დასვრის სრული ნებართვა 🏖️', 'ტალახით ან წყლით თამაში სურს? მიეცით დასვრის უფლება! სენსორული განვითარების ხელშემწყობი ამ აქტივობებისთვის ადვილად გასაწმენდი ნივთები რეკომენდებულ პროდუქტებში იპოვეთ.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'რეჟიმის ანალიზი ⏱️', 'საღამოს დაძინებას 1 საათი სჭირდება? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, უკვე დიდი ხანია დროა, დღის ძილი შეამციროთ და საღამოს დაძინების დრო უფრო ადრე გადმოწიოთ.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'დალაგება ერთად 🧹', 'სახლია დასალაგებელი? სანამ ოთახს გვით, მიეცით ბავშვს ტილო და საშუალება, წმენდით დაგეხმაროთ. ბლოგებში წაიკითხეთ, როგორ აქციოთ ერთად დალაგება სახალისო თამაშად.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'შუაღამის ყვირილი 🤖', 'შუაღამისას ყვირილით იღვიძებს და ვერ გცნობთ? ეს შესაძლოა ღამის ტერორი იყოს. დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ მოიქცეთ სწორად და რატომ არ უნდა გააღვიძოთ ბავშვი.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', '„რატომ?“ არ მთავრდება 🤔', 'მას სამყაროს შეცნობა და ყველაფერში ლოგიკის პოვნა სურს. Anacan AI-სგან გაიგეთ, როგორ უპასუხოთ მის დაუსრულებელ კითხვებს მოთმინებით ისე, რომ არ დაიღალოთ. თქვენი მოთმინება მისი მომავალია.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'უფლება, ყავა ცხელი დალიოთ ☕', 'ოთახი არეულია? დატოვეთ, როგორც არის. საკუთარ თავს 10 წუთი დაუთმეთ და ის ყავა, ბოლოს და ბოლოს, ცხელი დალიეთ. თქვენ არ ხართ ვალდებული, იდეალური იყოთ.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'ფარულად მირთმეული შოკოლადი 🍫', 'სამზარეულოში გახვედით და მისგან მალულად, ფეხზე დგომისას, რაიმე ტკბილი მიირთვით? თავს ნუ გაკიცხავთ. დღის ხმაურთან გასამკლავებლად დედას სრული უფლება აქვს, სისხლში შაქრის დონე აიმაღლოს.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'სცენა მამას ეკუთვნის 🎭', 'თქვენი ფრაზა „საჭმელი ბოლომდე ჭამე“ უკვე აღარ ჭრის. ახლა ჯერი მამაზეა. როცა ის კოვზს მფრინავ თვითმფრინავად აქცევს, სიჯიუტეც თითქოს სასწაულებრივად ქრება. დაისვენეთ და უყურეთ.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'არასწორი ფერის კოვზის კრიზისი 🥄', 'იმის გამო, რომ საჭმელი მწვანე კოვზის ნაცვლად ყვითელი კოვზით მიეცით, ქვეყანა დაიქცა? ღრმად ჩაისუნთქეთ. ამ სიტუაციაში ლოგიკას ნუ ეძებთ — ბავშვი უბრალოდ ამოწმებს, შეუძლია თუ არა სამყაროს მართვა. უბრალოდ შეუცვალეთ კოვზი და გაუღიმეთ.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', 'დაგეხმარები 🧽', 'როცა მტვერს წმენდთ, ხელიდან ტილოს გტაცებთ? მას სურს, თავი დიდად იგრძნოს. მიეცით პატარა, ნესტიანი ტილო. დალაგების ნაცვლად შეიძლება უფრო მეტად დასვაროს, მაგრამ თავს მნიშვნელოვნად იგრძნობს.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'სახლის აკუსტიკა 🤫', 'შუადღისას ძლივს დაიძინა. ახლა სახლში უმცირესმა ხმაურმაც კი შეიძლება ჭკუიდან გადაგიყვანოთ. დაუყოვნებლივ ჩართეთ ხმის საზომი, დახურეთ ფანჯრები და დატკბით ამ სრული სიჩუმით.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'ფეხსაცმლის ჩაცმის ომი 👟', 'მარჯვენა ფეხსაცმელი მარცხენა ფეხზე ჩაიცვა და არაფრით უნდა გახდა? დატოვეთ, როგორც არის. ამ ეტაპზე გარეგნული სილამაზე ან სისწორე მისთვის თავისუფლების განცდაზე მნიშვნელოვანი არ არის.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'სიბნელესთან დამეგობრება 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. გვერდით მიუწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ჩუმად, ჩურჩულით მოუყევით. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი ყველაზე ბუნებრივი საშუალებაა.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'პატარა მხატვარი 🎨', 'ფანქრით კედელზე ან ქაღალდზე წრეებს ხატავს? ეს მოტორული განვითარების მნიშვნელოვანი წინსვლაა.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'საბავშვო ბაღის ძებნას იწყებთ? 🏫', 'სამი წლის ასაკის მოახლოებასთან ერთად საბავშვო ბაღზე ფიქრობთ? თუ მარტო ფიქრით დაიღალეთ, შეუერთდით Anacan-ის საზოგადოებას და სხვა დედებს გამოცდილება და რეკომენდაციები ჰკითხეთ.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'წარმოსახვითი ჩაის სუფრა ☕', 'ცარიელ ფინჯანს გიწვდით და გეუბნებათ, ჩაი დალიეთო? სიმბოლური თამაშები ბავშვის განვითარების ნამდვილი შედევრია. დიდი სიამოვნებით მიირთვით ფინჯანში ჩასხმული, ოთახის ტემპერატურის წარმოსახვითი ჩაი.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'ტანსაცმელი სულ დალაქავებულია 🎨', 'პიჟამა საკვებითაა დალაქავებული, ტანსაცმელი კი — საღებავით? ბავშვები სისუფთავის დაცვით კი არ უნდა იზრდებოდნენ, არამედ გარემოს აღმოჩენისას უნდა ისვრებოდნენ. გამოიყენეთ სილიკონის წინსაფრები, დანარჩენი კი სარეცხ მანქანას მიანდეთ.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', '15-წუთიანი გაქცევა 🛀', 'ტუალეტში შეხვედით, კარი ჩაკეტეთ და უბრალოდ ტელეფონს უყურებთ? დიახ, ეს დედების გაქცევისა და დასვენების ყველაზე ცნობილი მეთოდია. დარჩით ამ სიმშვიდეში ისე, რომ არავის წინაშე არ მოგიწიოთ თავის მართლება.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', 'მტკიცე „ნუ მკოცნი!“ 🛑', 'როცა რომელიმე ნათესავი მის კოცნას ცდილობს, ბავშვი სახეს აბრუნებს და ხელს ჰკრავს? ნუ დაარღვევთ მის პირად საზღვრებს! უნებართვო შეხების გაპროტესტება მისი ჯანსაღი მომავლისთვის აუცილებელია.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'ღამის ტერორის რეალობა 😭', 'შუაღამისას თვალდახუჭული და ტირილით იღვიძებს და არავის ხმა არ ესმის? ეს ღამის ტერორია. ნუ შეანჯღრევთ და ნუ ეცდებით მის გაღვიძებას. უბრალოდ მის გვერდით იყავით და უსაფრთხოების განცდა შეუქმენით.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'ბუნებაში განტვირთვა აუცილებელია 🌳', 'დღეს სახლში ქაოსი აუტანელი გახდა? დაუყოვნებლივ შეამოწმეთ ამინდისა და ჩაცმულობის ხელსაწყო, შესაბამისად მოემზადეთ და უახლოეს პარკში გაიქეცით. სუფთა ჰაერი ბავშვისთვის საუკეთესო დამამშვიდებელია.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'სიტყვების ახალი ვერსია 🗣️', '„წყლის“ ნაცვლად „წალს“, „დიდის“ ნაცვლად კი „დილს“ ამბობს? ისე საყვარლად ჟღერს, რომ სიცილის შეკავება რთულია. თუმცა ყოველ ჯერზე თბილად გაუმეორეთ სიტყვის სწორი ფორმა, რათა მისმა ტვინმა სწორედ ის დაიმახსოვროს.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'ზღაპრის დასასრული თავად მოიფიქროს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. ამჯერად ჭკვიან ზღაპრებში ამბის დასასრული თქვენს ბავშვს აარჩევინეთ. ჰკითხეთ: „როგორ ფიქრობ, ვინ დაეხმარა იმ გმირს?“ — და მისი ფანტაზია გააღვიძეთ.'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'როცა ენერგია გელევათ 🔋', 'დღეს არაფრის ძალა არ გაქვთ? ჯანსაღი რეცეპტებიდან 5 წუთში მოამზადეთ ბლენდერში ათქვეფილი, რკინითა და ვიტამინებით მდიდარი სმუზი და გზადაგზა დალიეთ. იზრუნეთ საკუთარ თავზე.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'საყიდლების სია თქვენი მხსნელია 🛒', 'საკუთარ მეხსიერებას მიენდეთ, მაღაზიაში წახვედით და ბავშვის საფენების გარეშე დაბრუნდით? ასეც ხდება. მიეჩვიეთ ყველა საჭირო ნივთის საყიდლების სიაში ჩაწერას და მიეცით აპს საშუალება, თქვენს ნაცვლად შეგახსენოთ.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'მოულოდნელი დრო წყვილისთვის 🥂', 'ბავშვს მოულოდნელად ადრე ჩაეძინა! ამ იშვიათ წუთებს სახლის დალაგებაზე ნუ დახარჯავთ. თქვენს პარტნიორთან პირისპირ დაჯექით, ტელევიზორი გამორთეთ და უბრალოდ ჰკითხეთ ერთმანეთს, როგორ ჩაიარა დღემ.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'ფაზლების ინჟინერია 🧩', 'ბავშვი დაჟინებით ცდილობს ფორმების შესაბამის ჭრილებში მოთავსებას. მაშინაც კი, თუ შეცდება ან გაბრაზდება, მაშინვე ნუ დაეხმარებით. პრობლემების გადაჭრის უნარს სწორედ ცდისა და შეცდომის გზით ივითარებს.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'განშორების შფოთვა 🥺', 'ოთახიდან რამდენიმე წამითაც რომ გახვიდეთ, თქვენს უკან ტირის. განშორების შფოთვა ზოგჯერ კვლავ იჩენს თავს. ყოველ ჯერზე შორიდან გამოეხმაურეთ და აგრძნობინეთ, რომ იქვე ხართ — უთხარით: „სამზარეულოში ვარ, მალე მოვალ“.'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'სრულყოფილების წნეხი 🛑', 'სხვა ბავშვები უკვე ფერებს ითვლიან, თქვენს ბავშვს კი ეს არ სურს? დაუყოვნებლივ შეწყვიტეთ შედარება! ყველა ბავშვი თავისი ტემპით ვითარდება. თქვენი ბავშვიც საკუთარი ტემპით წინ მიიწევს და ეს სრულიად ნორმალურია.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'მამის საიდუმლო ტაქტიკა 👨‍🍼', 'დღის განმავლობაში ისედაც საკმარისად იღლებით. საღამოს ბავშვის დასაძინებლად მომზადება და კბილების გახეხვა მამას და მის თამაშით სავსე მიდგომას მიანდეთ, თქვენ კი მშვიდად ჩამოჯექით და ჩაი მიირთვით.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'პედიატრიული ეჭვები 🤖', '32 თვის ბავშვის სიმაღლისა და წონის გრაფიკმა მოულოდნელად შეგაშფოთათ? ინტერნეტფორუმებზე საშიში დაავადებების ძებნას ნუ დაიწყებთ — ზუსტი და მეცნიერულად დასაბუთებული ინფორმაცია Anacan AI-სგან მიიღეთ.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'ძილის ბუნებრივი გარემო 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ის დროა, როდესაც ტვინი ყველაზე მგრძნობიარეა. ფანჯრიდან შემოსული ხმების გასანეიტრალებლად ოთახში ჩართეთ თეთრი ხმაურის მოწყობილობა დაბალ ხმაზე (მაგალითად, წვიმის ხმით).'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'მე აგიხსნით! ☝️', 'ყველაფერზე თითით მიგითითებთ და ზედიზედ გისვამთ კითხვებს. მას სურს, რომ სამყარო სიტყვებით აღუწეროთ. ეს კომუნიკაციის უნარის განვითარებაში დიდი ნახტომია! მიუხედავად დაღლილობისა, საგნების სახელები მოთმინებით გაუმეორეთ.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'მამას პარკის დაზვერვა 👨‍👧', 'დედობა 24/7-ზე მორიგეობა არ არის! დღევანდელი გასეირნება მამას მიანდეთ. მიეცით საშუალება, ერთად ამოიგანგლონ ტალახში, თქვენ კი დივანზე წამოწექით და სიჩუმით დატკბით.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'სიმაღლისა და წონის ნახტომი 📏', 'შარვლები ისევ დაუმოკლდა? ის ყოველდღე თქვენს თვალწინ იზრდება! განვითარების ტრეკერში მიმდინარე მონაცემები შეიყვანეთ და სიამაყით შეხედეთ ზრდის მრუდს — თქვენი უძილო ღამეების შედეგს.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'კლასიკური მუსიკის სასწაული 🎶', 'საღამოობით უმიზეზო გაღიზიანება დაიწყო? გამორთეთ ტელევიზორი, ჩააქრეთ მკვეთრი განათება და ოთახში ძალიან ხმადაბლა ჩართეთ კლასიკური მუსიკა. სიმშვიდისა და მუსიკის ჰარმონია ატმოსფეროს შეცვლის.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'სუპში დამალული აგენტები 🥦', 'ყველაფერს, რაც მწვანეა, ბოიკოტი გამოუცხადა? ნუ ღელავთ. კვების გეგმის ფარგლებში ბოსტნეულის პიურედ ქცევა და კატლეტებსა თუ სოუსებში დამალვა დედების ერთ-ერთი უძველესი და სასარგებლო ხრიკია.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'გამოგონილი სიმღერები 🎤', 'სათამაშოების დალაგებისას თავისთვის არცერთ ენაში არარსებული სიტყვებით მღერის. მისი ლექსიკური მარაგი და რიტმის შეგრძნება ერთდროულად ვითარდება. განვითარების ტრეკერში ეს ახალი მუსიკალური ეტაპიც აუცილებლად დაამატეთ.'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'ჯიუტი პიჟამა 👕', 'ჩაცმა დიდ ომად იქცა? არჩევანი მას დაუტოვეთ: წითელი პიჟამა გინდა თუ ლურჯი? ეს პატარა ხრიკი აგრძნობინებს, რომ გადაწყვეტილებას თავად იღებს, და წინააღმდეგობას შეწყვეტს.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც თამაშია საჭირო, არც წიგნი და არც ზღაპარი. ამ საღამოს უბრალოდ გულში ჩაიკარით, მისი საამო სურნელი ღრმად შეისუნთქეთ და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია ის თქვენთვის.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'ერთად დალაგება 🧹', 'სახლია დასალაგებელი? როცა ოთახს გვით, მიეცით მასაც ტილო და საშუალება, რომ წმენდაში დაგეხმაროთ. ბლოგებში წაიკითხეთ, როგორ აქციოთ დალაგება გუნდურ საქმიანობად და გართობად.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'ძალიან დავიღალე 🔋', 'ყველა თქვენგან ენერგიას ელის, მაგრამ თქვენი ელემენტი უკვე დაცლილია. დღეს ნურაფერს მოამზადებთ — საჭმელი შეუკვეთეთ. იდეალური დედობა არ ნიშნავს, რომ ყველაფერი მარტო უნდა გააკეთოთ. მიეცით საკუთარ თავს ამის უფლება.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'წრიდან ფორმამდე 🎨', 'ფანქრით კედელზე ან ქაღალდზე წრეებს ხატავს? ეს ცელქობა სინამდვილეში მოტორული განვითარების დიდი ნახტომია.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'წყლის ჰარმონია 🛀', 'მთელი დღე სირბილმა თქვენც დაგღალათ და ისიც. თბილი აბაზანის მიღებისას ფონად ბუნების დამამშვიდებელი ხმები ჩართეთ. წყლის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ძილისთვის მოამზადებს.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'ტანტრუმი მაღაზიაში 🛒', 'სალაროსთან ტკბილეულის გამო ყვირის? გარშემო მყოფების განმკითხველ მზერას ყურადღებას ნუ მიაქცევთ. მშვიდად დაამყარეთ თვალით კონტაქტი, აუხსენით წესი და მტკიცედ დაიცავით თქვენი გადაწყვეტილება.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'სახლის საქმეებს ვინ გააკეთებს? 🌪️', 'საქმეები დაუმთავრებელი რჩება? დარჩეს. სთხოვეთ თქვენს პარტნიორს, დღეს სახლის საქმეები საკუთარ თავზე აიღოს. თქვენ კი დაისვენეთ — ამ სახლში ყველაზე მნიშვნელოვანი და ენერგიის აღდგენის ყველაზე მეტად მომთხოვნი ადამიანი ხართ.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'გუნდური მხარდაჭერა 🥂', 'რთული დღე უკან მოიტოვეთ. როცა ბავშვი დაიძინებს, პარტნიორთან ერთად ჩაი დაისხით და ერთმანეთი გაამხნევეთ სიტყვებით: „ჩვენ ამას მართლაც შესანიშნავად ვუმკლავდებით“.'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'სურათებს აზრს სძენს 📖', 'როცა წიგნში პერსონაჟებს ხედავს, მათ ეხება და კითხულობს: „ეს რას აკეთებს?“ მისი ვიზუალური აღქმა გასაოცარია. ერთად მოიფიქრეთ წიგნისთვის ახალი, სრულიად გამოგონილი დასასრული.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'დალაგების სინდრომი 🌪️', 'სახლი დაალაგეთ და დაასუფთავეთ, მაგრამ 10 წუთის შემდეგ ყველაფერი ისევ აფეთქების ადგილს ჰგავს? დღეს უწესრიგობას დანებდით. მოკალათდით დივანზე და სანამ ყავას არ დაასრულებთ, ადგილიდან არ ადგეთ.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'მამის დიპლომატიური გამოსავალი 👨‍👧', 'თქვენი ფრაზა „საჭმელი ბოლომდე შეჭამე“ აღარ ჭრის? ჯერი მამაზე მიდგა. როგორც კი ის კოვზს მფრინავ კოსმოსურ ხომალდად აქცევს, სიჯიუტე რაღაც სასწაულით ქრება. დაისვენეთ და სცენას უყურეთ.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'დილის ადვოკატი საქმეშია 💼', 'ამ მაისურს არა, იმას ჩავიცვამ! ოთახში უკვე ბავშვი კი არა, პატარა ადვოკატია, რომელიც თქვენთან პროფესიონალურ მოლაპარაკებას აწარმოებს. ნუ შეეკამათებით — უბრალოდ 2 არჩევანი შესთავაზეთ და შეუქმენით ილუზია, რომ გადაწყვეტილებას თავად იღებს.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'ძილის რეჟიმი იცვლება? 😭', 'შუაღამისას გაიღვიძა და დაძინება აღარ სურს. ნუ გაუბრაზდებით. გაარკვიეთ მიზეზი, მოეფერეთ და აგრძნობინეთ, რომ მის გვერდით ხართ, შემდეგ კი დაელოდეთ, სანამ ძილს მიეცემა.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა არ მოგატყუოთ და ბავშვი არ გააციებინოთ. გადაწყვეტილებას მხოლოდ ფანჯრიდან გახედვით ნუ მიიღებთ — ამინდისა და ტანსაცმლის დამხმარის მეშვეობით შეარჩიეთ გარეთ ქარისთვის ყველაზე შესაფერისი ჩაცმულობა და სახლიდან მშვიდად გადით.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'თავისუფალი თამაშის სარგებელი 🧸', 'არ ხართ ვალდებული, ბავშვი ყოველ წუთს გაართოთ ან მისთვის თამაშები მოიფიქროთ. მოწყენა ბავშვებისთვის შემოქმედებითობის პირველი საფეხურია. მიეცით საშუალება, ოთახში დამოუკიდებლად აღმოაჩინოს რაიმე ახალი.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'საყიდლების სიიდან გამორჩენილი ნივთები 🛒', 'მაღაზიაში წასვლისას ყველაზე მნიშვნელოვანი ნივთი ყოველთვის გავიწყდებათ? საყიდლების სია აპში გელოდებათ. ჩანიშნეთ იქ ყველაფერი, რაც გჭირდებათ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ზუსტად ის პროდუქტები შეიძინოს.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'სხეულის ენით კომუნიკაცია 🗣️', 'როდესაც ეკითხებით: „წავიდეთ?“, ხელებს მაღლა სწევს, ხოლო თუ რამე არ სურს, თავს მკვეთრად აქნევს. მისი გაგების უნარი წარმოუდგენლად გაიზარდა! ხშირად უპასუხეთ დამადასტურებელი წინადადებებით.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'მუსიკით ძილისთვის მომზადება 🎶', 'სცადეთ, საღამოს უმიზეზო ჭირვეულობა მშვიდი კლასიკური მუსიკით დააწყნაროთ. ხშირად ეს მარტივი, მაგრამ ეფექტური ხერხი სახლში სასწაულს ახდენს და ოთახში სიმშვიდე შემოაქვს.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'ძილის რეჟიმი ირღვევა? ⏱️', 'საღამოს ჩაძინებას 1 საათზე მეტი სჭირდება? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, უკვე დიდი ხანია დროა, დღის ძილი მნიშვნელოვნად შეამციროთ ან საერთოდ გააუქმოთ და საღამოს დაძინების დრო უფრო ადრე გადმოწიოთ.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'ცხოველების მიბაძვა 🐶', 'მხოლოდ ხმებს კი არ გამოსცემს, არამედ ძაღლივით დახოხავს და კატასავით კრუტუნებს? სხეულის ენა და წარმოსახვა ერთმანეთს ერწყმის. თქვენც დიდი ენთუზიაზმით შეუერთდით მას და ერთად ითამაშეთ ხალიჩაზე.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'დღის ძილის კრიზისი 🥱', 'დაწოლა არ სურს და ტირის? 3 წლის ასაკისთვის ზოგი ბავშვი დღის ძილზე უარის თქმას იწყებს. დაძალების ნაცვლად, გამოაცხადეთ „სიმშვიდის საათი“ და შესთავაზეთ, საწოლში სათამაშოებით უბრალოდ ჩუმად ითამაშოს.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'დაძინება არ სურს და სიბნელის ეშინია?', 'ოთახი მთლიანად ჩააბნელეთ და კედელზე ხელებით ფრინველისა და ძაღლის ჩრდილები გამოსახეთ. შიში გართობად აქციეთ და დაეხმარეთ, სიბნელეს დაუმეგობრდეს.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'კვების სიგნალები 🥣', 'ორ კოვზს ჭამს, ამბობს, რომ დანაყრდა და სკამიდან გარბის? ნუ დააძალებთ. საკვებთან ჯანსაღი დამოკიდებულების ჩამოყალიბება ბევრად უფრო მნიშვნელოვანია, ვიდრე თეფშის აუცილებლად ბოლომდე დაცლა. როცა მოშივდება, თავად მოითხოვს.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'ილუსტრირებული ისტორიები 📖', 'წიგნში ცხოველებს ან ბავშვებს რომ ხედავს, ეხება და გეკითხებათ: „რას აკეთებს?“ მისი ვიზუალური აღქმა საოცარია. ერთად მოიგონეთ პერსონაჟების შესახებ საინტერესო და სახალისო ისტორიები.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'ქოთნის გამარჯვება 🚽', 'გრძნობს, რომ ტუალეტში უნდა და თვითონ გარბის ქოთნისკენ? ეს დიდი გამარჯვებაა!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'ზღაპარი მან მოიგონოს 📖', 'დღეს საღამოს წიგნი გვერდზე გადადეთ. ამბავი მან მოყვეს! Anacan AI-ს ჰკითხეთ, როგორ წარმართოთ დიალოგი ისე, რომ მისი საოცარი წარმოსახვის განვითარებას შეუწყოთ ხელი.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'პროტესტი მწვანე ფერის წინააღმდეგ 🥦', 'მწვანილს თეფშიდან ყრის? სუფრას ბრძოლის ველად ნუ გადააქცევთ. ჯანსაღი რეცეპტების განყოფილებაში აღმოაჩინეთ შინ მომზადებული კექსები დამალული ბოსტნეულით და შეუმჩნევლად შეავსეთ ვიტამინების დღიური ნორმა.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'ჩურჩულის მაგია 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. მის გვერდით დაწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ყურში ჩასჩურჩულეთ. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი ყველაზე ბუნებრივი და დამამშვიდებელი მეთოდია.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'ბროკოლის დეტექტივი 🥦', 'თეფშზე მწვანე ბოსტნეულს პოულობს და გვერდზე სწევს? შენიღბვის ხელოვნებაზე გადადით. ჯანსაღი რეცეპტების განყოფილებაში აღმოაჩინეთ ეშმაკური რეცეპტები, რომლებშიც ბოსტნეულს პიურედ აქცევთ და გემრიელ კატლეტებში დამალავთ.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'კომპოზიტორის პირველი კონცერტი 🎤', 'სათამაშოების დალაგებისას განსაკუთრებული რიტმით მღერის სიტყვებს, რომლებიც არცერთ ლექსიკონში არ არსებობს? ნუ შეაჩერებთ ამ ინტელექტუალურ აღმაფრენას — განვითარების ტრეკერში მისი პირველი კომპოზიციის სახით ჩაინიშნეთ.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'ბუნებაში გაქცევის გეგმა ⛅', 'ოთხ კედელში ყოფნამ ისიც გააღიზიანა და თქვენც. შეამოწმეთ ამინდისა და ჩაცმულობის ინსტრუმენტი, სწრაფად მოემზადეთ და პარკისკენ გაეშურეთ. სუფთა ჰაერი პატარას ყველაზე მწვავე კრიზისსაც კი სწრაფად აცხრობს.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'ოქროს სიჩუმე 🤫', 'სახლში ქაოსი როგორც იქნა დასრულდა და ბავშვს ღრმად ჩაეძინა. ჩართეთ ხმის საზომი, შეამოწმეთ ოთახში სიჩუმის დონე (დეციბელებში) და 15 წუთის განმავლობაში არცერთ ეკრანს არ შეხედოთ — უბრალოდ ჩაიძირეთ ამ ოქროს სიჩუმეში.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'ავანგარდული მოდა 👗', 'შარვალი თავზე ჩამოიცვა და ოთახში ამაყად დააბიჯებს? ნუ ჩაერევით. ეს სახალისო ექსპერიმენტები თავისუფლებისა და ინდივიდუალურობის ძიების ნაწილია. დიახ, უცნაურად გამოიყურება, მაგრამ ასეთი მომენტები ძალიან ძვირფასია.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'მეხსიერების დაკარგვა მაღაზიაში 🛒', 'საკუთარ მეხსიერებას მიენდეთ, მაღაზიაში წახვედით და ყველაზე მნიშვნელოვანი ნივთის გარეშე დაბრუნდით? ჩვევად აქციეთ, რომ ყველაფერი, რაც გჭირდებათ, აპლიკაციის საყიდლების სიაში ჩაიწეროთ — დაე, ციფრულმა მეხსიერებამ გიხსნათ.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'უხილავი სტუმრები 👻', 'დივანზე ცარიელ ადგილს უყურებს და რაღაცას ელაპარაკება, უხილავ მეგობარს კი ჩაისაც უსხამს? წარმოსახვითი მეგობრების ეპოქა გაჩაღდა! ახლა უკვე საკუთარი სამყაროს სცენარისტია. ღიმილით უყურეთ ამ წარმოდგენას.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'წყლის ძალა, რომელიც მოგონებებს რეცხავს 🛀', 'მთელი დღის სირბილმა მასაც დაუძაბა ნერვები და თქვენც. თბილი აბაზანა მხოლოდ ჰიგიენა არ არის — ეს წყლის მისტიკური ძალით სარგებლობის საშუალებაა, რომელიც დაძაბულობას ხსნის და დღის უარყოფით ენერგიას ჩამორეცხავს.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'მამის სამზარეულოს მორიგეობა 👨‍🍳', 'დედობა მარტო გასარბენი მარათონი არ არის. შაბათ-კვირის სადილი მამამ მოამზადოს და ბავშვსაც მან აჭამოს, თქვენ კი დივანზე წამოწექით და დამსახურებული შესვენებით დატკბით.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'მხოლოდ მე ვარ ასეთი? 💬', 'ძალიან დაიღალეთ და გგონიათ, რომ თქვენი არავის ესმის? დაუყოვნებლივ მისწერეთ Anacan-ის საზოგადოებას. იქ ათასობით დედა, რომელსაც თქვენნაირად არ სძინავს, თავისი გზავნილით — მეც შენნაირი ვარ — ძალას შეგმატებთ.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'სცენარი მან დაწეროს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. ამჯერად ჭკვიან ზღაპრებში ამბის დასასრული თქვენს ბავშვს აარჩევინეთ. ჰკითხეთ: შენი აზრით, ვინ დაეხმარა იმ გმირს? — და ძილის წინ მისი ფანტაზია აამუშავეთ.'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'დედის საკვების მარაგი 🥗', 'მის დასანაყრებლად 3 განსხვავებული მენიუ მოიფიქრეთ, თავად კი ფეხზე დგომისას წაიხემსეთ? ჯანსაღი რეცეპტებიდან შეარჩიეთ ვიტამინებით სავსე სალათი, რომელიც 10 წუთში მზადდება, და საკუთარ თავზეც იზრუნეთ.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'მამის მიმიკების თეატრი 🤡', 'როცა თქვენი ხრიკები აღარ ჭრის, მამის უცნაური ხმები სიტუაციას მაშინვე შველის. საღამოს ჭირვეულობის დროს პასუხისმგებლობა მას გადააბარეთ და გვერდიდან მხიარულ კისკისს უყურეთ.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'პატარა დამლაგებელი 🧽', 'როცა მტვერს წმენდთ, ხელიდან ტილოს გტაცებთ? მას სურს, თავი დიდად და გუნდის წევრად იგრძნოს. მიეცით ნოტიო ტილო. დალაგების ნაცვლად უფრო აურევს, მაგრამ თავს დაფასებულად იგრძნობს.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'თვალით კონტაქტი აუცილებელია 🥂', 'ბავშვს მოულოდნელად ადრე ჩაეძინა! ამ იშვიათ მომენტს სახლის დალაგებაზე ნუ დახარჯავთ. პარტნიორთან პირისპირ დაჯექით, ტელევიზორი გამორთეთ და უბრალოდ, თვალებში ჩახედეთ ერთმანეთს და ჰკითხეთ, როგორ ჩაიარა დღემ.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'ცოცხალი დიქტოფონი 🎙️', 'თქვენს მიერ შემთხვევით ნათქვამ სიტყვასაც კი თუთიყუშივით მაშინვე იმეორებს? ის თქვენი ცოცხალი სარკეა. ორმაგი ყურადღება მიაქციეთ, რას ამბობთ და რა ემოციებს გამოხატავთ მის გვერდით — ის ყველაფერს იმეორებს.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'ცივი ყავის რეალობა ☕', 'ყავის მომზადებიდან 3 საათის შემდეგ მისი ყინულივით ცივად დალევა დედობის დაუწერელი კანონია. დღეს გამონაკლისი დაუშვით! ბავშვი სათამაშოებთან დამოუკიდებლად დატოვეთ და ყავა 10 წუთში, ჯერ კიდევ ცხელი დალიეთ. თქვენ ამას იმსახურებთ.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'დედის ფარული ქარიშხალი 🩸', 'უეცარი დაღლილობა ან უმიზეზოდ ტირილის სურვილი გაქვთ? გახსენით მენსტრუაციის ტრეკერი. შესაძლოა, PMS-ის ფაზაში ხართ. თავს ნუ დაიდანაშაულებთ — ჯანსაღი რეცეპტებიდან მაგნიუმით მდიდარი წასახემსებელი მოამზადეთ და თქვენს სხეულს მოუსმინეთ.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'ციფრული პედიატრი 🤖', '33 თვის ბავშვის სიმაღლისა და წონის გრაფიკმა მოულოდნელად შეგაშფოთათ? ინტერნეტფორუმებზე საშიში დაავადებების ძებნას ნუ დაიწყებთ — Anacan AI-სგან ზუსტი, მყისიერი და მეცნიერულად დასაბუთებული ინფორმაცია მიიღეთ.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'მოცარტის ეფექტები 🎶', 'საღამოსკენ უმიზეზო აგრესია დაიწყო. გამორთეთ ტელევიზორი, ჩააქრეთ მკვეთრი განათება და ოთახში ძალიან მშვიდი კლასიკური მუსიკა ჩართეთ. წყლისა და მუსიკის ჰარმონია ატმოსფეროს ჯადოსნურად შეცვლის.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'ფრენის გამოცდები 🧗‍♂️', 'დივნიდან ბალიშებზე ხტება. ასე მიზიდულობის ძალასა და საკუთარ გამბედაობას ცდის. აკრძალვის ნაცვლად, ოთახში ხტომისთვის უსაფრთხო სივრცე მოაწყვეთ და მიეცით საშუალება, ენერგია დახარჯოს.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'ღამის ტირილის საიდუმლო 😭', 'ტირილის შეტევები, რომელთა მიზეზსაც ვერ ადგენთ, ძალიან დამღლელია. შეწყვიტეთ ვარაუდების გამოთქმა და ტირილის ანალიზის ხელსაწყოს დახმარებით სცადეთ, ხმის მიღმა დამალული მიზეზი (ტკივილი, დაღლილობა) გაიგოთ და ბავშვი დაამშვიდოთ.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'შენიღბვის ოსტატი 🥦', 'წვნიანში ბოსტნეულს ისე არჩევს და გვერდზე დებს, თითქოს მიკროსკოპით ეძებდეს? ჯანსაღ რეცეპტებში იპოვეთ სოუსების რეცეპტები, რომლებიც ბოსტნეულს შეუმჩნეველს გახდის. შემოქმედებითობა დედის ყველაზე ძლიერი საიდუმლო იარაღია.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'კბილის ჯაგრისების ომი 🦷', 'კბილის ჯაგრისს პირთან არ გაკარებინებთ და თავად სურს გახეხვა? იძულების ნაცვლად, ეს თამაშად აქციეთ. ჯერ მას მიეცით საშუალება, თქვენ გაგიხეხოთ კბილები, შემდეგ კი თქვენი ჯერი იქნება.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'არეულობის ნებართვა 🌪️', 'დაიღალეთ ყოველდღე ერთი და იმავე სათამაშოების ყუთში ჩალაგებით? დღეს ნუ დაალაგებთ! სახლი მუზეუმი კი არა, სიცოცხლით სავსე სივრცეა. ყურადღება არეულობის ნაცვლად თქვენი ბავშვის აღმოჩენებით გამოწვეულ სიხარულზე გაამახვილეთ.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'ახლა მამის ჯერია 👨‍🍼', 'დღისით ისედაც საკმარისად დაიღალეთ. საღამოს ბავშვის დასაძინებლად მომზადება, კბილების გახეხვა და პიჟამის ჩაცმა მამას გადააბარეთ, თავად კი მშვიდად ჩამოჯექით და ჩაი მიირთვით.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'დედა, შემომხედე! 👀', 'როცა ტელეფონს უყურებთ ან სხვა საქმით ხართ დაკავებული, მოდის და თქვენს სახეს თავისკენ ატრიალებს? მას თქვენი სრული ყურადღება სურს. დაამყარეთ თვალით კონტაქტი, რათა აგრძნობინოთ, რომ უსმენთ და ის თქვენთვის მნიშვნელოვანია.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'წინადადებები ზღაპრებად იქცევა 🗣️', 'უკვე აერთიანებს სიტყვებს და სასაცილო, გამოგონილ ამბებს ჰყვება? მისი ლექსიკური მარაგი საოცარი სისწრაფით იზრდება!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'ოთახის აკუსტიკა 🤫', 'ჩაძინებისას მგრძნობელობა იმატებს. ფანჯრიდან შემოსული ხმების გასანეიტრალებლად შეამოწმეთ ხმის საზომი და ოთახში დაბალ ხმაზე ჩართეთ თეთრი ხმაურის (white noise) აპარატი.'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'პატარა ინჟინერი 🤔', 'თუ ამას გადავაგდებ, რა მოხდება?, ეს ღილაკი რისთვისაა? ის მუდმივად ატარებს ფიზიკურ ექსპერიმენტებს. ასე სწავლობს! კიდევ ერთხელ შეამოწმეთ სახლის უსაფრთხოება ბავშვის სიმაღლიდან.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'ფანჯარას ნუ ენდობით ⛅', 'სასეირნოდ გასვლისას ფანჯრიდან დანახულმა ამინდმა შეცდომაში არ შეგიყვანოთ. ამინდისა და ჩაცმულობის დამხმარის საშუალებით შეარჩიეთ გარეთ არსებულ ქარსა და ტემპერატურაზე საუკეთესოდ მორგებული სამოსი და სახლიდან მშვიდად გადით.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'საყიდლების მხსნელი 🛒', 'მაღაზიაში წასვლისას ყოველთვის ყველაზე მნიშვნელოვანი ნივთი გავიწყდებათ? საყიდლების სია აპში გელოდებათ. ჩაინიშნეთ იქ ყველაფერი, რაც გჭირდებათ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ზუსტად ის პროდუქტები მოიტანოს.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'წყლის თერაპია 🛀', 'მთელი დღის სირბილმა თქვენც და ბავშვიც დაგღალათ. თბილი აბაზანის მიღებისას ფონად ბუნების დამამშვიდებელი ხმები ჩართეთ. წყლის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ძილისთვის მოამზადებს.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'მტკიცე „არა“! 🛑', 'როდესაც ვინმეს მისი კოცნა სურს, ბავშვი თავს არიდებს და მტკიცედ ამბობს „არას“? პატივი ეცით მისი სხეულის საზღვრებს. უნებართვო შეხების გაპროტესტება მისი ჯანსაღი ფსიქოლოგიური განვითარებისთვის აუცილებელია.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'მამის ხმის ტონი 📖', 'ამ საღამოს ხმის იოგები დაასვენეთ. ბავშვის საყვარელი წიგნების სხვადასხვა ხმით, ფანტაზიისა და იუმორის თანხლებით წაკითხვა მამას მიანდეთ.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'პირადი საკუთრება 🧸', 'თქვენი ბავშვი სახლში მოსული სტუმრის ბავშვს თავის სათამაშოს არ აძლევს? ეს ეგოიზმი კი არა, პირადი საზღვრების დაცვაა. გაზიარება იძულებით კი არა, საკუთარი მაგალითით ასწავლეთ.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'დედის ენერგეტიკული ბარი 🥑', 'ყოველდღიურ სირბილში სადილს ნაჩქარევად, ფეხზე მდგომი ნუ მიირთმევთ. ჯანსაღი რეცეპტებიდან ენერგიის მომცემი წასახემსებელი შეარჩიეთ და საკუთარ კვებას პრიორიტეტი მიანიჭეთ — თუნდაც სულ მცირე 10 წუთით დივანზე წამოწვეთ.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'დაჭერობანას მარათონი 🏃‍♂️', 'ბავშვს უკვე მხოლოდ სიარული აღარ აკმაყოფილებს — როცა ეძახით, სწრაფად გარბის და იმალება. ოთახიდან სახიფათო დაბრკოლებები მოაშორეთ და ამ მხიარულ დაჭერობანაში თქვენც ჩაერთეთ.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'აღმოაჩინეთ ფსიქოლოგია 📱', 'დაგღალათ იმან, რომ ბავშვი ყველაფერზე „არას“ ამბობს? აპლიკაციაში ფსიქოლოგიური ბლოგების წაკითხვით უკეთ გაიგებთ მის ტვინში მიმდინარე განვითარების ამ ქარიშხლის სიღრმისეულ მიზეზებს.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'სიბნელის ძალა 🌙', 'ბავშვს სწრაფად რომ დაეძინოს, ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'რეჟისორი მუშაობის პროცესშია 🎭', 'ილუსტრირებული წიგნის პერსონაჟებს უყურებს და სრულიად თავის გამოგონილ ამბებს ჰყვება? მისი წარმოსახვა განვითარების მწვერვალზეა! სიამაყით მოუსმინეთ მის უჩვეულო ისტორიებს ისე, რომ არ შეაწყვეტინოთ.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'ცხელი ჩაი და სიმშვიდე 🍵', 'დაივიწყეთ საოჯახო საქმეები — ყველაფერი შეიძლება მოიცადოს. ჯანსაღი რეცეპტებიდან მოამზადეთ მელისის ჩაი და დატკბით საკუთარ თავთან განმარტოებით.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'პარკის თერაპია 🌳', 'ოთხ კედელში ყოფნა გახრჩობთ. გრილი ამინდის მიუხედავად, ბავშვს თბილად ჩააცვით და 20 წუთით პარკში გაიყვანეთ. მიეცით საშუალება, შეისწავლოს ფოთლები და ქვები — სუფთა ჰაერი მის ტვინს ჟანგბადით მოამარაგებს.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'ხელოვნება თეფშზე 🥦', 'ამ საჭმელს არ ჭამს? ზოგჯერ პრობლემა გემო კი არა, გარეგნობაა. სცადეთ, ფერადი ბოსტნეულით სასაცილო სახეები შექმნათ, მადა გაუღვიძოთ და ჭამა თამაშად აქციოთ.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'მხიარული ხარხარი 🤡', 'როცა თქვენი მცდელობები უშედეგოა, მამის უცნაური ხმები სიტუაციას შველის. საღამოს ჭირვეულობისას პასუხისმგებლობა მაშინვე მას გადააბარეთ, თავად კი გვერდიდან ღიმილით უყურეთ.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'ველური ბუნება სახლში 🐶', 'მხოლოდ ხმებს კი არ გამოსცემს, ძაღლივითაც დახოხავს და კატასავითაც იზნიქება? სხეულის ენა და წარმოსახვა საოცრად ერწყმის ერთმანეთს. შეუერთდით მას და ხალიჩაზე ერთად ითამაშეთ.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'ფეხშიშველი სიარული 👣', 'მას განსაკუთრებით სიამოვნებს ფეხშიშველი სიარული და სხვადასხვა ზედაპირთან შეხება. ტერფებზე არსებული ნერვული დაბოლოებების სტიმულირება მისი ნევროლოგიური განვითარებისთვის ძალიან მნიშვნელოვანია, ამიტომ მიეცით უფლება, წინდების გარეშე იაროს.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'ციფრული მეხსიერება 🛒', 'მაღაზიაში წასვლისას აუცილებლად რაღაც გავიწყდებათ? საყიდლების სია აპში გელოდებათ. ჩაწერეთ იქ ყველაფერი, რაც გჭირდებათ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ზუსტად ის პროდუქტები შეიძინოს.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'ხმოვანი წარმოსახვა 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ მისთვის განსაკუთრებული თავგადასავალი შექმენით: ამბავი მამაც კურდღელზე, რომელსაც მტვერსასრუტის არ ეშინია. ზღაპრების დახმარებით შიშებთან გამკლავება ძალიან მარტივია.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'შელახული ეგო 🛑', '„მე თვითონ გავაკეთებ!“ — ამბობს და ყველანაირ დახმარებაზე უარს აცხადებს. ფეხსაცმელი უკუღმა რომც ჩაიცვას, ნუ ჩაერევით. დაუზიანებელი ეგო უფრო მნიშვნელოვანია, ვიდრე დაზიანებული ფეხსაცმელი.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'ეჭვებს ბოლო მოუღეთ 🤖', 'ბავშვის ქცევაში მოულოდნელმა ცვლილებებმა შეგაშფოთათ? ნუ დაიწყებთ ინტერნეტფორუმებზე საშიში დაავადებების ძიებას — Anacan AI-ისგან მიიღეთ ზუსტი, მყისიერი და მეცნიერულად დასაბუთებული ინფორმაცია.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'ძილის დარაჯი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ტვინის ყველაზე აქტიური პერიოდია. ხმის საზომის დახმარებით ოთახში ხმაურის დონე დაარეგულირეთ. ზოგჯერ მსუბუქი წვიმის ხმაც კი შეიძლება ბავშვს ღრმად ჩაძინებაში დაეხმაროს.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', '1000 დღემდე სულ რაღაც 5 დღე დარჩა! 🎈', 'ათვლა თითქმის დასრულებულია! თქვენ ზუსტად 1000-დღიანი დიდი და დაუვიწყარი გზის გავლას ასრულებთ. გაიღიმეთ და საიუბილეო მზადება თუ მხიარული იდეების მოფიქრება ახლავე დაიწყეთ!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'ჩუმად კითხვის დრო 🥱', 'დაძინება არ სურს და წინააღმდეგობას გიწევთ? ამ პერიოდში ზოგი ბავშვი დღის ძილზე უარს ამბობს. ბრძოლის ნაცვლად, გამოაცხადეთ სიმშვიდის საათი და შესთავაზეთ, საწოლში უბრალოდ წიგნი დაათვალიეროს.'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'სიამაყის ფურცელი 📝', 'ამ გრძელ და აღმართ-დაღმართებით სავსე გზაზე თქვენი უდიდესი ძალა მის მიმართ სიყვარულია. გახსენით ემოციების დღიური და დაუწერეთ პატარა, სიამაყით სავსე წერილი, რომელსაც მომავალში წაიკითხავს.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'პატარა დამხმარე 🧸', 'როდესაც ეუბნებით, ფეხსაცმელი მოგიტანოთ, მართლა მიდის და მოაქვს? მისი ლექსიკური მარაგი და გაგების უნარი პიკს აღწევს! ჩართეთ მცირე საოჯახო საქმეებში და თავდაჯერებულობის გაზრდაში დაეხმარეთ.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'ნამდვილი გუნდი თქვენ ხართ 🌟', 'მისი ყოველი თავდაჯერებული ნაბიჯი თქვენი და თქვენი პარტნიორის ერთობლივი შრომის შედეგია.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'არეული სახლი, ბედნიერი დედა 🌪', 'ტანსაცმელი მთასავით დაგროვდა, ჭურჭლის სარეცხი მანქანა კი სავსეა? იყოს ასე. სთხოვეთ თქვენს თანაგუნდელს, დღეს საოჯახო საქმეები საკუთარ თავზე აიღოს. თქვენ დაისვენეთ — ამ სახლის მთავარი საყრდენი ხართ.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'ძილზე უარის თქმა 🥱', 'არ სურს საწოლში დაწოლა და გეწინააღმდეგებათ? ზოგი ბავშვი ამ პერიოდში დღის ძილზე უარს ამბობს. ბრძოლის ნაცვლად, გამოაცხადეთ „სიმშვიდის საათი“ და შესთავაზეთ, საწოლში სათამაშოებით ჩუმად ითამაშოს.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'ღამის ტერორის ამოცნობა 😭', 'თუ ბავშვი შუაღამისას თვალდახუჭული ტირილით იღვიძებს და არავის ხმა არ ესმის, მისი ტირილი ტირილის ანალიზის ფუნქციას მოასმენინეთ. თუ ეს ძილის ტერორია, ნუ ეცდებით მის გაღვიძებას. უბრალოდ მის გვერდით იყავით და უსაფრთხოების განცდა შეუქმენით.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'შერჩევითი კვების კრიზისები 🍝', 'ბავშვი დღეს უარს ამბობს საჭმელზე, რომელიც გუშინ უყვარდა? სუფრას ბრძოლის ველად ნუ გადააქცევთ. კვების მონიტორინგის ხელსაწყოთი შეამოწმეთ ყოველკვირეული ბალანსი, ხოლო ჯანსაღ რეცეპტებში იპოვეთ განსხვავებული და სახალისო გაფორმების იდეები.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'ანატომიის გაკვეთილი 👀', 'როდესაც ეკითხებით, სად აქვს მხრები, თითით ეხება და გაჩვენებთ? მისი აღქმის უნარი პიკზეა! გააგრძელეთ თამაში სხეულის უფრო რთული ნაწილებით და გაუმდიდრეთ ლექსიკური მარაგი.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'წყლის ძალა 🛀', 'მთელი დღის სირბილის შემდეგ ბავშვიც დაიღალა და თქვენც. თბილი აბაზანის მიღებისას ფონად ბუნების დამამშვიდებელი ხმები ჩართეთ. წყლის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ძილისთვის მოამზადებს.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'დედას ჯამში უფრო გემრიელია 🥣', 'თავის თეფშს გვერდზე სწევს და იმ საკვებისკენ იწევს, რომელსაც თქვენ მიირთმევთ? ბავშვები ყოველთვის მეტად ენდობიან მშობლების არჩევანს. ჯანსაღ რეცეპტებში შეარჩიეთ ისეთი კერძები, რომელთა მირთმევასაც ორივე შეძლებთ.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'გასეირნების ტაქტიკა ⛅', 'გასეირნებისას გარეგნულად კარგმა ამინდმა არ მოგატყუოთ და ბავშვს ნუ გააციებთ. გადაწყვეტილებას მხოლოდ ფანჯრიდან გახედვით ნუ მიიღებთ — ამინდისა და ჩაცმულობის დამხმარის მეშვეობით გარეთ ქარისთვის ყველაზე შესაფერისი სამოსი შეარჩიეთ და სახლიდან მშვიდად გადით.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'მელატონინის ქარხანა 🌙', 'იმისთვის, რომ ბავშვს სწრაფად ჩაეძინოს, ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'თავაზიანობის წესები 👋', 'როდესაც ვინმე კარიდან გადის, ბავშვი საკუთარი ინიციატივით ხელს უქნევს და ემშვიდობება! მას სოციალური ინტელექტი და ემპათია უყალიბდება. ხშირად წაახალისეთ მისი ასეთი თავაზიანი ქცევა.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'დაშავებული დათუნიას ექიმი 🩺', 'როცა სათამაშო დაუვარდება, ეფერება და ეუბნება: „არ იტირო“? ესე იგი, მასში ემპათიის საოცარი გრძნობა იბადება! პიროვნული განვითარების ეს ოქროს ეტაპი დაუყოვნებლივ მონიშნეთ განვითარების ტრეკერში.'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'მელატონინის მოწვევა 🌙', 'დაძინების დასაჩქარებლად ოთახში გამორთეთ ყველა დამატებითი განათება და ლურჯი შუქის მქონე ეკრანი. ძილის ჰორმონი (მელატონინი) სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'ქვიშის მოედნის პოლიტიკა 🧸', 'პარკში თავის სათლს არავის აძლევს? ეს ეგოიზმი კი არა, უბრალოდ პირადი საკუთრების განცდის აღმოჩენაა. შერცხვენის გარეშე შესთავაზეთ მორიგეობით თამაშის წესი და დიპლომატიური კრიზისი მოაგვარეთ.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'ერთად დალაგება 🧹', 'სახლია დასალაგებელი? ოთახის დაგვისას ბავშვსაც მიეცით ტილო, რომ გაწმენდაში დაგეხმაროთ. ბლოგებში წაიკითხეთ, როგორ აქციოთ დალაგება გუნდურ საქმიანობად და გართობად.'),
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7', 'რეჟიმი ირღვევა? ⏱️', 'საღამოს ჩაძინება ძალიან ჭიანურდება? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, უკვე დროა, დღის ძილი მნიშვნელოვნად შეამციროთ და საღამოს დაძინების დრო უფრო ადრე გადმოწიოთ.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', '„მე უკვე დიდი ვარ!“ — სიჯიუტე 🛑', 'ყველაფერში ჩარევა სურს და საქმეებს აჭიანურებს? დამოუკიდებლობისთვის ამ სახალისო ბრძოლაში არჩევანის რამდენიმე მარტივი ვარიანტი შესთავაზეთ.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', '1000-დღიანი სასწაული! 👑', 'გილოცავთ! უკვე ზუსტად 1000 დღეა, რაც ამ ქარიშხლიან, დამღლელ, მაგრამ მსოფლიოში ყველაზე ძვირფას გზას მიუყვებით! დაუყოვნებლივ იზეიმეთ გამარჯვების ეს განსაკუთრებული დღე და სიამაყით გაუზიარეთ Anacan-ის საზოგადოებას!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'გუნდის გამარჯვების ცეკვა 🥂', 'ამ საღამოს პარტნიორთან ერთად აღნიშნეთ 1000 დღის დაღლილობა, ცრემლები და სიხარული. სუფრაზე ერთი სანთელი აანთეთ და დიდი სიხარულით იზეიმეთ თქვენი შეუპოვარი გუნდის გამარჯვება!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'თქვენ ეს შეძელით! 📈', 'რამხელა გზა გაიარა თქვენმა ბავშვმა! პირველი დღეების მყიფე შიში ახლა უზარმაზარმა თავდაჯერებამ ჩაანაცვლა. თქვენ ეს 1000 დღე დიდი სიამაყით გამოიარეთ! მართლაც შესანიშნავი ხართ!'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც თამაშია საჭირო, არც წიგნი და არც ზღაპარი. ამ საღამოს უბრალოდ გულში ჩაიკარით, მისი მშვენიერი სურნელი ღრმად შეისუნთქეთ და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის.'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'ჩანაწერი დღიურში 📝', 'როცა ბავშვი დაიძინებს, გახსენით განწყობის დღიური. დღეს ყველაზე მეტად რამ დაგღალათ და რამ გაგაცინათ? მიეცით საკუთარ გრძნობებს სრული თავისუფლება და გულზე მოეშვით.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'გამარჯვების შემდგომი რეალობა 🚀', 'გუშინდელი იუბილეს შემდეგ, ამ დილით ისევ მიმოფანტულმა სათამაშოებმა და შეძახილებმა „არ მინდა!“ გაგვაღვიძა! ცხოვრება გრძელდება. ღრმად ჩაისუნთქეთ — თქვენ ამ ქაოსის საუკეთესო მმართველი ხართ.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'დღის ძილის კრიზისი 🥱', 'დაწოლა არ უნდა და ტირის? 3 წლის ასაკის მოახლოებასთან ერთად ზოგი ბავშვი დღის ძილზე უარის თქმას იწყებს. ბრძოლის ნაცვლად, გამოაცხადეთ სიმშვიდის საათი და შესთავაზეთ, უბრალოდ საწოლში წიგნი დაათვალიეროს.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'საწოლიდან გაქცევის გეგმა 🛌', 'საბავშვო საწოლიდან გადმოძრომას ცდილობს? უსაფრთხოებისთვის ოთახი თავიდან შეამოწმეთ. დიდი ბავშვის საწოლზე გადასვლის დრო ახლოვდება.'),
  ('9fdf76d2-ea34-465e-99e8-537978d670c9', 'იწყება კითხვები „როგორ?“ 🤔', 'კითხვებს „რატომ?“ თანდათან ცვლის კითხვა „ეს როგორ მუშაობს?“. ბავშვი მექანიზმების გაგებას ცდილობს. მოიკრიბეთ მოთმინება და მოკლე, ლოგიკური განმარტებები მიეცით.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'შესვენება დედისთვის ☕', 'როცა ბავშვი დამოუკიდებლად თამაშობს, მაშინვე ნუ შეუდგებით საოჯახო საქმეებს. ოთახში არეულობა არსად გაიქცევა, თქვენი ენერგია კი შეიძლება ამოიწუროს. ჩამოჯექით და ცხელი ყავა დალიეთ.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', 'ეს რა არის? მანქანა ☝️', 'ყველაფერზე თითით მიგითითებთ და გეკითხებათ, რა ჰქვია? მას სურს, რომ სამყარო მისთვის სიტყვებით აღწეროთ. ეს კომუნიკაციაში დიდი წინსვლაა! თუნდაც დაიღალოთ, მოთმინებით გაუმეორეთ საგნების სახელები.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'თქვენ ადამიანი ხართ 🛑', 'დღეს არაფერი წავიდა გეგმის მიხედვით? თავს ნუ დაიდანაშაულებთ. თქვენ ნამდვილი დედა ხართ და არა სოციალურ ქსელებში გაფილტრული ილუზია. თქვენს ბავშვს უბრალოდ თქვენ სჭირდებით.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'ესთეტიკური კვების კრიზისი 🥦', 'პურის ქერქს ან კიტრის ნაჭერს მხოლოდ იმიტომ არ ჭამს, რომ უშნოდ გამოიყურება? საკვების მიმართ პრეტენზიულობა ზოგჯერ უცნაურ ფორმებს იღებს. კვების გეგმაში აღმოაჩინეთ ბოსტნეულის პიურედ ქცევისა და საკვებში შეუმჩნევლად დამალვის ყველაზე ოსტატური ხერხები.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'დილის კონცერტი დაიწყო 🎤', 'გაღვიძებისთანავე ხმას მაქსიმალურ დეციბელზე აყენებს და რაღაცებს მღერის? დილის 7 საათზე მისი ენერგია სრულად დამუხტულია. მოიფშვნიტეთ თვალები და ღიმილით უყურეთ ამ პატარა პოპვარსკვლავის შოუს.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'წყალდიდობა სააბაზანოში 🛀', 'წყლით თამაში სისუფთავისთვის კი არა, ოთახის აკვაპარკად გადასაქცევად სჭირდება. აცადეთ, წყალი აშხეფოს. თბილი წყალი და გართობა მთელი დღის განმავლობაში დაგროვილ სიჯიუტეს ჩამორეცხავს.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', '„კიდევ ერთი“ ხაფანგი 📖', 'დაძინება არ უნდა და კიდევ ერთი ზღაპრის მოყოლის თხოვნით დროს აჭიანურებს. თავი დაანებეთ კლასიკურ წიგნებს. ჭკვიან ზღაპრებში მის მიერ გამოგონილი პერსონაჟებით შექმენით ძილისწინა მოკლე ამბავი და დაძინების რიტუალი დაასრულეთ.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'ფარული შოკოლადის შესვენება 🍫', 'დედიკო, რომელიც სამზარეულოს კარადის უკან მალულად, ფეხზე მდგარი შეექცევით რაიმე ტკბილს — ჩვენ გხედავთ! თავს ნუ დაიდანაშაულებთ. ხმაურის ასატანად გლუკოზის დონის ამგვარ მატებაზე სრული უფლება გაქვთ.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('c5c0175d-de40-45a7-97f9-43392b324696'::uuid, 'სახლის პატარა დიქტატორი 👑', 'იქ არა, აქ დაჯექი! ამას შენ კი არა, მე გავაკეთებ! სახლის მართვა თავად სურს. მისი ნების მკვეთრად გატეხვის გარეშე შეინარჩუნეთ წონასწორობა და უთხარით: შენ აქ დაჯექი, მე კი იქ დავჯდები.'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'მამის მასაჟის სეანსი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე და ბავშვის დევნით წელი გწყდებათ. როგორც კი ბავშვი დაიძინებს, პარტნიორს სთხოვეთ, მხრებზე 10-წუთიანი მასაჟი გაგიკეთოთ. თქვენ ოჯახის ბურჯი ხართ, ბურჯებს კი დასვენებაც სჭირდებათ.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'ნუ ჩაერევით 🧦', 'წინდის ქუსლი ზემოთ აქვს მოქცეული, მაგრამ რადგან თვითონ ჩაიცვა, მსოფლიოში ყველაზე ამაყი ადამიანივით დადის. ოდნავადაც ნუ ჩაერევით. დამოუკიდებლობის განცდა სწორად ჩაცმაზე უფრო მნიშვნელოვანია.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'საზოგადოებაში ამოსუნთქვა 💬', 'ძალიან დაიღალეთ და თავი მსოფლიოში ყველაზე მოუთმენელ დედად მიგაჩნიათ? დაუყოვნებლივ გახსენით Anacan-ის საზოგადოება. იმის წაკითხვა, რომ სხვა დედებიც იმავე კრიზისებს გადიან, უდიდესი ფსიქოლოგიური მხარდაჭერაა.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'ღრუბლების გამოცანა ⛅', 'ოთხ კედელში ყოფნა გახრჩობთ? ამინდის შესაბამისად ჩაიცვით და პარკში გადით. უბრალოდ დასხედით და გამოიცანით, რას ჰგავს ცაში ღრუბლები. ეს მშვიდი თამაში ტვინს ერთდროულად ასვენებს და ავითარებს.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'სახლში ქაოსი საბოლოოდ დასრულდა.', 'ფანჯრიდან შემოსული ხმების დასაფარად ჩართეთ lofi მუსიკა და სული დაისვენეთ.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'პირველი საყვარელი ტყუილები? 🤥', 'წყალი მე არ დამიღვრია, დათუნიამ დაღვარა. ყურადღება! ბავშვის წარმოსახვა იმდენად განვითარდა, რომ მოვლენების თავის სასარგებლოდ გამოგონება შეუძლია. ტყუილში ნუ დაადანაშაულებთ — გაუღიმეთ და უთხარით: დათუნიას უთხარი, მეორედ აღარ დაღვაროს.'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'დილის ვარჯიში 🤸‍♂️', 'თქვენ ჯერ არც კი გაგიღვიძიათ, ის კი უკვე საწოლში ზედ გახტებათ. მსოფლიოში ყველაზე ხმაურიანი, მაგრამ ყველაზე საყვარელი მაღვიძარა! დაიწყეთ დღე ღიმილით და მისი უსაზღვრო ენერგიით.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'მაღაზიაში სიის გარეშე წასვლის უბედურება 🛒', 'მაღაზიაში წახვედით და ყველაზე მთავარი ნივთის ყიდვა დაგავიწყდათ? დედის მეხსიერება ასეთია. ნუ ენდობით მხოლოდ საკუთარ მეხსიერებას — ჩვევად აქციეთ, რომ ყოველი წვრილმანი საჭიროება დაუყოვნებლივ ჩაწეროთ საყიდლების სიაში.'),
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939', 'ჩაი სანთლის შუქზე 🕯️', 'ბავშვმა დაიძინა. ჩააქრეთ შუქი და მაგიდაზე სანთელი აანთეთ. ეს რომანტიკისთვის კი არა, მთელი დღის განმავლობაში დაძაბული ნერვებისა და დაღლილი თვალების დასამშვიდებლადაა.'),
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5', 'ხელოვნური ინტელექტი, რეალური დახმარება 🤖', 'რა ფსიქოლოგიური მიზეზი იმალება ბავშვის მუდმივი გაჯიუტების უკან? ინტერნეტში შემაშფოთებელ სტატიებს ნუ მოძებნით. სთხოვეთ Anacan AI-ს, მეცნიერულად და მოკლედ აგიხსნათ 33 თვის ბავშვებისთვის დამახასიათებელი კრიზისები.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'რეჟიმის დარღვევა ⏱️', 'საღამოს ჩაძინებას 1 საათზე მეტი სჭირდება? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, უკვე დიდი ხანია დროა, დღის ძილი საგრძნობლად შეამციროთ და საღამოს დაძინების დრო უფრო ადრე გადმოწიოთ.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'თმის დავარცხნის აპოკალიფსი 🪮', 'თმის დავარცხნისას ან შეხებისას ისე ყვირის, თითქოს ეს მსოფლიოში ყველაზე დიდი წამებაა? შეწყვიტეთ ბრძოლა. ჯერ სავარცხელი მას მიეცით და თქვენი თმა დაავარცხნინეთ, შემდეგ კი ჯერი თქვენზე გადავიდეს.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'რკინის მარაგი 🥩', 'ფერმკრთალია ან უმადობა აქვს? კვების კონტროლის ხელსაწყოში შეამოწმეთ, საკმარის რკინას იღებს თუ არა. ხორცთან ერთად აუცილებლად მიეცით ლიმონიანი სალათი — ეს რკინის შეწოვას მყისიერად გააუმჯობესებს.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'სათამაშოების გაზიარების გაკვეთილი 🧸', 'პარკში წასვლამდე ესაუბრეთ: დღეს სათამაშოებს ერთმანეთს რიგრიგობით მივცემთ. დიახ, შესაძლოა, ისევ არ ათხოვოს, მაგრამ აუცილებელია, ეს აბსტრაქტული წესი არაერთხელ მოისმინოს.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'მამის დაძინების ტაქტიკა 👨‍🍼', 'ღამით პიჟამის ჩაცმა არ უნდა და გარბის? საქმე მამას გადააბარეთ. როცა ის ჩაცმის პროცესს ჭიდაობად ან სახალისო თამაშად აქცევს, ბავშვი ვერც კი ამჩნევს, როგორ იცვამს პიჟამას.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'ბუნების გამოცანა 🍁', 'პარკში უბრალოდ სეირნობის ნაცვლად თამაში დაიწყეთ: მოდი, ყველაზე დიდი ყვითელი ფოთოლი ვიპოვოთ! ბუნება მისთვის ყველაზე დიდი და ინტერაქციული სკოლაა.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'სარეცხი მანქანისადმი ინტერესი 🧺', 'სარეცხი მანქანის წინ ზის და მბრუნავ ტანსაცმელს აკვირდება? ეს სრულიად უფასო და გონების დამამშვიდებელი გასართობია. ხელს ნუ შეუშლით, თქვენც ისარგებლეთ შემთხვევით და დაისვენეთ.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'გულახდილობა განწყობის დღიურში 📝', 'აიღეთ ტელეფონი. სოციალურ ქსელში სქროლვის ნაცვლად გახსენით განწყობის დღიური და დაწერეთ ყველაფერი, რამაც დღეს გაგაგიჟათ — წერეთ, სანამ გულს არ მოიოხებთ. ციფრული თერაპია ნამდვილად მუშაობს.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'მელატონინის დრო 🌙', 'ძილის ჰორმონის გამოსაყოფად, დაძინებამდე სულ მცირე 1 საათით ადრე გამორთეთ ლურჯი სინათლის ყველა წყარო, მათ შორის ტელევიზორი და პლანშეტი. სიბნელე და სიჩუმე ძილის საუკეთესო საშუალებაა.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', 'თამაში „მე დედა ვარ!“ 🎭', 'თოჯინას თითს უქნევს და თქვენი ხმის ტონით უბრაზდება? ოთახში თქვენი პატარა ასლი დადის. საკუთარ თავზე გვერდიდან დაკვირვება სახალისოცაა და იმის მინიშნებაც, რომ თქვენს ქცევებს მეტი ყურადღება მიაქციოთ.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'დღის ძილზე უარის თქმა 🥱', 'დაწოლა არ უნდა, მაგრამ თვალები ძილისგან ეხუჭება? 3 წლის ასაკის მოახლოებისას ასეთი წინააღმდეგობა ჩვეულებრივი მოვლენაა. ნუ აიძულებთ — ოთახში სინათლე შეამცირეთ და წიგნის ჩუმად თვალიერების საათი გამოაცხადეთ.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'დილის სიჯიუტის ფერი 🔴', 'საჭმელი მწვანე თეფშზე მოითხოვა, მაგრამ როცა მიუტანეთ, ატირდა და გითხრათ, რომ წითელი უნდოდა. ლოგიკის ძებნას თავი დაანებეთ. უბრალოდ წითელ თეფშზე გადაუღეთ და ნერვულ უჯრედებს გაუფრთხილდით.'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'ღამის ქარიშხალი 😭', 'შუაღამისას უმიზეზოდ ტირილით გაიღვიძა? აირები აწუხებს თუ ღამის შიში აქვს? შეწყვიტეთ ვარაუდი — „ტირილის ანალიზით“ მიზეზი დაადგინეთ, შემდეგ კი მშვიდად ჩაეხუტეთ და დაამშვიდეთ.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'ქოთანთან დაკავშირებული უსიამოვნებები 🚽', 'ქოთნის გამოყენების სწავლისას ისევ ხალიჩაზე მოშარდა? ღრმად ჩაისუნთქეთ. გაბრაზებამ შესაძლოა უკან დახევა გამოიწვიოს. ნუ ინერვიულებთ იმის გამო, რაც უბრალოდ გაიწმინდება — ეს მხოლოდ სწავლის პროცესია.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'პარკის ადვოკატი 🗣️', '„ცოტა კიდევ ვითამაშებ, სულ რაღაც 5 წუთი!“ — ამბობს და დროს აჭიანურებს. დროის აღქმა ჯერ არ აქვს, მაგრამ მოლაპარაკება შესანიშნავად გამოსდის. დააყენეთ ტაიმერი და წესები თამაშით, საყვედურის გარეშე შეახსენეთ.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'სიმაღლეში ნახტომი 📏', 'შარვლები დაუმოკლდა? ის სწრაფად იზრდება! შეიყვანეთ მიმდინარე მონაცემები განვითარების ტრეკერში და უძილო ღამეების შედეგს სიამაყით შეხედეთ.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'დრო წყვილისთვის 🥂', 'ბავშვმა დაიძინა. ახლა ტელეფონები და საოჯახო საქმეები გვერდზე გადადეთ. პარტნიორთან მინიმუმ 20 წუთის განმავლობაში ისაუბრეთ ნებისმიერ თემაზე, გარდა ბავშვისა და გადასახადებისა.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'ზღაპრის ჯადოსნური სამყარო 🪄', 'ამ საღამოს ჭკვიან ზღაპრებში სრულიად განსხვავებული რამ სცადეთ: პატარა ღრუბლის ამბავი, რომელმაც ცა აღმოაჩინა. ხმის ტონი ზღაპრის რიტმს მოარგეთ და ბავშვი ნელ-ნელა დააძინეთ.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', '„მე შემომხედე!“ — პროტესტი 👀', 'როცა ტელეფონს უყურებთ, მოდის, ხელზე გირტყამთ ან მოწყობილობას გართმევთ. ის სრულიად მართალია. მას იმ წამს თქვენი სრული და განუყოფელი ყურადღება სჭირდება. დაამყარეთ თვალით კონტაქტი და აგრძნობინეთ, რომ უსმენთ.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'ჯიუტი ლაქები, თავისუფალი აღმოჩენები 🎨', 'პიჟამა საჭმლითაა მოსვრილი, ტანსაცმელი კი საღებავით? ბავშვები სისუფთავეში კი არ უნდა იზრდებოდნენ, არამედ სამყაროს აღმოჩენისას უნდა ისვრებოდნენ. არეულობა მისი შემოქმედების ხელწერაა — ნუ ინერვიულებთ.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'ჩურჩულით საუბარი 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. მის გვერდით დაწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ჩურჩულით მოუყევით. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი საუკეთესო მეთოდია.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'გამოცდილების გაზიარება 💬', 'ბავშვის ყველაფერზე გაჯიუტებამ შეგაშინათ? ინტერნეტში შემაშფოთებელ სტატიებს ნუ მოძებნით. გაეცანით Anacan-ის საზოგადოებაში გამოცდილი დედების რეალურ გამოცდილებას და გაიღიმეთ.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'პროფესიონალი მოცეკვავე 🎶', 'პირველივე გაგონილ რიტმზე — იქნება ეს რეკლამის მუსიკა თუ მანქანის სიგნალი — ცეკვას იწყებს. ცხოვრებას თქვენც მასავით მხიარულად შეხედეთ! შეუერთდით და ოთახში რამდენიმე წუთით გიჟურად იცეკვეთ.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'მამის საიდუმლო ტაქტიკა 👨‍🍼', 'დღის დაღლილობაც საკმარისია თქვენთვის. საღამოს ბავშვის დასაძინებლად მომზადება და კბილების გახეხვა მამას და მის მხიარულ თამაშებს მიანდეთ, თავად კი გვერდით მშვიდად დაისვენეთ.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'დაკეცილი და მიმოფანტული ტანსაცმელი 👗', 'თქვენ დიდი წვალებით კეცავთ ტანსაცმელს, ის კი მოდის და მყისვე ყველაფერს ფანტავს. გაბრაზების ნაცვლად, ეს საქმე თამაშად აქციეთ: ვნახოთ, ამ მაისურს ვინ უფრო შორს გადააგდებს?'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'დაჟინებით დამოუკიდებლად ჭამა 🥄', 'კოვზს იღებს და ყველაფერს სვრის? ჩართეთ კვების ტაიმერი. დაყრილ საკვებზე კი ნუ იდარდებთ, არამედ შეხედეთ, რამდენად დამოუკიდებელი ხდება, და გაიხარეთ.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'ბოსტნეულის საიდუმლო ოპერაცია 🥦', 'წვნიანში ბოსტნეულს ისე აცალკევებს, თითქოს მიკროსკოპით ეძებდეს? ჯანსაღ რეცეპტებში იპოვეთ სოუსების რეცეპტები, რომლებიც ბოსტნეულს შეუმჩნეველს გახდის. კრეატიულობა დედის ყველაზე ძლიერი იარაღია.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'ქვემოთ ჩაიხედეთ — რას აღმოაჩენს? 👣', 'განსაკუთრებით სიამოვნებს ფეხშიშველი სიარული და სხვადასხვა ზედაპირთან შეხება. ტერფებზე არსებული ნერვული დაბოლოებების სტიმულაცია წონასწორობის განვითარებისთვის მნიშვნელოვანია, ამიტომ მიეცით საშუალება, წინდების გარეშე იაროს.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'ღამის მცველები 🧸', 'სიბნელის ეშინია? მისი საყვარელი დათუნიები და სათამაშოები საწოლის გარშემო დაალაგეთ და უთხარით: „ისინი დილამდე დაგიცავენ“. უსაფრთხოების ეს თვალსაჩინო განცდა შესანიშნავად მოქმედებს.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'სიჩუმის დასტური 🤫', 'ხმაურიანი დღის შემდეგ, როცა ბავშვს ჩაეძინება, ხმის საზომი მოწყობილობით ოთახში სიჩუმე გაზომეთ. ნულთან მიახლოებული მაჩვენებლების დანახვაც კი დედის ტვინზე თერაპიულად მოქმედებს.'),
  ('53046b7a-695e-4d17-9dda-231255060141', 'დილის „არა!“ 🛑', 'თვალები ჯერ არც კი გაუხელია და თუ რამეს შესთავაზებთ, უკვე „არა!“ გპასუხობთ. 3 წლის ასაკის ზღურბლზე კითხვები ნუ დაუსვამთ — უბრალოდ იმოქმედეთ. „მოდი, პირი და ხელები დავიბანოთ“ კი ნუ ეტყვით, არამედ: „პირისა და ხელების დაბანის დროა!“'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'საკუთარ თავსაც დაუთმეთ დრო 🥑', 'მუდმივმა სირბილმა ძალა გამოგაცალათ. ფეხზე დგომისას სახელდახელოდ წახემსების ნაცვლად, ჯანსაღი რეცეპტებიდან მოამზადეთ ნოყიერი, ვიტამინებით სავსე განსაკუთრებული კერძი და სიამოვნებით მიირთვით. ენერგია აუცილებლად გჭირდებათ.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'ფეხშიშველი მკვლევარი 👣', 'წინდების ჩაცმა არ უნდა, გარბის და იმალება? აცადეთ, ცოტა ხნით ფეხშიშველმა შეიგრძნოს იატაკი, ხალიჩა და ცივი ფილები. ტერფებზე არსებული ნერვული დაბოლოებების განვითარება მისი წონასწორობისთვის შეუცვლელია.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'ჩააქრეთ შუქი, მოიხმეთ ძილი 🌙', 'იმისთვის, რომ ბავშვმა უფრო სწრაფად დაიძინოს, ოთახში ყველა ზედმეტი შუქი ჩააქრეთ და პლანშეტის ეკრანიც გამორთეთ. მელატონინი მხოლოდ სიბნელესა და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'ბუნების საგანძურის ძიება 🍁', 'ამინდის შესაბამისად ჩაიცვით და გარეთ გადით. პარკში სხვადასხვა ქვისა და ფერადი ფოთლის პოვნის თამაში ითამაშეთ. ამ ასაკში ბუნება მისთვის ყველაზე დიდი და ინტერაქტიული სათამაშოა.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'დავიწყებული ნივთები მაღაზიაში 🛒', 'მეხსიერებას მიენდეთ, მაღაზიაში წახვედით და ყველაზე მნიშვნელოვანი ნივთის ყიდვა დაგავიწყდათ? მიეჩვიეთ, რომ ყველაფერი, რაც გჭირდებათ, დაუყოვნებლივ ჩაწეროთ საყიდლების სიაში — დაე, აპმა თქვენს ნაცვლად დაიმახსოვროს.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'დილის პატარა დამხმარე 🧑‍🍳', 'საუზმის მომზადებაში დახმარება სურს. ფქვილს დაყრის, წყალს დაღვრის, სამზარეულოს დასვრის... მაგრამ ის სწორედ ამ წვრილი მოტორიკის გამოცდებით იზრდება. მოთმინება გამოიჩინეთ.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'ჯადოქარი მამის შოუ 🤡', 'როცა თქვენი მცდელობები აღარ ჭრის, მამის უცნაური ხმები მდგომარეობას მყისიერად შველის. საღამოს ჭირვეულობის დროს ასპარეზი მას დაუთმეთ და გვერდიდან მხიარულ კისკისს უყურეთ.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'თბილი აბაზანის თერაპია 🛀', 'მთელი დღის სირბილმა თქვენც და ბავშვიც დაგღალათ. თბილი აბაზანის მიღებისას ფონად ბუნების დამამშვიდებელი ხმები ჩართეთ. წყლის ჰარმონიული ხმა ყველაზე ჯიუტ ბავშვსაც კი ძილისთვის მოამზადებს.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'თვითონ უნდა ჩამოასხას 💧', 'წყალი ჭიქაში აუცილებლად თვითონ უნდა ჩამოასხას. ხელსახოცები მოიმზადეთ და დამოუკიდებლობის სურვილს ნუ ჩაუხშობთ. წყალს დაღვრის, მაგრამ რამდენიმე ცდის შემდეგ გაგაოცებთ, როგორი სიფრთხილით ავსებს ჭიქას.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'ემოციური გამოფიტვის განცდა 🔋', 'თავს არასაკმარისად კარგად გრძნობთ? ფიქრობთ, რომ ყველაფერს თავს ვერ ართმევთ? გადახედეთ საზოგადოების პოსტებს — თქვენ მარტო არ ხართ და არასაკმარისი ნამდვილად არ ხართ. თქვენ ამ ბავშვის მთელი სამყარო ხართ.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'უცნაური გრამატიკა 🗣️', '„მე მომშივდა ვიყავი“, „ის მიდიოდა და მოვიდა“ — ბავშვი სრულიად ახალ, თავისებურ გრამატიკულ ფორმებს იგონებს. მკაცრად ნუ შეუსწორებთ, უბრალოდ უპასუხეთ და წინადადების სწორი ფორმა გაუმეორეთ.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'Anacan AI-ის რჩევა 🤖', 'გაქვთ შეკითხვა იმის შესახებ, როგორ უნდა დაამყაროს ბავშვმა ურთიერთობა პარკში სხვა ბავშვებთან? საათობით ნუ დაიკარგებით ინტერნეტში — ჰკითხეთ Anacan AI-ს და მყისიერად მიიღეთ ბავშვის განვითარების ეტაპზე მორგებული, პედიატრების მიერ დამტკიცებული რჩევა.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'ღამის შიშის გაფრთხილება 😭', 'თუ ბავშვი მოულოდნელად ატირდება ან დახუჭული თვალებით დაიწყებს ყვირილს, შეამოწმეთ ტირილის ანალიზის საშუალებით. თუ ეს ღამის შიშია, ნუ ეცდებით მის გაღვიძებას — უბრალოდ მის გვერდით იყავით და მშვიდად აგრძნობინეთ, რომ უსაფრთხოდაა.'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'წარმოსახვითი სცენარები 🧸', 'სათამაშო დათუნიას ზღაპარს უყვება ან ცარიელი ჭიქიდან ჩაის სვამს? სიმბოლური თამაშები განვითარების შედევრია. ხელს ნუ შეუშლით — გვერდიდან დააკვირდით ამ პატარა რეჟისორს.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'სიჩუმის საჭიროება 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმის საზომით შეამოწმეთ გარემოში ხმაურის დონე დეციბელებში და მეზობელ ოთახში ტელევიზორის ხმა შესაბამისად დაარეგულირეთ.'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'ურთიერთობა პარკში 🌳', 'სხვა ბავშვებთან თამაშის ნაცვლად, მათ გვერდით თავისთვის თამაშობს? პარალელური თამაში ამ ასაკისთვის სრულიად ბუნებრივია. ამინდის შესაბამისად ჩააცვით და პარკში გაიყვანეთ.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'სწრაფი პედიატრი 🤖', 'ქოთნის გამოყენების სწავლებისას რეგრესს აწყდებით? თავს ნუ გადაიღლით — ჰკითხეთ Anacan AI-ს, როგორ გაუმკლავდეთ ამ ფსიქოლოგიურ პროცესს.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'დრო მიფრინავს!', 'უკან მოიხედეთ და დაინახეთ, რამდენი რამ ისწავლეთ. ამ პატარა ადვოკატს უკვე ნებისმიერ საკითხზე შეუძლია თქვენთან მოლაპარაკება. იამაყეთ როგორც მისით, ისე საკუთარი თავით.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'ზღაპრის გმირი 🪄', 'კლასიკურმა წიგნებმა ორივე მოგაბეზრათ თავი. გონივრულ ზღაპრებში ის კოსმონავტად აქციეთ და ვარსკვლავებისკენ გააფრინეთ ან ზღვის სიღრმეებში ჩაუშვით. ძილის წინ ფანტაზიას თავისუფლება მიეცით.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'სიმშვიდის საათი აუცილებელია ☕', 'თუ დღისით დაძინებაზე კატეგორიულ უარს ამბობს, ნუ დააძალებთ. თუმცა 30-წუთიანი სიმშვიდის საათი (quiet time) დაუწესეთ. ის საწოლში წიგნებთან ერთად მარტო დარჩეს, თქვენ კი ოთახში ცოტა ამოისუნთქეთ.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'განწყობის დღიური 📝', 'აიღეთ ტელეფონი. სოციალური ქსელის სქროლვის ნაცვლად, გახსენით განწყობის დღიური და მომავლისთვის ჩაინიშნეთ დღევანდელი ყველაზე სასაცილო მომენტი, როცა მან ყველაზე მეტად გაგაცინათ.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'ოპერაცია „დამალული ბოსტნეული“ 🥦', 'წვნიანიდან ბოსტნეულს არჩევს და ყრის? ნუ შეებრძოლებით. კვების გეგმაში აღმოაჩინეთ ბოსტნეულის პიურედ ქცევისა და სოუსებში დამალვის ყველაზე მრავალფეროვანი და ეშმაკური გზები.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', '„დედა, შემომხედე!“ — დაჟინებული მოთხოვნა 👀', 'როცა ტელეფონს უყურებთ ან საქმეს აკეთებთ, მოდის და ხელზე გირტყამთ? ის სრულიად მართალია — თქვენი განუყოფელი ყურადღება სურს. თვალით კონტაქტი და 5-წუთიანი სრულფასოვანი დრო მას დაამშვიდებს.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'ოთახიდან გაქცევის თამაში 🏃‍♂️', 'როცა პიჟამის ან მაისურის ჩაცმას უპირებთ, სიცილით გარბის ოთახიდან. გაბრაზების ნაცვლად, ეს პროცესი თამაშად აქციეთ. დაჭერობანას თამაშისას მისი ჩაცმა უფრო მარტივი იქნება.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'ამინდის გაფრთხილება ⛅', 'სასეირნოდ გასვლისას მხოლოდ ფანჯრიდან დანახულ ამინდს ნუ ენდობით. ამინდისა და ჩაცმულობის დამხმარის საშუალებით გარეთ არსებულ რეალურ ქარსა და ტემპერატურაზე საუკეთესოდ მორგებული სამოსი შეარჩიეთ და ისე გადით სახლიდან.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'ჩუმ რეჟიმზე გადასვლა 🤫', 'ჩაძინებისას მისი მგრძნობელობა იმატებს. შეინარჩუნეთ სიმშვიდე და სიჩუმე.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'მამასთან ძილისპირული დუეტი 📖', 'დღეს საღამოს ოთახში განსხვავებული განწყობა შევქმნათ. წიგნის წაკითხვის ნაცვლად, მამასთან ერთად ჩუმად და რიტმულად უმღერეთ, რათა ბავშვს ჩაძინებაში დაეხმაროთ.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'დედა, კარგად დანაყრდით 🥑', 'ყოველდღიურ ქაოსში სადილს ფეხზე მდგომი ნუ მიირთმევთ. დაჯექით, მოამზადეთ რკინითა და კალციუმით მდიდარი, განსხვავებული სალათი და სიამოვნებით მიირთვით. თქვენი ენერგია ამ სახლის მამოძრავებელი ძალაა.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'მეგობრობის ნაბიჯები 👫', 'პარკში პირველად გაუზიარა სხვა ბავშვს საკუთარი სურვილით სათამაშო? ეს დიდი წინსვლაა! ეგოცენტრიზმი მცირდება და ემპათია ყალიბდება. დიდი სიხარულით შეაქეთ და ტაში დაუკარით.'),
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d', '„ჩემია!“ — სიჯიუტე 🛑', 'ყველაფრის დასაკუთრება სურს? გაზიარების ცნება ჯერ ბოლომდე ჩამოყალიბებული არ აქვს. ნუ აიძულებთ; ამის ნაცვლად, თანდათან შემოიღეთ წესი: „მორიგეობით ვითამაშოთ“.'),
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc', 'ჯადოსნური ღამის ფონი 🪄', 'დაძინება უჭირს? „ჭკვიან ზღაპრებში“ სპეციალური ზღაპრის შექმნით, ახალი ჩვევები საინტერესო ამბად აქციეთ.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', '10 წუთი სანთლის შუქზე 🕯️', 'ბავშვმა დაიძინა, სახლში ქაოსიც დასრულდა. ჩააქრეთ შუქები და 10 წუთის განმავლობაში უბრალოდ სიბნელეს ან სანთლის ალს უყურეთ, რათა გონება და ფიქრები სრულად განიტვირთოთ.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'ნუგეში საზოგადოებაში 💬', 'ფიქრი, რომ ძველებური თქვენ ვეღარასდროს გახდებით, გთრგუნავთ? გაუზიარეთ ეს დროებითი, თუმცა ძალიან მძიმე განცდა Anacan-ის საზოგადოებაში მყოფ დედებს და მიიღეთ მათგან მხარდაჭერა.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'ჯიუტი ნაწნავები 🪮', 'თმის შეკვრის ან დავარცხნის უფლებას საერთოდ არ გაძლევთ? შეწყვიტეთ ბრძოლა. დადექით სარკესთან და ჯერ საკუთარი თმა დაივარცხნეთ ისე, როგორც მას სურს, შემდეგ კი მისი ჯერი დადგეს.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'ბრძოლა დღის ძილისთვის 🥱', 'თუ უარს ამბობს, ნუ აიძულებთ. იმის ნაცვლად, რომ დაძინება არაერთხელ სცადოთ და ნერვები მოიშალოთ, შექმენით რეჟიმი, რომლის დროსაც ოთახში მშვიდად ითამაშებს სათამაშოებით.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'გუნდური გამარჯვება 🥂', 'კიდევ ერთი რთული დღე მოიტოვეთ უკან. დაჯექით თქვენს პარტნიორთან პირისპირ და ჩაის ჭიქები მიუჭახუნეთ ერთმანეთს: ჩვენ მართლაც ლეგენდარული გუნდი ვართ და ამას შესანიშნავად ვუმკლავდებით!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'გაზიარების სირთულე 🧸', 'სათამაშოს არავის აძლევს? ეს ეგოიზმი კი არა, განვითარების ეტაპია. 3 წლის ასაკის მოახლოებისას Anacan AI-ისგან შეიტყვეთ არა გაზიარების, არამედ მორიგეობით თამაშის პრინციპის შესახებ.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'სამთვლიანი ველოსიპედი 🚴‍♂️', 'ცდილობს, პედლებს დააწვეს და ველოსიპედი ატაროს? მისი ფეხის კუნთები და კოორდინაცია განვითარების ახალ ეტაპზეა! წაახალისეთ, რომ უსაფრთხო ადგილებში ივარჯიშოს.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'ვიტამინები დედისთვის 🥑', 'ყველაფერს აკეთებთ, რომ ბავშვი დაანაყროთ. თქვენზე ვინ იზრუნებს? ჯანსაღი რეცეპტების განყოფილებიდან შეარჩიეთ რკინითა და კალციუმით მდიდარი მსუბუქი სადილი.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებას მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდად ყოფნა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'საგანძურით სავსე ჯიბეები 🍁', 'პარკიდან დაბრუნდით და მის ჯიბეში 3 ქვა, 1 გამხმარი ფოთოლი და ერთი ჩხირი იპოვეთ? მისთვის ეს ყველაფერი ძვირფასი საგანძურია. თქვენ კი უბრალოდ ეცადეთ, შეუმჩნევლად მოაშოროთ, სანამ მთელ სახლში მიმოფანტავს.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'ლოგიკას ნუ ეძებთ 👑', 'საუზმეზე ნაყინს ან გუშინდელ ოსპის წვნიანს ითხოვს? სახლში ახალი დიქტატორი გყავთ. არჩევანის უფლება მიეცით (მაგალითად: ვაშლი გინდა თუ ბანანი?) და ყურადღება სწრაფად გადაატანინეთ.'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'საწოლიდან გაქცევის საბაბები 🏃‍♂️', 'წყალი უნდა, ტუალეტში უნდა წასვლა, ოთახის ფარდისთვის კოცნა უნდა... მისი გონება ახალ მიზეზებს იგონებს, ოღონდ არ დაიძინოს. დააწესეთ ზღვარი: მხოლოდ 1 ჭიქა წყალი და მორჩა. იყავით მტკიცე.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'წარმოსახვითი საქმიანი ზარები 🍌', 'ხელში ბანანს ან პულტს იღებს და გამოგონილ ენაზე სერიოზული სახით ტელეფონზე საუბრობს? ის თქვენს სხეულის ენას ზუსტად იმეორებს. ვიდეო გადაუღეთ და მომავლისთვის შეინახეთ — ძალიან ბევრს იცინებთ.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'რეჟიმი ირევა? ⏱️', 'საღამოს ჩაძინებას 1 საათზე მეტი სჭირდება? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, დროა, დღის ძილი მთლიანად გააუქმოთ და საღამოს დაძინების დრო უფრო ადრე გადმოწიოთ.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'კბილის ჯაგრისის ომი 🪥', 'კბილის ჯაგრისის დანახვისას პირს მაგრად კეტავს? ჰიგიენას ბრძოლად ნუ აქცევთ. რეკომენდებულ პროდუქტებში მუსიკალური ჯაგრისები ნახეთ და ეს დამღლელი რუტინა სახალისო თამაშად გადააქციეთ.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', '„ფეხები აღარ მემორჩილება“ სიჯიუტე 🛑', 'პარკიდან დაბრუნებისას მოულოდნელად მიწაზე ჯდება, ამბობს, რომ ფეხები აღარ ემორჩილება და ხელში აყვანას ითხოვს? ეს დაღლილობა კი არა, მანიპულაციაა. უთხარით: „ვნახოთ, სახლამდე კურდღელივით ხტუნვით თუ მიხვალ?“ — და ყველაფერი თამაშად გადააქციეთ.'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'ქოთანთან დამალობანა 🚽', 'როდესაც ტუალეტში უნდა, ფარდის უკან ან დივნის გვერდით იმალება? სწორედ ახლაა საუკეთესო დრო, გადახვიდეთ ბლოგების განყოფილებაში და წაიკითხოთ, როგორ დაიწყოთ ქოთნის გამოყენების სწავლება მეცნიერულად დასაბუთებული ნაბიჯებით.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'დღიურში გულის გადაყოლება 📝', 'ვინმემ გითხრათ: „მთელი დღე სახლში ხართ, რა გღლით?“ დაუყოვნებლივ გახსენით განწყობის დღიური და მთელი ბრაზი თითებით ეკრანზე გადმოიტანეთ. ყალბ ღიმილს სჯობს, თქვენი ნამდვილი გრძნობები დაწეროთ.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'მამის ზღაპრების შოუ 📖', 'ამ საღამოს ოთახში თქვენი კი არა, მამის ხმა უნდა ისმოდეს. ზღაპარი მან წაიკითხოს და პერსონაჟების ხმების ხან დაბოხებით, ხან დაწვრილებით სახალისო წარმოდგენა მოაწყოს. თქვენ კი გვერდით დადექით და მათ სიცილს მოუსმინეთ.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'დედის საიდუმლო შოკოლადი 🍫', 'დედიკო, როგორც კი ბავშვი ზურგს შეგაქცევთ, პირში შოკოლადის ნატეხი ჩაიდეთ და სწრაფად დაღეჭეთ — ეს გლუკოზა თქვენი ყველაზე ბუნებრივი უფლებაა. მთელი დღე ამხელა ენერგიისთვის ფეხის ასაწყობად, თქვენც უნდა დაიმუხტოთ.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'უცნაური საუკეთესო მეგობარი 🥄', 'ამდენი ძვირადღირებული სათამაშოს მიუხედავად, ბავშვმა სამზარეულოში სილიკონის ნიჩაბი იპოვა, მთელი დღე თან დაატარებს და დასაძინებლადაც აწვენს? ბავშვის ტვინი საოცარია. ხელს ნუ შეუშლით — მიეცით საშუალება, თავისი ნიჩაბი უყვარდეს.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'ბუნებაში ძიება ⛅', 'ოთხ კედელში ყოფნამ გონება დაგიღალათ. ამინდისა და ტანსაცმლის გათვალისწინებით ყველაზე შესაფერისი კომბინაცია შეარჩიეთ. გარეთ გადით და მხოლოდ ყვითელი ფოთლის პოვნის მისიით ბავშვსაც დაახარჯვინეთ ენერგია და თავადაც ამოისუნთქეთ.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'სახიფათო სიტყვები 🤐', 'სადღაც გაგონილ ცუდ სიტყვას სიცილით გიმეორებთ და თქვენს რეაქციას ელოდება? თქვენი ყველაზე ძლიერი იარაღი რეაქციის არქონაა. ნუ გაიცინებთ, ნუ გაბრაზდებით — უბრალოდ ყურადღება არ მიაქციოთ. მალე დაივიწყებს.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'ოქროს სიჩუმის საზომი 🤫', 'ბოლოს და ბოლოს ჩაეძინა! ჩართეთ ხმის საზომი და ოთახში სიჩუმის აბსოლუტურ დონეს (0-10 desibel) ეკრანზე დააკვირდით. ამ რიცხვების ყურება დაღლილი დედის გონებისთვის საუკეთესო მასაჟია.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'ჯიუტი პიჟამა 👗', 'დილიდან საღამომდე დაბინძურებული და დალაქავებული პიჟამის გახდა არ სურს? 3 წლის ასაკში ესთეტიკას მნიშვნელობა არ აქვს. თუ არ სცივა, კიდევ რამდენიმე საათით ასე დარჩეს.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'მე ჭკვიან ზღაპარში 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით. გახსენით ჭკვიანი ზღაპრები, მთავარ გმირად თქვენი ბავშვი აქციეთ, დასაპყრობ ადგილად კი მისი ოთახი და ძილის წინ უჩვეულო თავგადასავალი შექმენით.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'მულტფილმების კრიტიკოსი 📺', 'ნანახ მულტფილმს თავისი გრამატიკით გიყვებათ და სერიოზულად გიხსნით, ვინ სად წავიდა. ყურადღებით და გაოცებული სახით მოუსმინეთ. აგრძნობინეთ, რომ მსოფლიოში ყველაზე ჭკვიანია.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'ისინი, ვინც მზეზე ადრე იღვიძებენ 🌅', 'ის დილის 6 საათზე უკვე ფეხზეა, თქვენ კი ძალა აღარ გაქვთ? ჰკითხეთ Anacan AI-ს, როგორ დაარეგულიროთ ეს რეჟიმი. გახსოვდეთ, უძილობა სამუდამოდ არ გრძელდება — ყველაფერი გაივლის.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'წყვილის შამპანური 🥂', 'ბავშვმა დაიძინა. შამპანური თუ არ გაქვთ, ჭიქებში ცხელი ჩაი ჩამოასხით და მეუღლესთან ერთად ჭიქები მიუჭახუნეთ სიტყვებით: „ეს რთული დღეც მშვიდობით დავასრულეთ“. თქვენ შესანიშნავი პარტნიორი ხართ.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'სიურპრიზი სიაში 🛒', 'მაღაზიაში წასვლამდე საყიდლების სია გახსენით და დაინახეთ, როგორ მოგიახლოვდათ უკნიდან, ტელეფონის ეკრანს დააჭირა და სიაში შოკოლადი დაამატა. დიახ, ტექნოლოგიები თქვენზე უკეთ იციან!'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'აბაზანაში თითების დანაოჭება 🛀', 'წყლით თამაში იმდენად სასიამოვნოა, რომ თითები დაუნაოჭდეს კიდეც, აბაზანიდან ამოსვლა მაინც არ უნდა. 5 წუთით ადრე გააფრთხილეთ და ტაიმერი დააყენეთ. წესი „ზარი რომ დაირეკება, ამოვდივართ“ ხშირად ამართლებს.'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'თმის დავარცხნის ბრძოლა 🪮', 'დილით გაიღვიძა და თმა ისე აქვს ყალყზე, თითქოს დენმა დაარტყა. სავარცხლის დანახვისთანავე კი გაქცევა იწყება. დავარცხნის ნაცვლად, სველი ხელებით თმა დაუმორჩილეთ და ბრძოლაც დაასრულეთ.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'ხელოვნური ინტელექტის აზრი 🤖', 'თქვენს ბავშვს უცნაური ჩვევა გაუჩნდა (მაგალითად, ფრჩხილების კვნეტა) და ინტერნეტში წაკითხულმა სტატიებმა შეგაშინათ? შეჩერდით. ჰკითხეთ Anacan AI-ს ამის რეალური, პედიატრების მიერ დადასტურებული მიზეზი და დამშვიდდით.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'ექიმი თქვენთანაა 🩺', 'სათამაშო სტეტოსკოპს იღებს, მკერდზე გადებთ და გეუბნებათ, რომ ჩაისუნთქოთ. თქვენ პაციენტი ხართ, ის კი მთავარი ექიმია. აჰყევით თამაშში, დაწექით და მკურნალობის დროს თუნდაც 5 წუთით თვალები დახუჭეთ და დაისვენეთ.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'ენერგიის მოზღვავება 🏃‍♂️', 'სახლში კედლებზე დაძვრება. შეამოწმეთ ამინდი, შესაფერისად ჩააცვით და აუცილებლად გაიყვანეთ გარეთ. ჟანგბადით მდიდარ გარემოში 30 წუთის განმავლობაში სირბილი საღამოს კარგი ძილის საუკეთესო გარანტიაა.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'ჩურჩულის მაგია 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. გვერდით მიუწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ჩურჩულით მოუყევით. ჩურჩული ტვინის ძილისთვის მოსამზადებელი ერთ-ერთი ყველაზე ბუნებრივი და დამამშვიდებელი მეთოდია.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'მამას ზურგზე ცხენობანა 🐴', 'ენერგია ბოლომდე ვერ დახარჯა და დასაძინებლად არ მიდის? მამას ზურგზე შემოჯდომა, სახლში ცხენივით ჭენება და გულიანი სიცილი ენერგიის განულების ყველაზე სწრაფი და სახალისო გზაა. ახლა მამას ჯერია.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'დედას სიმშვიდე სჭირდება 🩸', 'ყველა ხმა გაღიზიანებთ? მენსტრუაციის ტრეკერს გადახედეთ. თქვენს სხეულს დასვენება სჭირდება. ჯანსაღი რეცეპტებიდან მოამზადეთ მაგნიუმით მდიდარი წასახემსებელი და საკუთარ თავს დრო დაუთმეთ.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'უმიზეზო ტირილი 😭', 'თვალის გახელისთანავე უმიზეზოდ ტირის? ეს ჭირვეულობა კი არა, ემოციური გადატვირთვაა. გაესაუბრეთ ჩვენს Anacan AI ექსპერტს და გაიგეთ, როგორ მოიქცეთ კრიზისის დროს.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'მამას ჯერი სამზარეულოში 👨‍🍳', 'დღეს სადილის მომზადება და ბავშვის გამოკვება მამას ევალება! თქვენ კი ეს დრო საკუთარ თავს დაუთმეთ — უბრალოდ წამოწექით ან დაისვენეთ.'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'ძილი ბუნების ხმების თანხლებით 🪄', 'კლასიკური მუსიკა არ ჭრის? ჭკვიან ზღაპრებში გამორთეთ თხრობა და ჩართეთ მხოლოდ წვიმის ან ტყის ხმების ფონი. ბუნების მონოტონური ხმები ბავშვს თითქოს ჯადოსნურად აძინებს.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'დიდივით ოხვრა 😔', 'დივანზე ზის და უცებ, დიდივით, ღრმად სუნთქავს და ოხრავს. ისე კარგად გბაძავთ! უბრალოდ ღიმილით დააკვირდით მის ამ დრამატულ მიმიკებს.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'სიბნელესთან შეგუება 🌙', 'დაძინება რომ გაუადვილოთ, ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. ჰორმონ მელატონინის გამოყოფა მხოლოდ მშვიდ და ბნელ გარემოში ჩქარდება.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'დედის დამუხტვის დრო 🔋', 'ბავშვი დამოუკიდებლად აწყობს ფაზლს და უკვე 10 წუთია, ჩუმადაა. თქვენ კი გინდათ, ეს დრო სახლის დალაგებას დაუთმოთ. არა! წადით და დივანზე წამოწექით. თქვენც უნდა დაიმუხტოთ, რომ საღამომდე გაძლოთ.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'გამოგონილი გრამატიკა 🗣️', 'ბავშვმა „მე წავედიდი“ და „ის მოსულიყოობდა“ მსგავსი უცნაური და სასაცილო დროის ფორმები გამოიგონა. მისი ლექსიკური მარაგი ვითარდება! სიცილით ნუ შეუსწორებთ, უბრალოდ სწორი წინადადება გაუმეორეთ და ამგვარად დაუდასტურეთ.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'განწყობის დღიურში თავშეფარება 📝', 'ვერავინ ამჩნევს, ასე ძალიან რომ დაიღალეთ? აპლიკაციაში განწყობის დღიური ყოველთვის მზადაა, მოგისმინოთ. ჩამოწერეთ იქ ყველა ის წვრილმანი, რომელმაც დღეს გაგაგიჟათ, და გონება გაითავისუფლეთ.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'საკვებთან დაკავშირებული გამოცდები 🥣', 'დღეს ყველაფერს აფურთხებს, რასაც გუშინდლამდე სიამოვნებით ჭამდა. თუ კბილებთან დაკავშირებული პრობლემა არ აქვს, ეს უბრალოდ თქვენი ნებისყოფის გამოცდაა. ჯანსაღ რეცეპტებში მოძებნეთ გემრიელი, ფერადი კატლეტების რეცეპტები, რომლებშიც ბოსტნეული შეუმჩნევლადაა დამალული.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', '5 წუთის ილუზია ⏱️', 'ამბობს, რომ მხოლოდ კიდევ 5 წუთი უყურებს, მაგრამ მის გონებაში 5 წუთის ცნება ჯერ არ არსებობს. ტელეფონზე ტაიმერი დააყენეთ და აუხსენით, რომ ხმის გაგონებისას დრო ამოიწურება. დამნაშავე ტექნოლოგია იყოს და არა თქვენ.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'ტუალეტთან დაკავშირებული უკუსვლა? 🚽', 'ქოთნის გამოყენება უკვე ნასწავლი ჰქონდა, ახლა კი ისევ ვერ ასწრებს? ეს სრულიად ნორმალური უკუსვლაა. ნუ მოახდენთ ზეწოლას — ჰკითხეთ Anacan AI-ს, როგორ გადალახოთ ეს ფსიქოლოგიური ბარიერი კრიზისის გარეშე.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'მიიღეთ შთაგონება ბლოგებიდან 📱', 'განვითარების რა ნახტომები ახასიათებს ბავშვს, რომელიც 35 თვის ხდება? რისი გაკეთება უნდა შეეძლოს? გაეცანით აპლიკაციაში განთავსებულ განვითარების ბლოგებს და გაიხარეთ, როცა დაინახავთ, რამდენად წინ არის თქვენი შვილი.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'დიდი დღის სამზადისი 💆‍♂️', 'როცა ბავშვი დაიძინებს, მიულოცეთ ერთმანეთს პარტნიორთან ერთად ხვალინდელი მნიშვნელოვანი თარიღი და მხრები მსუბუქად დაუმასაჟეთ. საიუბილეო დღის ენერგიულად გასატარებლად აუცილებელია, ორივემ კარგად დაისვენოთ.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'ძილის წინ სირბილი 🏃‍♂️', 'დაძინების ნაცვლად დივანზე ხტუნავს? წყლის დალევის საბაბებსაც ბოლო არ უჩანს? ჩართეთ ძილის ტაიმერი და მტკიცედ დაიცავით დაწესებული საზღვრები.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'მამას თამაშის ჯერია 👨‍👧', 'დედობა დაუსრულებელი მარათონი არ არის. დღეს ბავშვს ენერგიის დახარჯვაში მამა დაეხმაროს პარკში, თქვენ კი დივანზე განმარტოებით დატკბით.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'ზამთრის ქუდები ზაფხულში 🧢', 'ამინდის სრულიად შეუფერებლად ჩაცმა სურს? დამოუკიდებლობისთვის ბრძოლაში რამდენიმე მარტივი არჩევანი შესთავაზეთ.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'დაუსრულებელი კითხვების მანქანა 🤔', '„რატომ?“ და „როგორ?“ კითხვები გონებას გიღლით? Anacan AI-სგან შეიტყვეთ, როგორ უპასუხოთ ბავშვის ცნობისმოყვარეობას ლოგიკურად ისე, რომ არ მოგბეზრდეთ. თქვენი მოთმინება მის განვითარებას უწყობს ხელს.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'სიჩუმის დღიური 📝', 'სახლის ქარიშხალმა როგორც იქნა დაიძინა. ახლა აიღეთ ტელეფონი და განწყობის დღიურში საკუთარ თავს მადლობის წერილი მისწერეთ იმისთვის, რომ დღევანდელ დღეს გაუძელით. თქვენ ამას შეძლებთ.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', '„მე თვითონ“ წინააღმდეგობა 🛑', 'ფეხსაცმლის თასმების დამოუკიდებლად შეკვრა სურს და ამას თქვენი 10 წუთი მიაქვს? ნუ იჩქარებთ, მიეცით დრო. ცდა და შეცდომა მომავალში პრობლემების გადაჭრის უნარის საფუძველია.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'ყავა და მედიტაცია ☕', 'ოთახი თავდაყირა დააყენა? დალაგებას თავი დაანებეთ. სანამ ბავშვი თავისით ერთობა, დივანზე მოკალათდით, ცხელი ყავა დალიეთ და უბრალოდ კედელს უყურეთ — 10 წუთით გონება განტვირთეთ.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'პროფესიების მიბაძვა 🩺', 'სათამაშო დათუნიას მკურნალობს ან მანქანებს არემონტებს? სიმბოლური თამაშები (როლური თამაშები) სრული დატვირთვით მიმდინარეობს.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'ჩრდილების თამაში 🐰', 'დაძინება არ სურს? ოთახი მთლიანად ჩააბნელეთ და კედელზე ხელებით ჩრდილების თეატრი მოაწყვეთ. ეს სიბნელის შიშის დაძლევის ყველაზე სახალისო გზაა.'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'ტატუები სხეულზე 🖍️', 'რამდენიმეწამიანი სიჩუმე ზოგჯერ სახიფათოა. ოთახში შესვლისას დაინახეთ, რომ ბავშვმა მკლავები ფლომასტერით მოიხატა? ღრმად ჩაისუნთქეთ. მისი ნატიფი მოტორული უნარები ვითარდება, კანი კი ისედაც ადვილად დაიბანება.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'მამა — თქვენი პარტნიორი 👨‍👧', 'საღამოსთვის ენერგია აღარ დაგრჩათ? თქვით: „მე ამ სცენარიდან გავდივარ“ და ბავშვი მამას გადააბარეთ. მათ მიერ ერთად არეული ოთახის დალაგება უფრო ადვილია, ვიდრე ბავშვთან მარტო გამკლავება.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'ბოჭკოს საჭიროება 💩', 'ბევრს დარბის, მაგრამ წყლის დალევა ავიწყდება. ქოთანში განავალს დააკვირდით. თუ შეკრულობის რისკი არსებობს, მენიუს შვრია და ქლიავი დაამატეთ.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'ჩრდილის შიში 👻', 'ქუჩაში ან ოთახში უცებ ატირდა? მიზეზი ისაა, რომ საკუთარი ჩრდილი დასდევს! 3 წლის ასაკის მოახლოებასთან ერთად ბავშვის წარმოსახვა უჩვეულო ხდება. ჩაეხუტეთ და ღიმილით გააცანით საკუთარი ჩრდილი.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'საკვების ქირურგი 🥦', 'საჭმელს არ ჭამს, უბრალოდ ქირურგიული სიზუსტით აცალკევებს მასში არსებულ ბრინჯის პატარა მარცვლებს ან მწვანე სანელებლებს. გადადით კვების გეგმაში და აღმოაჩინეთ ბოსტნეულის პიურედ ქცევის გზები.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'ყველაფერთან დამშვიდობება 🧸', 'დაძინებამდე სურს, ოთახში მანქანას, სკამსა და კარის სახელურსაც კი ღამე მშვიდობისა უსურვოს. ეს მის მიერ ათვისებული ძილზე გადასვლის ერთ-ერთი ახალი რიტუალია, ამიტომ ნუ დააჩქარებთ.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'სიჩუმის ფასი 🤫', 'ბავშვს როგორც იქნა ჩაეძინა. ახლა სახლში უმცირესი ხმაც კი გაღიზიანებთ. ხმის საზომით ოთახში ხმაურის ზღვრის დაყენებისას ფონად უწყვეტი თეთრი ხმაური ჩართეთ.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'თვლას ვიწყებთ 🔢', 'კიბეზე ასვლისას ან სათამაშოების დალაგებისას ცდილობს თქვას: ერთი, ორი, სამი? ასე მათემატიკური აზროვნების საფუძველი ყალიბდება. მასთან ერთად ოთახში არსებული ნივთები ხმამაღლა დაითვალეთ.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'ემოციური გადაწვის სინდრომი 🔋', 'ყველაფერზე ყვირილი გინდათ? თქვენ ემოციურ გადაწვას განიცდით. შედით Anacan-ის საზოგადოებაში და დაწერეთ: ძალიან დავიღალე. დაინახავთ, რომ იმავე წამს ათასობით ქალი გიცხადებთ თანადგომას.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'დღის ძილზე უარი 🥱', 'შუადღისას დაძინება საერთოდ არ სურს და გეწინააღმდეგებათ? 3 წლის ასაკის მოახლოებისას ზოგი ბავშვი დღის ძილზე უარს ამბობს. სცადეთ, ძილის რეჟიმი სიმშვიდის საათით (sleep-free quiet time) ჩაანაცვლოთ.'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'მოგონებები იღვიძებს 🧠', 'ამბობს წარსულთან დაკავშირებულ წინადადებებს, მაგალითად: გუშინ ბებიასთან ვიყავით? ეს დროის აღქმისა და ხანგრძლივი მეხსიერების ჩამოყალიბებაზე მიუთითებს. ინტერესით მოუსმინეთ მის მოგონებებს და კითხვები დაუსვით.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'შუაღამისას დახუჭული თვალებით ყვირის და ტირის?', 'ნუ ეცდებით მის გაღვიძებას. ხმა ტირილის ანალიზით შეამოწმეთ, დარწმუნდით, რომ ეს მხოლოდ ღამის შიშის ეპიზოდია და მშვიდად დარჩით მის გვერდით.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'სამზარეულოს კატასტროფები 🧑‍🍳', 'საჭმლის მომზადებისას აუცილებლად მოუნდება, ქურასთან დაგეხმაროთ და მარილი ჩაყაროს. თუ ნებას მისცემთ, კერძი გაფუჭდება, თუ არა — ატირდება. მიეცით ცარიელი ჯამი და წყალი და უთხარით: „შენი სუპი მოამზადე“.'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'თავისუფლების ჩანჩქერი 🥛', 'წყლის ან რძის ჭიქაში ჩასხმა აუცილებლად თვითონ უნდა და შედეგი? ირგვლივ ყველაფერი გუბეებად იქცევა. ღრმად ჩაისუნთქეთ. ეს ქაოსი მისი ხელისა და თვალის კოორდინაციისა და თავდაჯერების განვითარების საფასურია. ტილო მასაც მიეცით და უსიტყვოდ, ერთად დაალაგეთ.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'ხმაურისგან დეტოქსი 🎧', '„დედა, დედა, დედა!“ — ეს შეძახილები გონებაში ექოსავით ჩაგესმით? საკუთარ თავს მცირე კარანტინი გამოუცხადეთ. ბავშვი 15 წუთით უსაფრთხო საქმიანობით დააკავეთ, თქვენ კი ყავა სრულ სიჩუმეში დალიეთ. თქვენს ელემენტსაც სჭირდება დამუხტვა.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'ბანაობაზე უარის დაძლევა 🛁', 'აბაზანაში შესვლა არ უნდა, იატაკზე გორაობს და აპროტესტებს? ნაცვლად ფრაზისა „მოდი, დაგბან“, უთხარით: „წავიდეთ, შენი საყვარელი მანქანები (ან თოჯინები) ვაბანაოთ“. თამაშად ქცეული ვალდებულება ბავშვის წინააღმდეგობას ადვილად ამარცხებს.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'ფეხსაცმლის კრიზისი სახლში 👟', 'ტირის, რადგან ქუჩის ფეხსაცმლის სახლში ტარება უნდა და მის გახდაზე კატეგორიულ უარს ამბობს? ამაზე ომი არ ღირს. ძირები ნესტიანი ტილოთი გაუწმინდეთ და მიეცით საშუალება, რამდენიმე საათი ოთახში ამაყად იაროს. ზოგჯერ ბრძოლების შეგნებულად დათმობა სინამდვილეში დედის ყველაზე დიდი გამარჯვებაა.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'ახლა მამის ჯერია 👨‍🍼', 'მთელი დღე „არას“ თქმითა და წესების დაწესებით დაიღალეთ. ამ საღამოს პიჟამის ჩაცმისა და კბილების გახეხვის ბრძოლა მამას გადააბარეთ. ოთახის კარი მიხურეთ, განწყობის დღიურში უბრალოდ დღევანდელი გრძნობები ჩაიწერეთ და დრო მთლიანად საკუთარ თავს დაუთმეთ.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'ღიმილი საზოგადოებაში 💬', 'დღეს მისმა ჭირვეულობამ ნამდვილად გამოგფიტათ? დაუყოვნებლივ გახსენით Anacan-ის საზოგადოება და წაიკითხეთ სხვა დედების სახლებში მომხდარი მსგავსი, ზოგჯერ კი უფრო სასაცილო ჭირვეულობის ისტორიები. იმის ცოდნა, რომ ერთსა და იმავე გზას გადიხართ და მარტო არ ხართ, საუკეთესო ფსიქოლოგიური მხარდაჭერაა.'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'სიის შემოწმება 🛒', 'იუბილესთვის საჭირო ყველაფერი საყიდლების სიაში დაამატეთ? დარწმუნდით, რომ ბუშტები და პატარა სიურპრიზებიც სიაშია. პარტნიორს აპიდან ბოლო შეხსენება გაუგზავნეთ.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'სინათლის მაკონტროლებელი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ტვინის ყველაზე აქტიური პერიოდია. ხმის საზომის დახმარებით ოთახში შესაბამისი გარემო შექმენით. გაანეიტრალეთ ფანჯრიდან შემომავალი ხმები და უზრუნველყავით სრული სიმშვიდე და სიბნელე.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'ამბის რეჟისორი 🪄', 'ჩართეთ ჭკვიანი ზღაპრები და ამ საღამოს სიუჟეტის წარმართვა მას მიანდეთ. ჰკითხეთ: „ახლა გმირი სად წავიდეს?“ — და მიეცით საშუალება, თავისივე მოფიქრებულ აბსურდულ დასასრულთან ერთად თავადაც ჩაეძინოს.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'უმიზეზო ცრემლები 🐶', '15 წუთის განმავლობაში გულამოსკვნილი ტიროდა, რადგან ქუჩაში ნანახმა ძაღლმა არ შეხედა? ლოგიკას ნუ ეძებთ. მისთვის ეს ნამდვილად ღრმა მწუხარებაა. დაუდასტურეთ მისი გრძნობა და უთხარით: „ვიცი, გინდოდა, რომ მას შენთვის შემოეხედა“.'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'სახლის ქაოსთან შეგუება 🌪️', 'ოთახი სათამაშოებით არის მოფენილი? სისუფთავე კი არა, მასთან ერთად გატარებული ეს მხიარული წუთებია მნიშვნელოვანი. სათამაშოები ხვალაც იქ იქნება, თავს ნუ გადაიღლით. ზოგჯერ უწესრიგობასთან შეგუება საუკეთესო დასვენებაა.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', 'ნუ ტირი 🫂', 'როცა პარკში სხვა ატირებულ ბავშვს ხედავს, უახლოვდება და ეფერება? ემპათიის გრძნობა ოფიციალურად ამოქმედებულია! სიამაყით დააკვირდით მის ამ საოცარ თანაგრძნობას.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'დიდ საწოლზე გადასვლა? 🛏️', 'ბავშვი საწოლიდან გადმოძრომას ცდილობს? შესაძლოა, უკვე ფიქრობთ, დრო ხომ არ არის. ჰკითხეთ Anacan AI-ს დიდი ბავშვის საწოლზე გადასვლის უსაფრთხოების წესებისა და საუკეთესო დროის შესახებ.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'მამიკოს წიგნის საათი 📖', 'ამ საღამოს თქვენს ხმას დასვენების საშუალება მიეცით. ბავშვის საყვარელი წიგნების ხმის სხვადასხვა ტონით წაკითხვა მამიკოს მიანდეთ.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'რეჟისორი სარკის წინ 🎭', 'დგება სარკის წინ, სხვადასხვა მიმიკას აკეთებს და საკუთარ თავს ელაპარაკება? ის სხვადასხვა როლს ირგებს. ჩუმად დააკვირდით და დატკბით ამ სახალისო მომენტებით.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'ენერგიის შევსება გჭირდებათ 🍲', 'ყოველდღიურმა სირბილმა ძალა გამოგაცალათ. ჯანსაღი რეცეპტების განყოფილებიდან შეარჩიეთ რკინითა და ცილებით მდიდარი განსხვავებული სადილი, რომელიც თქვენც და ბავშვსაც მოგეწონებათ.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'დღის შეჯამება 📝', 'როგორც კი ბავშვი დაიძინებს, პარტნიორთან ერთად გახსენით განწყობის დღიური. ჩაიწერეთ ბავშვის დღევანდელი ყველაზე სასაცილო საქციელი, ერთად გაიღიმეთ და სტრესი მოიხსენით.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'მუსიკით ძილისთვის მომზადება 🛀', 'საღამოს რუტინა გართულდა? თბილი აბაზანის დროს ფონად მშვიდი კლასიკური მუსიკა ჩართეთ. წყლისა და მუსიკის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ამშვიდებს.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', '„გიპოვე!“ — სიხარულით 🙈', 'დამალობანა უკვე საყვარელი თამაშია. ბავშვი ფარდის უკან იმალება და ელოდება, როდის იპოვით. ამ ასაკში ასეთი თამაშები ობიექტის მუდმივობის აღქმას კიდევ უფრო ამყარებს.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'ისტერიკის მართვა 🛑', 'მაღაზიაში ან პარკში ბავშვის ისტერიკა უხერხულ მდგომარეობაში გაყენებთ? გახსოვდეთ, მნიშვნელოვანია არა ის, რას ფიქრობენ გარშემომყოფები, არამედ ბავშვის იმჟამინდელი ემოცია. მშვიდად ჩაეხუტეთ.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'პირად საზღვრებს აწესებს ✋', 'როდესაც ვინმეს მისი კოცნა სურს, თავს არიდებს ან უარს ამბობს? პატივი ეცით მისი სხეულის საზღვრებს და სხვებსაც მოსთხოვეთ იგივე. თავდაჯერებულობა სწორედ აქედან იწყება.'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'ჭკვიანი ზღაპრის მაგია 🪄', 'კლასიკური ზღაპრები მოგბეზრდათ? ჭკვიან ზღაპარს განსაკუთრებული თემა შეურჩიეთ: ბოსტნეულის მოყვარული ჯადოსნური დინოზავრის თავგადასავლები.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'ტანსაცმლის დიპლომატია 👗', 'ზამთრის შუაგულში საზაფხულო შარვლის ჩაცმა სურს? მაშინვე გახსენით ამინდისა და ტანსაცმლის ინსტრუმენტი და ეკრანზე გამოსახული ვიზუალური მასალის დახმარებით ლოგიკურად აუხსენით, რომ გარეთ ცივა.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'სთხოვეთ პარტნიორს დახმარება 🛒', 'საყიდლებზე წასასვლელად დრო არ გაქვთ? გახსენით საყიდლების სია, მონიშნეთ ყველაფერი, რაც სახლში გაკლიათ და ერთი დაწკაპუნებით გაუგზავნეთ პარტნიორს. მოვალეობების განაწილება აუცილებელია.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'ჩუმად წიგნების კითხვა 📖', 'ამ საღამოს ოთახში მხოლოდ წიგნის ფურცლების შრიალი ისმოდეს. ორივე საწოლში წამოწექით — ბავშვმა თავის სურათებიან წიგნს დაათვალიეროს, თქვენ კი სიჩუმეში დაისვენეთ.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'სახიფათო ნახტომები 🧗‍♂️', 'დივნის ზედაპირიდან იატაკზე გადმოხტომას ცდილობს? ის ზედმეტად ენდობა თავის მოტორულ უნარებს. აკრძალვის ნაცვლად, იატაკზე რბილი ბალიშები დააწყვეთ და უსაფრთხო სახტომი სივრცე შექმენით.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'წესების დარღვევის გამოცდა ⚠️', 'მიუხედავად იმისა, რომ უთხარით, ასე არ მოიქცესო, თვალებში გიყურებთ და მაინც იმავეს აკეთებს? მისი მიზანი თქვენი გაბრაზება კი არა, იმის შემოწმებაა, რამდენად მტკიცეა თქვენ მიერ დაწესებული საზღვრები. წესები თანმიმდევრულად დაიცავით.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'დაე, სახლი არეული დარჩეს 🌪️', 'დაიღალეთ ყოველდღე ერთი და იმავე სათამაშოების ალაგებით? დღეს ნუ აალაგებთ! არეული სახლი სამყაროს დასასრული არ არის, დედის ემოციური გამოფიტვა კი ნამდვილად სერიოზულია.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'დღევანდელი ჭკვიანი ზღაპარი 🪄', 'ჭკვიან ზღაპარს განსაკუთრებული თემა შეურჩიეთ: ჯადოსნური დათუნია, რომელსაც თავისი სათამაშოების ალაგება უყვარს. იქნებ ეს ამბავი ხვალინდელი დალაგებისას დაგეხმაროთ!'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'მამის რიტუალები 👨‍🍼', 'ბავშვებს მამებთან განსაკუთრებული რიტუალები აქვთ. ამ საღამოს დაძინების პროცესი მამის სახალისო წესებს მიანდეთ, თავად კი ოთახის გარეთ მშვიდად მიირთვით ჩაი.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'ფერების აღმოჩენა 🎨', 'ამბობს „ეს წითელია, ეს კი ლურჯი“ და ფერებს სწორად აჯგუფებს? ეს კოგნიტურ განვითარებაში დიდი წინსვლაა! განვითარების მონიტორინგის განყოფილებაში ეს მიღწევა სიამაყით მონიშნეთ.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'ერთად სამზარეულოში 🧑‍🍳', 'თქვენთან ერთად საქმის კეთება სურს? ჯანსაღი რეცეპტებიდან მარტივი კექსი შეარჩიეთ და ფქვილის ან წყლის დამატებაში დახმარების უფლება მიეცით. შეიძლება დასვრაც მოჰყვეს, მაგრამ გართობა გარანტირებულია.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'ღამის დეციბელები 🤫', 'ქუჩიდან შემოსული ხმები ხელს უშლის ღრმა ძილში ჩაძინებაში? ოთახში ხმაურის დონე ხმის საზომით შეამოწმეთ.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'ხელოვანი მუშაობის პროცესში 🖍️', 'კედლები და კარები ზოგჯერ მის სახატავ დაფად იქცევა. გაბრაზების ნაცვლად, იპოვეთ დიდი მუყაო, იატაკზე გაშალეთ და უთხარით: „ეს სივრცე შენია“. მისი შემოქმედებითი სურვილი სწორი მიმართულებით წარმართეთ.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'კითხვების ნიაღვარი 🤖', '3 წლის ასაკის მოახლოებასთან ერთად ბავშვის ქცევების შესახებ კითხვები არ გელევათ? Anacan AI თქვენი ციფრული პედიატრი და ფსიქოლოგია, რომელიც თქვენთვის 7/24 ფხიზლობს. მოგვწერეთ და პასუხი მყისიერად მიიღეთ.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'მიეცით ემოციებს გასაქანი 📝', 'თავს ძალიან მარტოსულად გრძნობთ და ფიქრობთ, რომ თქვენი არავის ესმის? ეს სრულიად ბუნებრივი განცდაა. გულწრფელად ჩაწერეთ თქვენი ემოციები განწყობის დღიურში.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'საკუთარ „მეს“ აღმოაჩენს 👑', '„მე ვარ!“, „ჩემია!“ — ეს სიტყვები მისი პირიდან არ ქრება. ეგოცენტრიზმის პერიოდი ახლა ყველაზე მკვეთრად ვლინდება. პატივი ეცით მის ინდივიდუალობას — ეს განვითარების ერთ-ერთი ეტაპია.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'ამინდი ცვალებადია ⛅', 'გასეირნება გსურთ, მაგრამ გარეთ ამინდი შეცდომაში შემყვანია? გახსენით ამინდისა და ტანსაცმლის ინსტრუმენტი და შეარჩიეთ ყველაზე შესაფერისი სამოსი, რომელიც ბავშვს არ გააოფლიანებს და ამავდროულად დაიცავს.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'გუნდური სიამაყე 🥂', 'რთული კვირა უკან მოიტოვეთ. დაჯექით თქვენს პარტნიორთან პირისპირ და გაამხნევეთ ერთმანეთი სიტყვებით: „ჩვენ ამ ბავშვს მართლაც კარგად ვზრდით“.'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'წინადადებებით ზღაპარს ჰყვება 🗣️', 'სურათებიან წიგნს ათვალიერებს, თავად იგონებს წინადადებებს და ზღაპარს თხზავს? მისი წარმოსახვა და მეტყველება ერთდროულად აყვავდა! ყურადღებით მოუსმინეთ და შეაქეთ.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'დედების სოლიდარობა 💬', 'Potty training-მა (ქოთანზე მიჩვევამ) სასოწარკვეთილებაში ჩაგაგდოთ? დაუყოვნებლივ შეუერთდით Anacan-ის საზოგადოებას. სხვა დედების წარმატებისა და წარუმატებლობის ისტორიები ძალას შეგმატებთ.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'სიბნელის შიში 🌙', 'ოთახის სიბნელის ეშინია? საწოლთან პატარა ღამის სანათი დაუდგით, თუმცა დარწმუნდით, რომ ოთახი საკმარისად ბნელია მელატონინის გამოსაყოფად.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'ტანსაცმლის თავად არჩევა სურს 👗', 'კარადას აღებს და ერთმანეთთან შეუსაბამო ფერებისა და სეზონების ტანსაცმლის შეხამება სურს? მხარი დაუჭირეთ მის დამოუკიდებლობას, თუმცა სიტუაციაზე კონტროლის შესანარჩუნებლად მხოლოდ 2 არჩევანი შესთავაზეთ.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'ყავის მუხტი ☕', 'დღის ძილი უკვე წარსულს ჩაბარდა და მთელი დღის განმავლობაში დასვენებას ვერ ახერხებთ? 15 წუთით უსაფრთხო აქტივობით დამოუკიდებლად დაკავების საშუალება მიეცით, თქვენ კი აუცილებლად შეივსეთ ენერგია ფინჯანი ყავით.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'მძიმე ტვირთი, ჯიუტი გული 🛒', 'გასეირნებიდან დაბრუნებისას ყველაზე მძიმე ნივთის ან ჩანთის თავად წამოღება სურს? ადგილიდან დაძვრაც რომ ვერ შეძლოს, თქვენს დახმარებაზე მაინც კატეგორიულ უარს ამბობს. მიეცით საშუალება, ცოტა იწვალოს და საკუთარი ძალები მოსინჯოს.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'პატარა ფილოსოფოსი 🤔', 'თვალები თითქმის დახუჭული ჰქონდა, როცა უეცრად თავი წამოსწია და ფილოსოფიური კითხვა დაგისვათ: „დედა, მზე სად მიდის დასაძინებლად?“ მისი ტვინი სამყაროს შესახებ ინფორმაციას დაძინების მომენტშიც კი ამუშავებს. ზედმეტ სიღრმეებში ნუ შეხვალთ — მოკლე და ზღაპრული პასუხი გაეცით.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'შეუძლებელი მოთხოვნები 🪄', 'დღეს დილით გაღვიძებისთანავე ყვირილით მოგთხოვათ, დაჭრილი ვაშლი ისევ მთლიანი გაგეხადათ? დიახ, 3 წლის ასაკის მოახლოებასთან ერთად მათი ლოგიკა ფიზიკის კანონებსაც კი უპირისპირდება.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'ცხოველების მიბაძვა 🐶', 'მხოლოდ ხმებს კი არ გამოსცემს, არამედ ძაღლივით დახოხავს და კატასავით გეფერებათ? აქ სხეულის ენა და წარმოსახვა ერთიანდება. შეუერთდით მას და ერთად ითამაშეთ ხალიჩაზე.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'საკვების არჩევითობა 2.0 🥣', 'დღეს უარს ამბობს წვნიანზე, რომელიც გუშინდლამდე უყვარდა? ნუ დააძალებთ. ჯანსაღი რეცეპტების განყოფილებაში იპოვეთ განსხვავებული ალტერნატიული რეცეპტები, რომლებშიც ბოსტნეულის შეუმჩნევლად დამატებას შეძლებთ.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'ძილის ჯადოსნური ზღაპარი 🪄', 'ჭკვიანი ზღაპრების განყოფილებაში შექმენით ამბავი მამაც გმირზე, რომელიც სამი წლის გასახდომად ემზადება, და აგრძნობინეთ ბავშვს, რომ იზრდება და ძლიერდება.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'გეძებ! 👀', 'ოთახიდან გასვლისთანავე ისევ ტირილს იწყებს? განშორების შფოთვა ზოგჯერ ბრუნდება. თქვენი ხმით შორიდან აგრძნობინეთ უსაფრთხოება, თუმცა არ ხართ ვალდებული, ყოველთვის მის თვალწინ იყოთ.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'ზღაპარი თავად დაასრულოს 📖', 'ამ საღამოს, ზღაპრის კითხვისას, წინადადებები დაუსრულებელი დატოვეთ და მიეცით ბავშვს მათი დასრულების საშუალება! ჰკითხეთ Anacan AI-ს დიალოგის ისეთი მეთოდების შესახებ, რომლებიც წარმოსახვის ამ საოცარ განვითარებას უწყობს ხელს.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'სია აუცილებელია 🛒', 'დაბადების დღისთვის საჭირო ნივთები არ დაგავიწყდეთ! ზედმეტად ნუ დაიტვირთავთ თავს — ყველაფერი დაუყოვნებლივ ჩაწერეთ საყიდლების სიაში და თქვენს პარტნიორთან დაასინქრონეთ.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'ახალი მეგობრების ძიება 👫', 'ცდილობს პარკში თანატოლებთან ერთად ირბინოს და მათ თამაშებში ჩაერთოს? სოციალიზაცია ოფიციალურად იწყება! გაამხნევეთ და ასწავლეთ, როგორ მიესალმოს სხვა ბავშვებს.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'ბუნების თერაპია დედისთვის 🌳', 'სახლის კედლები გახრჩობთ? ბავშვიც წაიყვანეთ და უახლოეს პარკში გაეშურეთ. სუფთა ჰაერი არა მხოლოდ ბავშვისთვის, არამედ თქვენი დაღლილი ნერვებისთვისაც საუკეთესო მასაჟია.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'წინდის ნაკერის ტრაგედია 🧦', 'დღეს დილით დიდი კრიზისით გავიღვიძეთ: წინდის შიგნით ნაკერი ფეხის თითზე ეხება! 3 წლის ასაკისკენ ემოციური მგრძნობელობა პიკს აღწევს. ლოგიკას ნუ ეძებთ — წინდა უკუღმა ჩააცვით და უყურეთ, როგორ დასრულდება ეს აბსურდული კრიზისი 10 წამში.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'გუბეებზე მონადირე 🌧️', 'წვიმის შემდეგ გარეთ გახვედით და ის პირდაპირ ტალახიან გუბეში ჩახტა? ტანსაცმელი დაესვარა, მაგრამ შეხედეთ, როგორ უბრწყინავს თვალები აღმოჩენის სიხარულით. ამინდი წინასწარ გაითვალისწინეთ და რეზინის ჩექმები ჩააცვით — მიეცით საშუალება, ბავშვობით დატკბეს.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'სათამაშოების ძილი ნებისა 🧸', 'ძილის დროა, მაგრამ ის ოთახში ყველა მანქანასა და დათუნიას სათითაოდ ემშვიდობება. ეს დაძინების გადადების ხელოვნების ნამდვილი შედევრია. დააყენეთ ტაიმერი და შემოიღეთ წესი: 3 წუთში ყველა სათამაშოს ერთდროულად ვემშვიდობებით.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'ყველაზე უცნაური ნივთი 🥄', 'ამდენი ძვირადღირებული სათამაშო აქვს, მაგრამ სამზარეულოში ჩამჩა იპოვა, მთელი საღამო თან დაატარებს და დასაძინებლადაც აწვენს. ბავშვის გონების ასეთი უცნაური გატაცებები აუხსნელია. ხელს ნუ შეუშლით — მიეცით საშუალება, ამ ჩამჩას თავისი სიყვარული გაუზიაროს.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'ქირურგი წვნიანში 🥣', 'საჭმელს არ ჭამს — მხოლოდ მასში მოხვედრილ ხახვის პატარა ნაჭრებსა თუ ბრინჯის მარცვლებს აცალკევებს ქირურგიული სიზუსტით. დროა, ბოსტნეული პიურედ აქციოთ და უხილავი გახადოთ. ჯანსაღი რეცეპტების განყოფილებაში გაეცანით დედების ყველაზე კრეატიულ რეცეპტებს დამალული ბოსტნეულით.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'კარადას მე გავაღებ! 🚪', 'დილით კარადის კარი თქვენ რომ გააღეთ, ატირდა, ისევ დაგაკეტინათ და შემდეგ თვითონ გააღო? დიახ, ყველაფერს თავად უნდა აკონტროლებდეს. ღიმილით შეხვდით მის უწყინარ მცდელობებს — „მე თვითონ გავაკეთებ!“ — ასე ის საკუთარ ნებისყოფასა და დამოუკიდებლობას გამოცდის.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'მამის პასუხისმგებლობა 👨‍🍼', 'თქვენ არ ხართ ვალდებული, ყველაფერი თავად გააკეთოთ. დღეს საღამოს კბილების გახეხვისა და პიჟამის ჩაცმის პროცესი მთლიანად მამას გადააბარეთ და გვერდიდან დააკვირდით.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'სიჩუმის ციფრული საზომი 🤫', 'როგორც იქნა, დაიძინა! სახლში გამეფებული სიჩუმე დაუჯერებელია. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს შეხედეთ — იგრძნობთ, როგორ ისვენებს და ძალებს იკრებს თქვენი გონება.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', '„შენ ცუდი დედა ხარ!“ — მტკივნეული დარტყმა 💔', 'სასურველი კანფეტი არ მიეცით და გითხრათ, რომ ცუდი ხართ? გულთან ახლოს ნუ მიიტანთ. მას ჯერ არ შეუძლია გრძნობების სწორად გამოხატვა და სინამდვილეში იმის თქმა სურს, რომ ძალიან გაბრაზებულია. დაამყარეთ თვალით კონტაქტი და აღიარეთ მისი ემოცია.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'საუბარი უხილავ ჭიანჭველასთან 🐜', 'აივანზე ან პარკში მიწაზე მყოფ ჭიანჭველასთან იხრება და ძალიან სერიოზულად ესაუბრება? ამ დროს წარმოსახვა და თანაგრძნობა ერთდროულად მუშაობს. დაუყოვნებლივ აღბეჭდეთ ეს საოცარი მომენტი ბავშვის ფოტოსესიით და არქივის ყველაზე საყვარელ კუთხეში შეინახეთ.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'მამის ფრენის რეჟიმი ✈️', 'სახლში ენერგია ვერ დახარჯა და დაძინებაზე უარს ამბობს. მამას მოუხმეთ დასახმარებლად. როდესაც ის ბავშვს ჰაერში აიტაცებს და თვითმფრინავობანას ეთამაშება, ოთახი სიცილით ივსება და დაგროვილი ფიზიკური დაძაბულობა წამებში ქრება.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'იატაკზე გორაობის თავისუფლება 🌪️', 'მაღაზიის შუაგულში იატაკზე გაწვა და ჭირვეულობს? ნუ ეცდებით მის წამოყენებას ან გარშემომყოფებისთვის ახსნა-განმარტების მიცემას. ღრმად ჩაისუნთქეთ. Anacan საზოგადოებაში შესვლისას დაინახავთ, რომ ათასობით დედა იმავე უხერხულ, თუმცა ბუნებრივ მომენტს განიცდის.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', '„ნუ მიყურებ!“ — სიჯიუტე 🙈', 'მხოლოდ იმიტომ, რომ შეხედეთ და გაუღიმეთ, ტირის და გეუბნებათ: „ნუ მიყურებ!“ აბსურდული ლოგიკის მწვერვალია! გვერდზე გაიხედეთ და დაელოდეთ, სანამ ეს სასაცილო ჭირვეულობა გადაივლის — ზოგჯერ თავადაც არ იციან, რა სურთ.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'დედის ხმის ძალა 🎶', 'ამ საღამოს არავითარი მოწყობილობა არ გამოიყენოთ. უბრალოდ გულში ჩაიკარით და ყურში მისი საყვარელი იავნანა ჩასჩურჩულეთ. თქვენი ხმა მისთვის ყველაზე უსაფრთხო ნავსაყუდელია.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'სწრაფი პედიატრიული მხარდაჭერა 🤖', '3 წლის ასაკთან მიახლოებისას ბავშვის სიმაღლისა და წონის გრაფიკი გაწუხებთ? ნუ დახარჯავთ საათებს ინტერნეტში ძიებაზე — Anacan AI-ისგან მყისიერად მიიღეთ ზუსტი, პედიატრების მიერ დადასტურებული ნორმები.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'თავისი სახელი და ასაკი იცის 🎂', 'როდესაც ეკითხებით: „რამდენი წლის ხარ?“, ცდილობს თითებით გაჩვენოთ? ეს საკუთარი თავის შესანიშნავ გაცნობიერებაზე მიუთითებს. მონიშნეთ ეს ინტელექტუალური ნახტომი განვითარების მონიტორინგში.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'შუქების ჯადოსნობა 🌙', 'სიბნელის შიში დაეწყო? ოთახი მთლიანად დააბნელეთ და პატარა ფარნით ჭერზე შუქებით ითამაშეთ. სიბნელე, რომლისაც ეშინია, გართობად და ძილის წინ პატარა აღმოჩენებით სავსე თავგადასავლად აქციეთ.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'პიჟამის სიყვარული 👗', 'დილით გაიღვიძა და ლაქებიანი პიჟამის გახდა კატეგორიულად არ სურს. თუ სახლიდან გასვლას არ აპირებთ, ნუ შეებრძოლებით. ზოგჯერ დედის ფსიქოლოგიური სიმშვიდე ბავშვის მოწესრიგებულ გარეგნობაზე გაცილებით მნიშვნელოვანია.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'ჯიბიდან ამოღებული საგანძური 🍁', 'პარკიდან დაბრუნდით და ბავშვის ჯიბეში 3 ქვა, 1 გამხმარი ფოთოლი და ერთი ჩხირი აღმოაჩინეთ. თქვენთვის ეს ნაგავია, მისთვის კი — საგანძური. შექმენით სპეციალური საკოლექციო ყუთი და ნება მიეცით, ისინი იქ შეინახოს, ნაცვლად იმისა, რომ მთელ სახლში მიმოფანტოს.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'ემოციური ტვირთისგან გათავისუფლება 📝', 'თქვენს სახლში ვერავინ ამჩნევს, რამდენად დაღლილი ხართ? განწყობის დღიური თქვენი ყველაზე ჩუმი მესაიდუმლეა. ჩაწერეთ მასში ყველა წვრილმანი, რომელმაც დღეს ჭკუიდან გადაგიყვანათ, და იგრძენით, როგორ გიმსუბუქდებათ გონება.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'მე თვითონ ვივლი! 🚶‍♂️', 'ქუჩაში ხელის ჩაკიდებაზე კატეგორიულ უარს ამბობს და თავისუფლებას აცხადებს. უსაფრთხო ადგილებში მიეცით ეს თავისუფლება. თვალი არ მოაშოროთ და აცადეთ, სამყარო საკუთარი ნაბიჯებით აღმოაჩინოს.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'სამზარეულოს პატარა მზარეული 🧑‍🍳', 'როცა ცომს აბრტყელებთ, აუცილებლად მოაქვს სკამი, თქვენ გვერდით დგება და პროცესში ერთვება? მიეცით ცომის პატარა ნაჭერი. ფქვილი ყველგან იქნება, მაგრამ მისი სერიოზული, საქმიანი გამომეტყველება შემდეგ დალაგებად ნამდვილად ღირს.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'უეკრანო შესვენების სირთულე 📺', 'დღეს საქმეების გამო ბავშვს ჩვეულებრივზე მეტი მულტფილმი აყურებინეთ და ახლა სინდისი გაწუხებთ? თავს ნუ დაიდანაშაულებთ. ყოველდღე იდეალური დედა ვერ იქნებით. ზოგჯერ ციფრული ძიძა ემოციური გამოფიტვისგან გიხსნით.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'ცოცხალი დიქტოფონი 🎙️', 'სიტყვა, რომელიც გუშინ პარტნიორთან საუბრისას შემთხვევით წამოგცდათ, დღეს დილით თავის სათამაშოს უთხრა! მისი ლექსიკური მარაგი საოცარი სისწრაფით იზრდება და ბავშვი ყველაფერში გბაძავთ. ნუ დაგავიწყდებათ, რომ მისთვის მაგალითი ხართ.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'ჩურჩულის ხრიკი 🤫', 'საწოლში იმდენად აქტიურია, რომ ვერ იძინებს. ხმის აწევის ნაცვლად, მოულოდნელად დაუწიეთ ხმას და ჩურჩულით ისაუბრეთ. როცა ბავშვი თქვენ გასაგონად ყურადღებას მოიკრებს, მისი ტვინი ავტომატურად ძილის რეჟიმზე გადაერთვება.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'ჟანგბადის საჭიროება ⛅', 'ოთხ კედელში ყოფნამ გონება დაგიღალათ და სახლში ისტერიკები დაიწყო. ამინდისა და ტანსაცმლის გათვალისწინებით შეარჩიეთ ყველაზე შესაფერისი სამოსი. გარეთ გასვლა და უბრალოდ სირბილი ბავშვს ენერგიის დახარჯვაში დაეხმარება, თქვენ კი ახალი ძალებით აგავსებთ.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'ზღაპარს ბავშვი მართავს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. ჩართეთ ჭკვიანი ზღაპრები: მთავარ გმირად თქვენი ბავშვი აქციეთ, გადასარჩენ ადგილად კი — მისი ოთახი. ასე უჩვეულო, მშვიდ და თავისუფალ ძილისწინა სეანსს შექმნით.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'ავანგარდული შემოქმედება 🖍️', 'რამდენიმეწამიანი სიჩუმე სახიფათო აღმოჩნდა. ოთახში შესულმა დაინახეთ, რომ ბავშვს ფლომასტერით ხელებზე ან მუცელზე ტატუები დაუხატავს. ღრმად ჩაისუნთქეთ. მისი ნატიფი მოტორიკა ვითარდება, კანი კი ისედაც ადვილად ჩამოიბანება.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'წყალი, წყალი ყველგან! 💧', 'აუცილებლად თვითონ უნდა ჩაესხა წყალი ჭიქაში. დაეღვარა და ყველაფერი დასველდა. მაგრამ შეხედეთ მის პატარა ხელებს, რომლებიც ტილოს აღებასა და იქაურობის გაწმენდას ცდილობენ. ის შეცდომების დაშვებით პასუხისმგებლობას სწავლობს, ამიტომ ნუ გაბრაზდებით.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'ახლა მამიკოს ჯერია 👨‍👧', 'დედობა დაუსრულებელი მარათონი არ არის. დღეს პარკში სირბილი მამას მიანდეთ, თქვენ კი დივანზე განმარტოებით დატკბით.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'გუნდური მასაჟი 💆‍♂️', 'ბავშვის დაძინების შემდეგ, დღის სტრესის მოსახსნელად, თქვენ და თქვენმა პარტნიორმა ერთმანეთს მხრების მასაჟი გაუკეთეთ. თქვენ მხოლოდ მშობლები არ ხართ — ამ სახლისა და ერთმანეთის ყველაზე დიდი მხარდამჭერებიც ხართ.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'დავიღალე... 🔋', 'ყველა თქვენგან ენერგიას ელის, მაგრამ თქვენი ელემენტი უკვე დაცლილია. დღეს ნურაფერს მოამზადებთ — შეუკვეთეთ მზა საჭმელი ან ყველაზე მარტივი მაკარონი მოხარშეთ. სუპერგმირობა არ ნიშნავს, რომ ყველაფერი მარტო უნდა გააკეთოთ.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'სიმშვიდე აბაზანაში 🛀', 'მთელი დღე „არ მინდას“ ძახილში გავიდა. თბილი აბაზანა მხოლოდ ჰიგიენისთვის არ არის — ის ბავშვის დაძაბულ ნერვულ სისტემას განტვირთვაში ეხმარება. მოუსმინეთ წყლის ხმას და ოთახში ატმოსფერო მყისიერად შეიცვლება.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'კიბეზე დამოუკიდებლად 🧗', 'ცდილობს კიბეზე დახმარების გარეშე ასვლას? მისი მოტორული უნარები პიკზეა! გვერდიდან დააკვირდით და ნუ ჩაერევით. ეს დამოუკიდებლობის წამი ბავშვის ფოტოსესიით უკვდავყავით.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'შოკოლადის სიურპრიზი სუპერმარკეტში 🛒', 'სუპერმარკეტში წასვლამდე საყიდლების სია გახსენით და დაინახეთ, როგორ მოგეპარათ ბავშვი უკნიდან, ტელეფონის ეკრანს დააჭირა და სიაში რაღაცები ჩაამატა. დიახ, ის თქვენს ციფრულ ცხოვრებასაც ბაძავს!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'გამოგონილი გრამატიკის ხიბლი 🗣️', 'მან „მე წავედიდი“, „ის მოდიოდადა“ და სხვა უცნაური, მაგრამ ძალიან საყვარელი დროის ფორმები გამოიგონა. მისი ლექსიკური მარაგი ქარიშხალივით იზრდება! განვითარების დღიურში მისი ეს განსაკუთრებული ენა სამახსოვროდ ჩაინიშნეთ.'),
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14', 'რა არის საწოლის ქვეშ? 👻', 'სჯერა, რომ სიბნელეში ურჩხულები იმალებიან? აიღეთ წყლით სავსე უბრალო ბოთლი და დაარწმუნეთ ბავშვი, რომ ეს „შიშის გამქრობი სპრეია“, შემდეგ კი ოთახში შეასხურეთ. ფანტაზია ფანტაზიით დაამარცხეთ.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'დილის 5 საათზე წვეულება დაიწყო! ⏰', 'მზე ჯერ არ ამოსულა, ის კი უკვე საწოლზე ხტუნავს და ახალ დღეს იწყებს. თქვენ ჯერ კიდევ გეძინებათ, ბავშვი კი მზადაა სამყაროს დასაპყრობად. შეუერთდით და მიეცით ამ გიჟურ ენერგიას თქვენი გაღვიძების საშუალება.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'საბავშვო ბაღს ეძებთ? 🏫', 'ბავშვი 3 წლის ხდება და საბავშვო ბაღზე ფიქრობთ, მაგრამ გადაწყვეტილებას ვერ იღებთ? თუ მარტო ფიქრით დაიღალეთ, შეუერთდით Anacan-ის საზოგადოებას და გაეცანით სხვა დედების რეალურ გამოცდილებას საბავშვო ბაღებთან დაკავშირებით.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'ემოციების აღრიცხვა 📝', 'ვინმემ გითხრათ: „მთელი დღე სახლში ხარ, რით იღლები?“ დაუყოვნებლივ გახსენით განწყობის დღიური და მთელი გაღიზიანება თითებით ეკრანზე გადმოიტანეთ. ხელოვნურად ღიმილს სჯობს, გულწრფელი გრძნობები დაწეროთ — ეს თერაპიულია.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'ყუთის ჯადოსნური ხიბლი 📦', 'ამდენად ძვირადღირებული, ხმოვანი სათამაშო უყიდეთ, ის კი უკვე 1 საათია, სათამაშოს ყუთით თამაშობს. ბავშვის ტვინს მზა სტრუქტურებზე მეტად მარტივი ნივთები მოსწონს, რომლებიც ფანტაზიის საშუალებას აძლევს. დააკვირდით და ისწავლეთ.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'ბუნებრივი თეთრი ხმაური 🤫', 'ჩაძინებისას მგრძნობელობა მატულობს. ქუჩიდან შემოსული ხმების გასანეიტრალებლად ოთახში ხმის საზომის ფონური ხმა ჩართეთ და მშვიდი ატმოსფერო შეინარჩუნეთ.'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'მოჩვენებითი ტირილი 🎭', 'სასურველის მისაღებად უცრემლოდ, აკანკალებული ხმით თავს გაჩვენებთ, თითქოს ტირის? ის თქვენზე ზემოქმედებას სწავლობს. შეიკავეთ თავი, რომ არ გაგეცინოთ, მაგრამ არც დაუთმოთ. მკაფიო საზღვრები დააწესეთ.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', 'უეცარი „მიყვარხარ“ 💖', 'ოთახის შუაგულში თამაშისას უცებ შემოგხედათ და გითხრათ: „ძალიან მიყვარხარ“? ეს ყველა უძილო ღამედ და დაღლილობად ღირს! დატკბით ამ წამით მოტანილი ღრმა და განუმეორებელი სიმშვიდით.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'მამას გიჟური ცეკვა 🕺', 'საღამოსკენ დაწყებულ გაღიზიანებას მხოლოდ მამა გაუმკლავდება. მუსიკა ბოლომდე აუწიონ და ბავშვთან ერთად ოთახში ხტუნვით იცეკვონ. თქვენ კი ამ მხიარულ ენერგიას გვერდიდან ამაყად უყურეთ.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', 'მხოლოდ თქვენთვის განკუთვნილი 10 წუთი ☕', 'სანამ მულტფილმითაა გართული, ჭურჭლის სარეცხი მანქანის ასავსებად ნუ გაიქცევით! წამოწექით დივანზე. როგორც იქნა, ყავა ცხელი მიირთვით და 10 წუთით დედის როლიდან გამოდით — უბრალოდ საკუთარი თავი იყავით.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'ბოსტნეულთან მტრობა გრძელდება 🥦', 'წვნიანში სტაფილოს ის პატარა ნაჭერი ისევ შეამჩნია და ჭამაზე უარი თქვა? კვების გეგმის დახმარებით ბოსტნეულის პიურედ ქცევა და კატლეტში დამალვა დედების ერთ-ერთი უძველესი და სასარგებლო ხრიკია. სცადეთ!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'პატარა ექიმი გასინჯავთ 🩺', 'სათამაშო სტეტოსკოპს იღებს, მკერდზე გადებთ და გთხოვთ, ჩაისუნთქოთ. თქვენ პაციენტი ხართ, ის კი — მთავარი ექიმი. აჰყევით თამაშში, წამოწექით და მკურნალობისას თუნდაც 5 წუთით დახუჭეთ თვალები და დაისვენეთ.'),
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06', 'ხმაურის ლიმიტი 🌙', 'როგორც იქნა, დაიძინა. ახლა სახლში უმცირესი ხმაც კი გაშფოთებთ. ჩააქრეთ განათება, გამორთეთ ტელევიზორი და სიბნელეში დატკბით ამ იშვიათი, ტკბილი სიჩუმით.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('19419b9a-b627-43ae-9610-e43b875264b1'::uuid, 'მიზანმიმართული ხოხვა და სირბილი 🐢', 'ახლა მხოლოდ სიარული აღარ აკმაყოფილებს — სწრაფად გარბის, გემალებათ და კარს უკანიდან იჭყიტება. ოთახიდან დაბრკოლებები მოაშორეთ და თქვენც დიდი ბავშვის ენერგიით ჩაერთეთ ამ დაჭერობანას თამაშში.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'ჩააქრეთ შუქი, რომ ძილი მოვიდეს 🌙', 'დაძინება რომ გაუადვილოთ, ოთახში ყველა ზედმეტი განათება და ლურჯი ეკრანი გამორთეთ. ძილის ჰორმონი (მელატონინი) სწრაფად მხოლოდ ჩაბნელებულ და ტექნოლოგიებისგან თავისუფალ გარემოში გამომუშავდება.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'ხელოვნური ინტელექტი, რეალური პასუხი 🤖', 'თქვენს ბავშვს უცნაური ჩვევა გაუჩნდა (მაგალითად, ფრჩხილების კვნეტა) და ინტერნეტფორუმებმა შეგაშინათ? შეჩერდით. Anacan AI-ს ჰკითხეთ ამის რეალური, პედიატრის მიერ დადასტურებული მიზეზი და დამშვიდდით.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'თავისუფლება პარკში 🌳', 'ოთხ კედელში ყოფნა მას აგრესიულს ხდის. წაიყვანეთ პარკში, მიეცით საშუალება, ქვიშაში ამოიგანგლოს, სირბილისას წაიქცეს და ქვები შეაგროვოს. ბუნებაში განცდილი ეს თავისუფლება მისი ტვინის განვითარებისთვის საუკეთესო წამალია.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'მელატონინის ქარხანა 🌙', 'უფრო სწრაფად რომ ჩაეძინოს, ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ მშვიდ, სუსტად განათებულ და ეკრანებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'წარმოსახვითი სტუმრები მოვიდნენ ☕', 'ოთახში მარტო მყოფი თავის უხილავ მეგობრებს ესაუბრება და ჩაის უსხამს? ეს წარმოსახვის განვითარების მწვერვალია! სიამაყით ადევნეთ თვალი ამ შესანიშნავ სცენარისტს — ის უკვე საკუთარ სამყაროს ქმნის.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'მოდი, აგიხსნი! ☝️', 'მოდის და იმას, რაც თქვენ უკვე იცით, ძალიან სერიოზული და ჭკვიანური გამომეტყველებით გიხსნით. ასე ის საკუთარ ცოდნას ამოწმებს. სიცილის შეკავება რომც გაგიჭირდეთ, ძალიან სერიოზულად მოუსმინეთ.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'გულახდილი ჩანაწერი განწყობის დღიურში 📝', 'აიღეთ ტელეფონი. სოციალურ ქსელში სხვების ცხოვრების თვალიერების ნაცვლად, გახსენით განწყობის დღიური და მომავლისთვის ჩაინიშნეთ დღევანდელი ყველაზე სასაცილო რამ, რაც მან გააკეთა. ციფრული თერაპია ნამდვილად მუშაობს.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'ამბოხი შუადღის ძილის წინააღმდეგ 🥱', 'დაძინება არაფრით უნდა? 3 წლის ასაკის მოახლოებისას ასეთი წინააღმდეგობა ძალიან ტიპურია. ნუ აიძულებთ და ნუ აატირებთ. ოთახში განათება შეამცირეთ, „წიგნების ჩუმად თვალიერების საათი“ გამოაცხადეთ და რუტინა შეცვალეთ.'),
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656', 'საკუთარი თავის დავიწყება აკრძალულია! 🥗', 'მის დასანაყრებლად 3 განსხვავებული მენიუ მოიფიქრეთ, თავად კი ისევ მშიერი დარჩით? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინითა და კალციუმით მდიდარი სადილი, რომელიც 10 წუთში მზადდება, და იზრუნეთ საკუთარ თავზე.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'ბრაზის უეცარი აფეთქება 💥', 'თამაშის დროს მოულოდნელად გაბრაზდა და სათამაშოების სროლა დაიწყო? მას ჯერ კიდევ არ შეუძლია ემოციების მართვა. ყვირილის ნაცვლად, თანაგრძნობა გამოიჩინეთ და უთხარით: „ვხედავ, რომ გაბრაზდი. მოდი, ერთად ღრმად ჩავისუნთქოთ“.'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'წყვილის შამპანური 🥂', 'ბავშვს ჩაეძინა. შამპანური თუ არ გაქვთ, ჭიქებში ცხელი ჩაი ჩამოასხით და პარტნიორთან ერთად ჭიქები მიაჭახუნეთ სიტყვებით: „ეს რთული დღეც მშვიდობიანად დავასრულეთ“. თქვენ ამ სახლის უძლიერესი მხედართმთავრები ხართ.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', '3 წლის იუბილემდე ბოლო 5 დღე! 🚀', 'დაუჯერებელია! დიდ 3 წლის იუბილემდე სულ რაღაც 5 დღე დარჩა. ეს პატარა პიროვნება, რომელიც სახლში საკუთარ წესებს ადგენს, თქვენ გაზარდეთ. ტორტი Anacan-იდან ახლავე შეუკვეთეთ და სამზადისს შეუდექით.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'მამის ფრენის რეჟიმი ✈️', 'სახლში ენერგია ვერ დახარჯა და დაძინებას ეწინააღმდეგება. მამას დახმარება სთხოვეთ. როცა ის ბავშვს ჰაერში აიყვანს და თვითმფრინავივით „გააფრენს“, ოთახი სიცილით ივსება და ფიზიკური დაძაბულობა წამებში ქრება.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'დედის შესვენება ☕', 'ბავშვის ენაზე ლაპარაკით დაიღალეთ. დედების მეგობარ ადგილებს შორის იპოვეთ კაფე საბავშვო კუთხით, მიირთვით ყავა, სხვა დედებს გულახდილად გაესაუბრეთ და ცოტა ამოისუნთქეთ.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'განშორების შფოთვა ისევ? 🥺', 'ოთახიდან სულ რამდენიმე წამითაც რომ გახვიდეთ, ბავშვი უკან მოგყვებათ და ტირის. 3 წლის ასაკის მოახლოებისას განშორების შფოთვა ზოგჯერ ისევ იჩენს თავს. ყოველ ჯერზე გამოეხმაურეთ და შორიდან დაამშვიდეთ — უთხარით, რომ იქვე ხართ: „სამზარეულოში ვარ, მალე მოვალ“.'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'სიმშვიდის დასტური 🤫', 'ხმაურიანი დღის შემდეგ, როცა ბავშვი დაიძინებს, ხმის საზომი მოწყობილობით ოთახში ხმაურის დონე გაზომეთ. ნულთან მიახლოებული რიცხვების დანახვაც კი დედის ტვინზე საუკეთესო ვიზუალური მასაჟივით მოქმედებს.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'სრულყოფილების წნეხი 🛑', 'სხვა ბავშვები უკვე ფერებს ითვლიან, თქვენს ბავშვს კი ეს არ სურს? დაუყოვნებლივ შეწყვიტეთ შედარება! ყველა ბავშვს განვითარების საკუთარი ტემპი აქვს. თქვენი ბავშვი თავისი ტემპით ვითარდება და ეს სრულიად ნორმალურია.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'გამარჯვებისთვის მზადება 💆‍♂️', 'ბავშვის დაძინების შემდეგ, დღის სტრესის მოსახსნელად, თქვენ და თქვენმა პარტნიორმა ერთმანეთს მხრების მასაჟი გაუკეთეთ. ხვალინდელი 3 წლის იუბილესა და ფუსფუსისთვის ორივეს აუცილებლად ბევრი ენერგია დაგჭირდებათ!'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'დედების მხარდამჭერი ჯგუფი 💬', 'რთული დღე გაქვთ და ყველაფერი გადაულახავად გეჩვენებათ? Anacan-ის საზოგადოებაში გამოცდილი დედების რჩევები რეალური ცხოვრებიდან აღებული, ყველაზე პრაქტიკული გამოსავალია, რომელსაც ვერცერთ წიგნში ვერ იპოვით — შთაგონება იქ მოიძიეთ.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', '3 წლის გახდომის წინა დღე! 🎂', 'ხვალ დიდი დღეა! რამდენად გრძელი გზა გამოიარეთ იმ დღიდან, როცა პირველად იგრძენით მისი მოძრაობა მუცელში. დღეს დიდხანს უყურეთ, ტანსაცმელი შეურჩიეთ და ხვალინდელი ბავშვის ფოტოსესიისთვის ტელეფონში მეხსიერება გაათავისუფლეთ.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'შეეგუეთ სახლის ქაოსს 🌪️', 'ოთახი მთლიანად სათამაშოებითაა მოფენილი? სისუფთავეზე მნიშვნელოვანი მასთან ერთად გატარებული ეს მხიარული წუთებია. სათამაშოები ხვალაც იქ იქნება, თავს ნუ გადაიღლით. ზოგჯერ არეულობასთან შეგუება საუკეთესო დასვენებაა.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'მამის საიდუმლო ტაქტიკა 👨‍🍼', 'დღის დაღლილობაც გეყოფათ. საღამოს ბავშვის დასაძინებლად მომზადება და კბილების გახეხვა მამას და მის თამაშით სავსე ხრიკებს მიანდეთ, თქვენ კი გვერდზე მშვიდად დაისვენეთ.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'უცნაური საუკეთესო მეგობარი 🥄', 'ამდენი ძვირადღირებული სათამაშოს მიუხედავად, სამზარეულოში სილიკონის ნიჩაბი იპოვა, მთელი დღე თან დაატარებს და აძინებს კიდეც? ბავშვის გონება საოცარია. ხელს ნუ შეუშლით — დაე, უყვარდეს თავისი ნიჩაბი.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'ჩურჩულით დაძინება 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. გვერდით მიუწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ყურში ჩასჩურჩულეთ. ჩურჩული ყველაზე ბუნებრივი და ეფექტური მეთოდია, რომელიც ტვინს ძილისთვის ამზადებს და ხმაურს ავიწყებს.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'სიურპრიზი სიაში 🛒', 'მაღაზიაში წასვლამდე საყიდლების სია გახსენით და დაინახეთ, როგორ მოგიახლოვდათ უკნიდან, ტელეფონის ეკრანს დააჭირა და სიაში შოკოლადი დაამატა. დიახ, ტექნოლოგიები თქვენზე უკეთ იციან!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'მიზანმიმართული ნგრევა 🧱', 'დიდი მონდომებით აშენებს კოშკს, შემდეგ კი სიცილით ერთი ხელის მოსმით ანგრევს. ასე ის ფიზიკასა და მიზეზშედეგობრივ კავშირებს სწავლობს. ნუ გაბრაზდებით — დანგრეული კოშკები მის ტვინში წარმოქმნილი ახალი ნეირონული კავშირებია.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'აღნიშნეთ პარტნიორთან ერთად 🥂', 'ამ საღამოს პარტნიორთან ერთად აღნიშნეთ ამ 3 წლის დაღლილობა, ცრემლები და სიხარული. სუფრაზე სანთელი აანთეთ და ღიმილითა და დიდი სიხარულით იზეიმეთ თქვენი ურყევი გუნდის გამარჯვება!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'შესანიშნავი 3 წელი! 👑🎉', 'გილოცავთ! ის უკვე 3 წლისაა! ზუსტად 1095 დღეა, რაც ამ ქარიშხლიან, დამღლელ, მაგრამ მსოფლიოში ყველაზე ტკბილ გზას მიუყვებით! დაუყოვნებლივ აქციეთ ეს განსაკუთრებული დღე დღესასწაულად და თქვენი სიხარული ყველას გაუზიარეთ!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'თქვენ შეუდარებელი ხართ! 📈', 'რამხელა გზა გაიარა თქვენმა ბავშვმა! პირველი დღეების მყიფე შიში ახლა უზარმაზარმა თავდაჯერებამ და ცოდნამ ჩაანაცვლა. ეს 3 წელი დიდი სიამაყით გამოიარეთ! თქვენ მართლაც შესანიშნავი დედა ხართ!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'დღესასწაულის შემდგომი რეალობა 🚀', 'გუშინდელი დიდი იუბილეს შემდეგ ამ დილით ისევ მიმოფანტულმა სათამაშოებმა და შეძახილებმა — „ჩაცმა არ მინდა!“ — გაგაღვიძათ. ცხოვრება ჩვეულ რიტმს დაუბრუნდა. ღრმად ჩაისუნთქეთ — ამ ქაოსს თქვენ ყველაზე უკეთ მართავთ.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'ზღაპარს ის მართავს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. მოიგონეთ ჭკვიანური ზღაპრები, რომლებშიც მთავარი გმირი თქვენი ბავშვი იქნება, გადასარჩენი ადგილი კი — მისი ოთახი. ასე შექმნით უჩვეულო, მშვიდ და თავისუფალ ძილისწინა რიტუალს.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', '„მე თვითონ!“ — დაჟინება 🛑', 'ფეხსაცმლის თასმების თავად შეკვრა სურს და ამას თქვენი 10 წუთი მიაქვს? ნუ იჩქარებთ, მიეცით დრო. მცდელობა და შეცდომა მომავალში პრობლემების გადაჭრის უნარის საფუძველია.'),
  ('aa798243-c44e-4178-957c-647030916048', 'ამინდის გაფრთხილება ⛅', 'სასეირნოდ გასვლისას მხოლოდ ფანჯრიდან დანახულ ამინდს ნუ ენდობით. ამინდისა და ჩაცმულობის დამხმარის მეშვეობით გარეთ არსებულ ქარსა და ტემპერატურას ყველაზე შესაფერისი სამოსი შეურჩიეთ და სახლიდან მშვიდად, სათანადოდ მომზადებული გახვიდეთ.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'მულტფილმების კრიტიკოსი 📺', 'ნანახ მულტფილმს თავისი გრამატიკით გიყვებათ და სერიოზულად გიხსნით, ვინ სად წავიდა. ყურადღებით და გაოცებული სახით მოუსმინეთ. აგრძნობინეთ, რომ მსოფლიოში ყველაზე ჭკვიანია.'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'სიბნელის ძალა 🌙', 'დაძინება რომ გაუადვილდეს, ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'პრეტენზიული გურმანები 🥦', 'დღეს უარს ამბობს საჭმელზე, რომელიც გუშინ უყვარდა? 3 წლის ასაკში საკვების მიმართ ჭირვეულობა ნორმალურია. ჯანსაღ რეცეპტებში მოძებნეთ ფერადი, განსხვავებული და სახალისო გაფორმების იდეები, რომლებიც დააინტერესებს.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'წარმოსახვის ძალა ფრენაშია 🚀', 'ის უკვე უბრალოდ კი არ თამაშობს, არამედ სცენარებსაც ქმნის! მუყაოს ყუთი ერთ წამში კოსმოსურ ხომალდად იქცევა. განვითარების მონიტორინგში სიამაყით აღნიშნეთ ეს კოგნიტიური ნახტომი და მის თამაშში ჩაერთეთ.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'დღის შეჯამება 🌙', 'დაძინებამდე განათება შეამცირეთ და ისაუბრეთ იმაზე, თუ რამ გაგაცინათ დღეს ყველაზე მეტად. ძილის წინ ეს პატარა საუბრები აზრის გამოხატვის უნარს უვითარებს.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'მამის ფრენის რეჟიმი ✈️', 'სახლში დარბის და საწოლში დაწოლაზე უარს ამბობს. მამას დახმარება სთხოვეთ. როცა ის ბავშვს ჰაერში აიყვანს და თვითმფრინავივით „გააფრენს“, ოთახი სიცილით ივსება, მთელი დაგროვილი ფიზიკური აგრესია კი ოფლთან ერთად წამებში ქრება.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'რეჟისორობა დილის 6 საათზე 🎬', 'თქვენ ჯერ კიდევ გძინავთ, ის კი თავზე გადგათ: „შენ დათვი იყავი, მე კი კურდღელი!“ ნახევრად მძინარემ, ღრენის ხმების გამოცემით, ამ აბსურდულ სპექტაკლში თქვენი როლი შეასრულეთ. დედობა ზოგჯერ საუკეთესო სამსახიობო ოსტატობას მოითხოვს.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'საზოგადოების თანადგომა 💬', 'ძალიან დაიღალეთ და არავისთან არაფრის ახსნა არ გსურთ. შედით Anacan-ის საზოგადოებაში და უბრალოდ მკითხველად დარჩით. სხვა დედების მსგავსი დაღლილობის დანახვა გაგიჩენთ განცდას — „მე მარტო არ ვარ“ — და საუკეთესო თერაპიად იქცევა.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'სიჩუმის ციფრული სიამოვნება 🤫', 'როგორც იქნა, დაიძინა! სახლში ჩამოწოლილი სიჩუმე იმდენად ღრმაა, რომ ყურები გიგუბდებათ. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს უყურეთ — ასე თვალნათლივ იგრძნობთ, როგორ მშვიდდება და ნელ-ნელა აღდგება თქვენი ტვინი.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', 'სუპერმარკეტში: „მე წავიყვან!“ 🛒', 'აუცილებლად თვითონ უნდა ატაროს საყიდლების ურიკა, რის გამოც თაროებს ეჯახებით. მისი ნებისყოფა რომ არ დათრგუნოთ, ურიკა ერთად მართეთ. რაიმე რომ არ დაგავიწყდეთ, აპში საყიდლების სია გახსნილი დატოვეთ.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'დაასრულეთ დაუსრულებელი წინადადებები 🗣️', 'როცა სიტყვა ავიწყდება, ხელებით განიშნებთ და ელოდება, რომ თქვენ გამოიცნობთ? დააკვირდით, როგორ შვებას გრძნობს, როცა ეუბნებით: „ააა, ბურთს გულისხმობ?“ მისი ლექსიკური მარაგი იზრდება, უბრალოდ ტვინი ენაზე სწრაფად მუშაობს.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'ბუნების დეტოქსი აუცილებელია 🌳', 'ოთხ კედელს შორის მისი ენერგია აგრესიად გარდაიქმნება. ამინდისა და ჩაცმულობის მიუხედავად, სათანადოდ მოამზადეთ და აუცილებლად გაიყვანეთ გარეთ. მიწასთან შეხება და ფოთლების შეგროვება მის ნერვულ სისტემას მყისიერად ამშვიდებს.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'ჩურჩულის მისტიკური ძალა 🌙', 'ზღაპრების კითხვით თქვენი ხმოვანი იოგები დაიღალა. ოთახში სინათლე მთლიანად ჩააქრეთ. გვერდით მიუწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ყურში ჩასჩურჩულეთ. ჩურჩული ტვინის ძილისთვის მომზადების ყველაზე დამამშვიდებელი გზაა.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'საოცარი არსება 🎈', 'ამხელა გზაზე გასაოცარი მართლაც ბევრია. მაგალითად, გუშინ ნასწავლი სიტყვის დღეს ფილოსოფიურ წინადადებაში გამოყენება! ეს დღეები აღარ განმეორდება.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'შოკოლადის ფარული შესვენება 🍫', 'დედა, რომელიც სამზარეულოს კარადის უკან ბავშვისგან მალულად მიირთმევთ შოკოლადს, ეს გლუკოზა თქვენ გეკუთვნით. თავს ნუ გაკიცხავთ! ამ გიჟურ ენერგიას რომ გაუმკლავდეთ, თქვენც აუცილებლად უნდა დაიმუხტოთ. ღრმად ჩაისუნთქეთ და განაგრძეთ ღეჭვა.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'ჭკვიან ზღაპარში მთავარი გმირი თავადაა 🪄', 'ამ საღამოს ჭკვიან ზღაპარში მთავარ გმირს პირდაპირ თქვენი ბავშვის სახელი დაარქვით. მოუყევით, რომ ზღაპრის პერსონაჟმაც არ გაიხეხა კბილები და შემდეგ ინანა — ასე საჭირო ღირებულებებს ირიბად ჩაუნერგავთ.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'ტუალეტის ქაღალდის ინჟინერი 🧻', 'რამდენიმეწუთიანი სიჩუმე... ოთახში შესვლისას კი ხედავთ, რომ ტუალეტის ქაღალდი მთლიანად გაუშლია და მთელ სახლში მიმოუფანტავს! გაბრაზების ნაცვლად, შეაგროვეთ ქაღალდები და ერთად გააკეთეთ თოვლის კაცი. ქაოსი შემოქმედებითობით დაამარცხეთ.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'შენ ბავშვი იყავი, მე — დედა 👩‍👧', 'როლების გაცვლის თამაში დაიწყო! ახლა ის გაძლევთ მითითებებს: „აქ მოდი“, „საჭმელი ჭამე“. დიდი სიამოვნებით მიეცით ლიდერობის გამოცდილების მიღების საშუალება და უხმოდ შეასრულეთ მისი ბავშვის როლი.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'ხელოვნური ინტელექტი, რეალური გამოსავალი 🤖', 'რატომ შეიძლება 3 წლის ბავშვმა მოულოდნელად დაიწყოს ფრჩხილების კვნეტა? დაივიწყეთ ინტერნეტში გავრცელებული შემაშინებელი და ტრავმული სტატიები. ჰკითხეთ Anacan AI-ს, ხომ არ არის ეს უბრალოდ სტრესზე დროებითი რეაქცია, და მიიღეთ მეცნიერულად დასაბუთებული პასუხი.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'დრო წყვილისთვის 🥂', 'ბავშვმა დაიძინა. ახლა ტელეფონები და საოჯახო საქმეები გვერდზე გადადეთ. პარტნიორთან პირისპირ დაჯექით და სულ რაღაც 20 წუთის განმავლობაში ისაუბრეთ ნებისმიერ თემაზე, გარდა გადასახადებისა და ბავშვისა. გახსოვდეთ, თქვენ წყვილიც ხართ!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'ჯიბეში ნაპოვნი განძი 🪨', 'შარვლის რეცხვისას ჯიბიდან 3 სხვადასხვა ზომის ქვა და წაბლის ერთი ნაჭუჭი ამოიღეთ? მისთვის ეს მსოფლიოში ყველაზე ძვირფასი კოლექციაა. გადაყრის ნაცვლად, პატარა ყუთში მოუყარეთ თავი და საგანძურის სკივრი შექმენით.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'ჩააქრეთ შუქი, მოიხმეთ ძილი 🌙', 'იმისთვის, რომ ბავშვმა უფრო სწრაფად დაიძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა ზედმეტი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი (ძილის ჰორმონი) სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'ემოციური გამოფიტვის განცდა 🔋', 'გინდათ, ყველაფერზე იყვიროთ? ხმაური თითქოს ტვინს გიხვრეტთ? ეს ნამდვილად ემოციური გამოფიტვაა. ბავშვი დაუყოვნებლივ უსაფრთხო ადგილას დატოვეთ (ან მამას ჩააბარეთ), სხვა ოთახში გადით და განწყობის დღიურში მთელი სტრესი ყოველგვარი ფილტრის გარეშე ჩაწერეთ.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'მუსიკალური გაღვიძება 🎶', 'მზე ჯერ ბოლომდე არც ამოსულა, ის კი საწოლზე ხტუნავს და რიტმულ ხმებს გამოსცემს. მსოფლიოში ყველაზე ხმაურიანი, თუმცა ყველაზე საყვარელი მაღვიძარა! დაიწყეთ დღე ღიმილით მის ამოუწურავ ენერგიაზე.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'ემოციების ჩაწერა 📝', 'როცა ბავშვი დაიძინებს, გახსენით განწყობის დღიური. მომავლისთვის ჩაიწერეთ დღევანდელი ყველაზე სასაცილო და აბსურდული მომენტი, რომელმაც ყველაზე მეტად გაგაცინათ. წლების შემდეგ წაკითხვისას თვალები ცრემლით აგევსებათ.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'სიმშვიდის საათის ექსპერიმენტი 🥱', 'შუადღისას დაძინება არ უნდა, მაგრამ თვალები ეძინება? 3 წლის ბავშვის წინააღმდეგობა კლასიკური ამბავია. ნუ დააძალებთ — ოთახში განათება შეამცირეთ, გამოაცხადეთ წიგნის ჩუმად ფურცვლის საათი და ახალი რუტინა შექმენით.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'მამის საიდუმლო იარაღი 🤡', 'როცა თქვენი ხერხები აღარ ჭრის, მამის უცნაური ხმები და სასაცილო სახეები სიტუაციას მყისიერად შველის. საღამოს ჭირვეულობისას ბურთი მაშინვე მას გადაუგდეთ, თავად კი გვერდიდან მშვიდად უყურეთ და დაისვენეთ.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'მოუსმინეთ საკუთარ სხეულს 🩸', 'უმიზეზოდ დაიღალეთ და ტირილი გინდათ? გახსენით მენსტრუაციის ტრეკერი. თქვენი სხეული სიგნალს გაძლევთ. გამოიჩინეთ საკუთარი თავის მიმართ მზრუნველობა და ჯანსაღი რეცეპტებიდან მაგნიუმით მდიდარი წასახემსებელი მოიმზადეთ.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'ჭირვეული მადა 🍝', 'მხოლოდ 2-3 საყვარელ კერძს ჭამს? ნუ ინერვიულებთ. კვების მონიტორინგის ხელსაწყოთი შეამოწმეთ კვირის კვებითი ბალანსი და სუფრასთან ჭამის დაძალებას მოერიდეთ.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'ზღაპრის დასასრულს თვითონ მოიფიქრებს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. გახსენით ჭკვიანი ზღაპრები და ამ საღამოს სიუჟეტის წარმართვა მას მიანდეთ. ჰკითხეთ: „ახლა ეს მანქანა სად წავიდეს?“ — და მიეცით საშუალება, თავისივე მოფიქრებული აბსურდული დასასრულით ჩაეძინოს.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'მითები იდეალური დედის შესახებ 🛑', 'სოციალურ ქსელებში ბავშვები უკვე ლექსებს ამბობენ, თქვენი ბავშვი კი ჯერ კიდევ სიტყვებს ურევს? დაუყოვნებლივ შეწყვიტეთ შედარება! ყველა ბავშვს განვითარების უნიკალური და განსხვავებული ტემპი აქვს. ის საკუთარი ტემპით იდეალურად ვითარდება.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'ფეხსაცმლის ჩაცმის ოლიმპიადა 👟', 'მარჯვენა ფეხსაცმელი მარცხენა ფეხზე ჩაიცვა და არაფრით უნდა გახდა? დატოვეთ, როგორც არის. თავისუფლების განცდა და სიამაყე — „მე თვითონ გავაკეთე!“ — უფრო მნიშვნელოვანია, ვიდრე ფეხსაცმლის სწორად ჩაცმა. ეს მომავალში პრობლემების დამოუკიდებლად გადაჭრის საფუძველიცაა.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'უხილავი ნაგვის ტრაგედია 🗑️', 'ეძებს და დასტირის იმ უსარგებლო ქაღალდის ნაგლეჯს, რომელიც თვითონ მოისროლა, თქვენ კი ნაგავში გადააგდეთ! 3 წლის ბავშვის ლოგიკა სწორედ ასეთია. რადგან მის დაბრუნებას ვეღარ შეძლებთ, დაუყოვნებლივ გადაატანინეთ ყურადღება რაიმე უფრო თვალშისაცემზე.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'დედის დამუხტვის დრო 🔋', 'ის თავისით აწყობს ფაზლს და უკვე 10 წუთია ჩუმადაა. თქვენ კი ამ დროის სახლის დალაგებისთვის გამოყენება გინდათ. არა! წამოწექით დივანზე. თქვენც უნდა დაიმუხტოთ, რომ საღამომდე ამ ტემპს გაუძლოთ.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'სიბნელესთან შეგუება 🌙', 'საძინებელში შუქის ჩაქრობისას ღელავს? ოთახის ერთ კუთხეში პატარა, თბილი ფერის (ყვითელი ან ნარინჯისფერი) ღამის სანათი დადგით. ოთახის დანარჩენი ნაწილი კი ღრმა ძილისთვის სრულიად ბნელი უნდა დარჩეს.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'დილის დიქტატორი საქმეს შეუდგა 👑', 'იქ თქვენ ნუ დაჯდებით, ჩემი დათუნია უნდა დაჯდეს! საუზმის დროს მთელ სუფრას ის განაგებს. მისი ნების მკვეთრად გატეხვის გარეშე შეინარჩუნეთ წონასწორობა და უთხარით: „კარგი, დათუნია იქ დაჯდეს, მე კი აქ დავჯდები“.'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'ბუნებაში გაქცევა ⛅', 'ოთხ კედელში ყოფნამ როგორც ბავშვი, ისე თქვენ გაგაღიზიანათ. შეამოწმეთ ამინდისა და ჩაცმულობის ხელსაწყო და მაშინვე პარკისკენ გაეშურეთ. სუფთა ჰაერზე სირბილი და თავისუფლება ყველაზე მწვავე ასაკობრივ ისტერიკასაც კი მყისიერად აცხრობს.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'ღამის სიმშვიდის წუთები 🛀', 'მთელმა დღემ „არ მინდას“ ძახილში ჩაიარა. თბილი აბაზანა მხოლოდ ჰიგიენისთვის არ არის — ის ბავშვის დაძაბული ნერვული სისტემის განტვირთვასაც ემსახურება. წყლის ხმა და სითბო მთელ სიჯიუტეს ჩამორეცხავს.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'დავიწყებული ნივთი მაღაზიაში 🛒', 'საკუთარ მეხსიერებას ენდეთ, მაღაზიაში წახვედით და ბავშვის საფენების გარეშე დაბრუნდით? ასეც ხდება. მიეჩვიეთ, რომ ყველაფერი, რაც გჭირდებათ, მაშინვე საყიდლების სიაში ჩაიწეროთ — დაე, აპი თქვენს ციფრულ მეხსიერებად იქცეს.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'დედა, შემომხედე! 👀', 'როცა ტელეფონს უყურებთ ან საქმით ხართ დაკავებული, ბავშვი მოდის, ხელზე გირტყამთ ან წინ გიდგებათ. ის სრულიად მართალია — თქვენი განუყოფელი ყურადღება სჭირდება. სულ რაღაც 5-წუთიანი თამაში უწყვეტი თვალით კონტაქტით მას დაამშვიდებს.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'სიჩუმის დასტური 🤫', 'ხმაურიანი დღის შემდეგ, როცა ბავშვს ჩაეძინება, ხმის საზომით ოთახში სიჩუმის დონე გაზომეთ. ნულთან მიახლოებული რიცხვების დანახვა და ეს ვიზუალური სიმშვიდე დედის ტვინზე საუკეთესო მასაჟივით მოქმედებს.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'რა სწრაფად გადის დრო!', 'ის უკვე დამოუკიდებელი ადამიანია, რომელსაც საკუთარი გადაწყვეტილებები აქვს. მისი ძლიერი ხასიათი მომავალში ძალიან გაგაამაყებთ. ეს დღეები აღარ განმეორდება — სიყვარულით ჩაიხუტეთ.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'ბოსტნეულის ქირურგი 🥦', 'წვნიანში ბოსტნეულს ისე არჩევს და გვერდზე აწყობს, თითქოს მიკროსკოპით ეძებდეს? ნუ შეებრძოლებით. აღმოაჩინეთ ჯანსაღ რეცეპტებში ბოსტნეულის პიურედ ქცევისა და სოუსებში დამალვის მრავალფეროვანი და გემრიელი გზები.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'მამის მასაჟის სეანსი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე და მის დევნაში წელი გტკივათ. როგორც კი ბავშვი დაიძინებს, პარტნიორს სთხოვეთ, მხრებზე 10-წუთიანი მასაჟი გაგიკეთოთ. თქვენ ოჯახის საყრდენი ხართ, საყრდენებს კი აუცილებლად სჭირდება აღდგენა.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'სიბნელის დრო 🌙', 'დაძინების დასაჩქარებლად ოთახში გამორთეთ ყველა დამატებითი განათება და პლანშეტის ეკრანი. მელატონინი ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში უფრო სწრაფად გამოიყოფა და დაძინებას აადვილებს.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'ფიქრები საბავშვო ბაღზე 🏫', 'გრძნობთ, რომ მას უკვე უფრო მეტად სჭირდება სოციალიზაცია? შესაფერისი დროა საბავშვო ბაღისთვის? შეუერთდით Anacan-ის საზოგადოებას, გაეცანით სხვა დედების ადაპტაციის რეალურ გამოცდილებას და გადაწყვეტილების მიღება გაიმარტივეთ.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'მოდი, დაგეხმარები! 🧽', 'როცა ჭურჭელს რეცხავთ, აუცილებლად გვერდით იდგამს სკამს და წყლით თამაში უნდა? სინამდვილეში მას დახმარება კი არა, პროცესის შუაგულში ყოფნა სურს. მიეცით პატარა პლასტმასის ჭურჭელი და მიეცით საშუალება, თავადაც გასაპნოს.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'ჩურჩულით მოყოლილი ზღაპრები 🪄', 'ოთახში სინათლე მთლიანად ჩააქრეთ. გვერდით მიუწექით და ჭკვიანი ზღაპრებიდან მოკლე ამბავი ძალიან ხმადაბლა, ყურში ჩასჩურჩულეთ. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი ყველაზე ბუნებრივი და დამამშვიდებელი მეთოდია.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'ცოცხალი დიქტოფონი 🎙️', 'გუშინ ტელეფონით მეგობარს რომ ემოციური ან უცნაური ფრაზა უთხარით, დღეს ბავშვი იმავეს თავის სათამაშოს ეუბნება! მისი ლექსიკური მარაგი საოცარი სისწრაფით იზრდება და ის თქვენს ქცევას იმეორებს. ახლა თქვენს სიტყვებს ორმაგი ყურადღება უნდა მიაქციოთ.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'დააფასეთ საკუთარი თავი 🥗', 'მის გამოსაკვებად კვერცხი 4 სხვადასხვა მეთოდით მოამზადეთ, მაგრამ თავად რა მიირთვით? ჯანსაღი რეცეპტებიდან შეარჩიეთ 5 წუთში მოსამზადებელი, რკინითა და კალციუმით მდიდარი კერძი და საკუთარი თავი დააჯილდოეთ.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'თეთრი ხმაურის დახმარება 🤫', 'ჩაძინებისას მგრძნობელობა იმატებს. ფანჯრიდან შემოსული ხმების გასანეიტრალებლად ოთახში ხმის საზომის ფონური ხმა ჩართეთ და მშვიდი გარემო შექმენით.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'ტანსაცმელი სულ დალაქავებულია 🎨', 'პიჟამა საკვებითაა დასვრილი, ტანსაცმელი კი საღებავით დალაქავებული? ბავშვები ზედმეტად სუფთად არ უნდა იზრდებოდნენ — გარემოს შეცნობისას ისინი აუცილებლად დასვრიან. გამოიყენეთ სილიკონის წინსაფრები, დანარჩენი კი სარეცხ მანქანას მიანდეთ.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'ავეჯზე აცოცება 🧗‍♂️', 'დივანს ან სავარძელს ეჭიდება და ზედ აცოცებას ცდილობს? მისი წონასწორობა და კუნთების ძალა უმჯობესდება. დაიცავით, თუმცა ნუ შეუშლით ხელს ამ პატარა ალპინისტის მცდელობებსა და ფიზიკის აღმოჩენაში.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'დედების გულახდილი საუბრები 💬', 'ფიქრი, რომ ეს ბავშვი არასდროს დამშვიდდება, გღლით? შეუერთდით Anacan-ის საზოგადოებას, ნახავთ, რომ 3 წლის ასაკამდე ყველა ბავშვი გადის ამ ქარიშხლიან კრიზისებს, და შვებით ამოისუნთქავთ.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'ერთი, ორი, სამი... ათი! 🔢', 'ცდილობს თითების ან სათამაშოების დათვლას? მათემატიკური აზროვნება იღვიძებს. არ გამოგრჩეთ ეს პატარა მცდელობები, რომლებიც საოცარი სისწრაფით ვითარდება.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით გაღვიძებასა და ბავშვის დაძინებას ყოველთვის მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს. ამაღამ ბავშვის დაძინება მთლიანად მას მიანდეთ.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'სიმშვიდის საათის გამოცდა 🥱', 'შუადღით დაძინება არ სურს და ტირის? ნუ აიძულებთ. ოთახში განათება შეამცირეთ, „წიგნის ჩუმად ფურცვლის საათი“ გამოაცხადეთ და შექმენით ახალი რუტინა, რომელიც ორივეს დაგამშვიდებთ.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'წარმოსახვები სიბნელეში 🌌', 'შუქის ჩაქრობისას ოთახში ნივთები ურჩხულებად ეჩვენება? თეთრი ხმებიდან ჩაურთეთ დედის საშვილოსნოში მოსმენილი ხმა და კვლავ აგრძნობინეთ ის ძველებური, სრულყოფილი უსაფრთხოება.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'ლოგიკის ძიებაში 🧩', 'მარტივი სათამაშოები უკვე აღარ იზიდავს და უფრო რთულ თამაშებს იგონებს. „რეკომენდებული პროდუქტების“ განყოფილებაში მოძებნეთ თამაშები, რომლებიც მის გონებას კიდევ უფრო დატვირთავს და ლოგიკურ აზროვნებას განუვითარებს.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'უხილავი მდევარი 👻', 'კედელზე საკუთარი ჩრდილის შეეშინდა და ტირილი დაიწყო? ჩრდილთან ბრძოლა 3 წლის ასაკის ერთ-ერთი ყველაზე სახალისო კლასიკაა. ჩააქრეთ შუქი, აანთეთ ფანარი და ჩრდილები ააცეკვეთ — ასე ეს შიში ძილის წინ სახალისო რიტუალად გადაიქცევა.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'თბილი წყლის ჯადოსნური ძალა 🛀', 'მთელმა დღემ „არ მინდას“ ძახილში ჩაიარა. თბილი აბაზანა მხოლოდ ჰიგიენისთვის არ არის — ის ბავშვის დაძაბულ ნერვულ სისტემას განტვირთვაში ეხმარება. წყლის ხმა და სითბო მთელ სიჯიუტეს თან გაატანს.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'ბუნების გამოცანა 🍁', 'სახლის მოსაწყენი გარემო ორივეს გაწუხებთ. წადით პარკში და ყველაზე უცნაური ფორმის ქვის საპოვნელად გაეშურეთ. ბუნება ბავშვისთვის უდიდესი ლაბორატორიაა და მთელ დაძაბულობას მოუხსნის.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'ცხოველების მიბაძვა 🐶', 'მხოლოდ ხმებს კი არ გამოსცემს, არამედ ძაღლივით დახოხავს და კატასავით კნავის? სხეულის ენა და წარმოსახვა საოცრად ერწყმის ერთმანეთს. შეუერთდით ბავშვს ხალიჩაზე ამ თამაშში და თქვენც მოიშორეთ სტრესი.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'ოფლაინ საათი დედისთვის ☕', 'როცა ბავშვი თავის სამყაროშია ჩაფლული და თამაშობს, მაშინვე ნუ დაიწყებთ სახლის დალაგებას. დაისხით ცხელი ჩაი, გადადეთ ტელეფონი და 15 წუთის განმავლობაში არაფერზე იფიქროთ — უბრალოდ იჯექით.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'შესვენება წყვილისთვის 🥂', 'ბავშვმა დაიძინა. ახლა სახლის საქმეები გვერდზე გადადეთ. თქვენს პარტნიორს მინიმუმ 20 წუთის განმავლობაში ესაუბრეთ ნებისმიერ თემაზე, ბავშვისა და ხარჯების გარდა. თქვენ ამავდროულად წყვილიც ხართ!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', '„ეს რა არის?“ მანქანა ☝️', 'ყველაფერზე თითით მიგანიშნებთ და სახელს გეკითხებათ? ბავშვს სურს, რომ მისთვის სამყარო დაასახელოთ. ეს კომუნიკაციაში დიდი ნახტომია! დაღლის მიუხედავად, მოთმინებით განაგრძეთ საგნების სახელების გამეორება.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'კარავი ტანსაცმლის გორიდან ⛺', 'ახლახან დაკეცილი სუფთა ტანსაცმლის გროვა აურ-დაურია და თავისთვის კარავი ააშენა? სანამ გაბრაზდებით, იმ კარავში შეიხედეთ. იქ შექმნილი წარმოსახვითი სამყარო და ბავშვის სიხარული თქვენს დასაკეცად გაწეულ შრომაზე უფრო ძვირფასია.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'იარლიყის კრიზისი 🏷️', 'კისერს მიქავებს! მაისურის უკანა მხარეს მიკერებული პატარა იარლიყი ამ დილის ყველაზე დიდი მტერია. 3 წლის ასაკში სენსორული მგრძნობელობა პიკს აღწევს. ნუ შეეკამათებით, უბრალოდ მოაჭერით იარლიყი და მიეცით დღეს მშვიდად დაწყების შანსი.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'პულტი მაცივარში 📺', 'ტელევიზორის პულტს ვერ პოულობთ? მაცივარში ან ფეხსაცმლის კარადაში მოძებნეთ. ბავშვი სამყაროს იმით შეიცნობს, რომ ნივთებს მისივე გამოგონილი ლოგიკით ალაგებს. გაბრაზების ნაცვლად, ამ აბსურდულ დეტექტიურ თამაშს სიცილით მიუდექით.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'წარმოსახვითი ჭრილობის ძიება 🩹', 'გაღვიძებისთანავე სხეულზე უხილავ ჭრილობას პოულობს და შეშფოთებული მოითხოვს, რომ პლასტირი დააკრათ. ეს ფიზიკური ტკივილი კი არა, უბრალოდ ყურადღებისა და სითბოს საჭიროებაა. ნუ შეეკამათებით — დააკარით პატარა პლასტირი, აკოცეთ და დღე მშვიდად ჩაივლის.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'უეცარი შიმშილის სინდრომი 🥱', 'როგორც კი საწოლში დაწვებით, ამბობს: „დედა, მშია“ და სამზარეულოში გაქცევა უნდა. ძილის გადასავადებლად ეს ნამდვილი შედევრია! კვების გეგმაში საღამოსთვის შეიტანეთ პატარა, ძილის მომგვრელი წასახემსებელი (მაგალითად, ბანანი) და ეს საბაბი წინასწარ გააქარწყლეთ.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'სიჩუმით გამოწვეული შფოთვა 🤫', 'ბავშვი ოთახში მარტო ათვალიერებს სურათებს, სახლში კი სრული სიჩუმეა. თქვენ ამ სიჩუმეს ეჭვის თვალით უყურებთ და ყოველ წამს რაღაც უბედურებას ელით. დამშვიდდით. ზოგჯერ მათაც სურთ მარტო ყოფნა. გადაწექით და დატკბით ამ იშვიათი offline მომენტით.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'ხმამაღალი ფიქრები 💭', 'საწოლში წევს და დღის განმავლობაში მომხდარ ამბებს თავისთვის, თუმცა ხმამაღლა ჰყვება. ასე ამუშავებს ინფორმაციასა და მოგონებებს. გახსენით განვითარების ტრეკერი და სიამაყით აღნიშნეთ, რამდენად სწრაფად ვითარდება მისი დამოუკიდებლად ამბების მოყოლის უნარი.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'ხალიჩის ხაზები 📏', 'ცდილობს, ხალიჩის ხაზებს არ დააბიჯოს და თქვენგანაც იმავეს მოითხოვს. მსხვილი მოტორიკა და ყურადღების კოორდინაცია აქ შესანიშნავად ერწყმის ერთმანეთს. ნუ ჩაშლით თამაშს — რამდენიმე ნაბიჯი თქვენც მასთან ერთად გადადგით და იმავე ხაზებს გადაახტით.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'აბაზანაში ჩაძირული გემები 🛀', 'სააბაზანოში წყლით სათამაშოდ შეხვედით, ბავშვი კი ცდილობს ჩაძიროს სათამაშოები, რომლებიც წყალში არ იძირება. ის ფიზიკის კანონებს აღმოაჩენს! აცადეთ, წყალი ირგვლივ აშხეფოს — წყლის ენერგია დღის განმავლობაში დაგროვილ დაძაბულობასაც თან წაიღებს.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'წარმოსახვითი შინაური ცხოველი 🐕', 'ბავშვი ოთახში არარსებულ ძაღლს ან კატას ეფერება და სახელს არქმევს? მისი წარმოსახვა უკვე ფიზიკურ საზღვრებს გასცდა. ოთახის ერთ კუთხეში უხილავი წყლის ჯამი დადგით და თქვენც შეუერთდით ამ საყვარელ ილუზიას.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'ნადიმი ყინულის ფორმაში 🧊', 'რაც არ უნდა სცადოთ, იმ ბოსტნეულს მაინც არ ჭამს? რადიკალურად შეცვალეთ მირთმევის ფორმა. სასარგებლო წასახემსებლები ყინულის ფორმის (ice cube tray) პატარა უჯრებში გადაანაწილეთ. უჩვეულო მირთმევა ყოველთვის აღვიძებს მადას.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'სუნთქვა დედისთვის 🌬️', 'სახლში გამეფებული ქაოსი ყურებში გიზუზუნებთ. შეამოწმეთ ამინდი, ჩაიცვით შესაბამისად — თუნდაც თბილად ჩაცმა დაგჭირდეთ — და სულ რაღაც 15 წუთით გარეთ გადით. ბავშვს ქვების შეგროვების საშუალება მიეცით, თავად კი ღრმად ჩაისუნთქეთ სახეზე მონაბერი ცივი და სუფთა ჰაერი.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'დინოზავრების ენა 🦖', 'დღეს დილით ის ადამიანი კი არა, დინოზავრია და თქვენს ყველა კითხვას მხოლოდ ღრიალით პასუხობს. როლური თამაშები პიროვნული განვითარებისთვის შესანიშნავი საშუალებაა. თქვენც ერთი წუთით დედა კი არა, სხვა დინოზავრი გახდით და მისივე ენით უპასუხეთ.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'დაღლილობის აღიარება 📝', 'ფიქრობთ, რომ თქვენი არავის ესმის და თქვენს შრომას ვერავინ ამჩნევს? ხელოვნური ღიმილი გვერდზე გადადეთ. განწყობის დღიურში დაწერეთ, სინამდვილეში რამდენად გამოფიტული ხართ დღეს. ეკრანზე გადატანილი ყოველი სიტყვა მხრებიდან მძიმე ტვირთს მოგხსნით.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'ხელოვნური ინტელექტი და შფოთვა 🤖', 'ბავშვი ზოგიერთ ბგერას ვერ წარმოთქვამს და ამან მოულოდნელად შეგაშფოთათ? დახურეთ ინტერნეტში ნაპოვნი არაპროფესიონალური და დამაშინებელი ფორუმები. Anacan AI-ს ჰკითხეთ, როგორია მეტყველების განვითარების ნორმები 3 წლის ასაკში და მიიღეთ მეცნიერულად დასაბუთებული, დამამშვიდებელი პასუხი.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'ცირკი საწოლში 🎪', 'ძილის დრო რომ დგება, საწოლი მყისვე ცირკის არენად იქცევა. ბავშვი ხტუნავს, დახოხავს და ყვირის. ხმის აუწევლად ჩააქრეთ მკვეთრი განათება. ის ენერგიის უკანასკნელ მარაგს ხარჯავს. ჭკვიან ზღაპრებში ძალიან ნელი რიტმის ამბავი შეარჩიეთ და ეს ქარიშხალი თანდათან ჩააცხრეთ.'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'კარის გაუყოფელი სახელური 🚪', '„კარს მე გავაღებ!“ — ამბობს და თქვენზე ადრე გარბის. თუ კარი თქვენ გააღეთ, ტირილით ისევ დაგაკეტინებთ და შემდეგ თავად გააღებს. ამ ასაკში კონტროლის განცდა მისთვის ყველაფერია. მიეცით საშუალება, კარი თავად გააღოს — ასეთი პატარა გამარჯვებები მის ჯერ კიდევ მყიფე თავდაჯერებას აძლიერებს.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'სოლიდარობის საზოგადოება 💬', 'დღეს ბავშვი იმდენად გეწინააღმდეგებოდათ, რომ თავს ცუდ დედად გრძნობთ. დაუყოვნებლივ შედით Anacan-ის საზოგადოებაში. როდესაც სხვა დედების შვილების დღევანდელი ამბოხების შესახებ წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ და სინამდვილეში შესანიშნავად ართმევთ თავს.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'ფარული მერყეობა 🤔', 'მოდის თქვენთან და სრულიად პარადოქსულ წინადადებებს გეუბნებათ, მაგალითად: „წყალი მომეცი, მაგრამ არ მომცე“. მის გონებაში ერთდროულად ორი ურთიერთსაწინააღმდეგო სურვილი არსებობს. ზედმეტ ლოგიკას ნუ ეძებთ — უბრალოდ წყალი მაგიდაზე დადგით და გადაწყვეტილება მის შინაგან ბრძოლას მიანდეთ.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'ჩაქუჩისა და ხრახნის ცდები 🛠️', 'ნებისმიერ მყარ სათამაშოს, რომელიც ხელში მოხვდება, ავეჯს ურტყამს და „არემონტებს“. მიუხედავად იმისა, რომ ხმაური ტვინს გიბურღავთ, ეს მისთვის აღმოჩენაა, რომლის მეშვეობითაც მიზეზშედეგობრივ კავშირს სწავლობს. მიეცით ცარიელი მუყაოს ყუთი და ხის კოვზი, რათა ხმაურიანი „რემონტი“ იქ განაგრძოს.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'ნაგავი კი არა, ხელოვნებაა 🎨', 'ოთახის შუაგულში ქაღალდის პატარა ნაგლეჯებისა და დაჭრილი ძაფებისგან დიდი ხელოვნების ნიმუში შექმნა და მისი გადაგდების უფლებას არ გაძლევთ. სისუფთავისადმი გადაჭარბებული სიყვარული ცოტა ხნით გვერდზე გადადეთ. პატივი ეცით მის მიერ შექმნილ ქაოსს — დალაგება ხვალაც მოიცდის.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'ხმაურის საზომით თერაპია 🤫', 'სახლში დაუსრულებელი ხმაური როგორც იქნა შეწყდა. ბავშვს სძინავს. ჩართეთ ხმაურის საზომი და უყურეთ, როგორ ეცემა ეკრანზე მაჩვენებელი 0 დეციბელამდე. იგრძენით, როგორ უკეთებს ოთახში გამეფებული სრული სიჩუმე თქვენს ტვინს ვიზუალურ მასაჟს.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'თეატრი სარკის წინ 🎭', 'დილიდანვე სარკის წინ დგება და ტირილის, სიცილისა და გაოცების სხვადასხვა გამომეტყველებას ავარჯიშებს. ის სწავლობს, როგორ გამოხატოს ემოციები და როგორ იცვლება ამ დროს მისი სახე! ამ გენიალურ სამსახიობო წარმოდგენას შორიდან სიამაყით უყურეთ.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'მამის ჯადოსნური მკლავები 🫂', 'მთელი დღე ტარებისგან ხელები გწყდებათ, მას კი ისევ ჩახუტება უნდა. მამას დაუძახეთ. მამის მკლავებში „ფრენა“ ბავშვის ყურადღების მოთხოვნილებასაც დააკმაყოფილებს და თქვენს ხელებსა და ზურგსაც ნანატრ დასვენებას მისცემს.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'კითხვების მიღმა არსებული ლოგიკა 🧐', 'თევზები რატომ არ დადიან? დილაუთენია მისი გონება ფილოსოფიური კითხვებით იღვიძებს. მიუხედავად იმისა, რომ მისმა კითხვებმა შეიძლება ჩიხში მოგაქციოთ, ეცადეთ, დაუღალავად აუხსნათ. თქვენი ხმა მისთვის სამყაროს შეცნობის ყველაზე უსაფრთხო და მშვენიერი გზაა.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'საყიდლების სიის ქაოსი 🛒', 'მაღაზიაში სალაროსთან დგახართ და ხვდებით, რომ ყველაზე მნიშვნელოვანი ნივთი ისევ დაგავიწყდათ. თქვენი გონება ისედაც ათას რამეზეა გადართული. ამიერიდან ჩვევად აქციეთ, საჭიროების გაჩენისთანავე ჩაიწეროთ ის აპლიკაციის საყიდლების სიაში — ასე საკუთარ თავს დაეხმარებით.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'უკუღმა ჩაცმის სიამაყე 🧦', 'წინდას ქუსლი ტერფის ზემოდან აქვს მოქცეული, მაგრამ ამაყად დადის, რადგან თავად ჩაიცვა. საერთოდ ნუ ჩაერევით. მისი ეს განცდა — „მე შევძელი“ — ფსიქოლოგიური განვითარების ბევრად უფრო ღირებული საფუძველია, ვიდრე ესთეტიკურობა ან სწორად ჩაცმა.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'ჩურჩულით მოყოლილი ამბები 🌙', 'დღეს იმდენი ილაპარაკეთ, რომ ხმა და ფილტვები დაგეღალათ. ჩააქრეთ შუქი, მის გვერდით დაწექით და დღის განმავლობაში მომხდარი ამბები ყურში უბრალოდ ჩურჩულით მოუყევით. ჩურჩული მის ყურადღებას იპყრობს და ტვინს ჰიპნოზურად ამზადებს ღრმა ძილისთვის.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'კონცერტი სამზარეულოში 🥄', 'ქვაბები და ხის კოვზები გამოუტანია და სამზარეულოს შუაგულში ხმაურიან კონცერტს მართავს. შეიძლება თავი აგტკივდეთ, მაგრამ ამ დროს მისი რიტმის შეგრძნება და მოტორული უნარები ვითარდება. უთხარით „ბრავო“ და იმედი იქონიეთ, რომ კონცერტი მალე დასრულდება.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'ოქროს დუმილის საზომი 🤫', 'სახლში ქაოსი როგორც იქნა დასრულდა და ბავშვს ჩაეძინა. ჭურჭლის გასარეცხად ნუ გაიქცევით! ჩართეთ ხმის საზომი, დააკვირდით ოთახში გამეფებულ აბსოლუტურ სიჩუმეს (0-10 დეციბელი) და 15 წუთის განმავლობაში თვალნათლივ შეიგრძენით, როგორ ისვენებს თქვენი გონება.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'ბანანის გაფცქვნის ტრაგედია 🍌', 'დილის 8 საათზე ოთახში რევოლუცია დაიწყო, რადგან ბანანი მის ნაცვლად თქვენ გაფცქვენით? ამ ასაკის ოქროს წესია: ყველაფერი თავად უნდა გადაწყვიტოს. ბანანს ქერქს უკან ვეღარ მიაკრავთ, ამიტომ ყურადღება დაუყოვნებლივ სხვა რამეზე გადაატანინეთ და კრიზისი განმუხტეთ.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'შერჩევითი სმენის სინდრომი 🙉', 'როცა სათამაშოების ალაგებას სთხოვთ, არ ესმის, მაგრამ მეზობელი ოთახიდან შოკოლადის შეფუთვის შრიალს მაშინვე ამჩნევს? სმენის პრობლემა არ აქვს — უბრალოდ იმას ისმენს, რაც აწყობს. სცადეთ, წესები ჩურჩულით უთხრათ — ეს მის ინტერესს გააღვიძებს.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'ჯიბიდან ამოღებული საგანძური 🪨', 'შარვლის რეცხვისას ჯიბეში 2 ქვა, ერთი გამხმარი ფოთოლი და ნახევარი ჯოხი იპოვეთ? ეს ნივთები, რომლებიც თქვენთვის ნაგავია, მისი ძვირფასი კოლექციაა, რომლითაც სამყაროს იკვლევს. გადაყრის ნაცვლად, პატარა საგანძურის ყუთში შეაგროვეთ.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'ბროკოლის კამუფლაჟი 🥦', 'წვნიანში მწვანე ბოსტნეულს ქირურგიული სიზუსტით აცალკევებს? საკვებისადმი პრეტენზიულობამ პიკს მიაღწია. დროა, კვების გეგმაში აღმოაჩინოთ განსაკუთრებული და ეშმაკური რეცეპტები, რომლებიც ბოსტნეულს შეუმჩნეველს გახდის და ფერად კატლეტებად გადააქცევს.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'ზღაპრის რეჟისორი თავადაა 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. ჩართეთ ჭკვიანი ზღაპრები და ამ საღამოს სიუჟეტის მართვა მას მიანდეთ. ჰკითხეთ: „ახლა ეს მფრინავი მანქანა სად წავიდეს?“ — და დაე, თავისივე მოფიქრებული აბსურდული დასასრულით ჩაეძინოს.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'მამის ფრენის რეჟიმი ✈️', 'ბავშვმა სახლში ენერგია ვერ დახარჯა და დაძინებას ეწინააღმდეგება. დასახმარებლად მამას უხმეთ. როცა ის ბავშვს ჰაერში აიყვანს და თვითმფრინავივით „გააფრენს“, ოთახი სიცილით ივსება და დაგროვილი ფიზიკური დაძაბულობა წამებში ქრება.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'საზოგადოებაში ამოსუნთქვა 💬', 'ძალიან დაიღალეთ და თავი მსოფლიოში ყველაზე მოუთმენელ დედად გეჩვენებათ? დაუყოვნებლივ გახსენით Anacan-ის საზოგადოება. იმის წაკითხვა, რომ სხვა დედებიც ზუსტად ასეთივე აბსურდულ კრიზისებს აწყდებიან, უდიდესი ფსიქოლოგიური მხარდაჭერაა.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'დაუსრულებელი „რატომ?“ 🌪️', 'რატომ დაფრინავენ ჩიტები?, რატომ ასველებს წყალი?, რატომ არის რატომ?... კითხვების მატარებელი მთელი სისწრაფით თქვენკენ მოემართება. დაღლილობის მიუხედავად, გაეცით ლოგიკური და მოკლე პასუხები. ბავშვი სამყაროს საიდუმლოებებს თქვენი ხმის ტონიდან სწავლობს.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'ბუნებაში გაქცევა ⛅', 'ოთხ კედელში ყოფნამ ბავშვიც გააღიზიანა და თქვენც. სახლში ქაოსით დაიღალეთ. შეამოწმეთ ამინდისა და ჩაცმულობის ინსტრუმენტი და დაუყოვნებლივ გაეშურეთ პარკისკენ. სუფთა ჰაერზე თავისუფლად სირბილი პატარა ბავშვის ყველაზე მწვავე კრიზისებსაც კი მყისიერად აჩერებს.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'არასწორი ფერის კატასტროფა 🔴', 'იმიტომ ატყდა ერთი ამბავი, რომ წყალი ლურჯის ნაცვლად წითელ ჭიქაში მიეცით? ეს ჭირვეულობა არ არის — ბავშვი უბრალოდ ამოწმებს თქვენს საზღვრებს და იმას, შეუძლია თუ არა სამყაროს მართვა. გაჯიუტების გარეშე შეუცვალეთ ჭიქა და ენერგია დაზოგეთ.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'მიეცით ემოციებს გასაქანი 📝', 'ვერავინ ამჩნევს, რამდენად იღლებით სახლში? განწყობის დღიური თქვენი ყველაზე ჩუმი მესაიდუმლეა. ჩაწერეთ იქ ყველა დეტალი, რომელმაც დღეს ჭკუიდან გადაგიყვანათ, და იგრძნობთ, როგორ შეგიმსუბუქდებათ გონება.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'ხელოვნური ინტელექტი, რეალური გამოსავალი 🤖', 'თქვენს ბავშვს უცნაური ჩვევა გაუჩნდა (მაგალითად, თმას თითზე იხვევს) და ინტერნეტში წაკითხულმა სტატიებმა შეგაშინათ? შეჩერდით. ჰკითხეთ Anacan AI-ს ამის პედიატრების მიერ დადასტურებული რეალური მიზეზი და თავიდან აიცილეთ ზედმეტი პანიკა.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'დამალობანას ლოგიკა 🙈', 'ოთახის შუაგულში ხელებით თვალებს იფარავს და ელოდება, როდის იპოვით! 3 წლის ბავშვის ლოგიკა: თუ მე ვერ გხედავ, ვერც შენ მხედავ. თავი მოაჩვენეთ, თითქოს მისმა ამ გულუბრყვილო ილუზიამ დაგაჯერათ, და ოთახში ხმაურით დაუწყეთ ძებნა.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'ჩააქრეთ შუქი და მოიხმეთ ძილი 🌙', 'იმისთვის, რომ ბავშვმა უფრო სწრაფად დაიძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი (ძილის ჰორმონი) სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამომუშავდება.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'ციფრული მეხსიერება 🛒', 'მაღაზიაში წასვლისას ყოველთვის რაღაც გავიწყდებათ? საყიდლების სია აპში გელოდებათ. საჭირო ნივთები მაშინვე იქ ჩაინიშნეთ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ყველაფერი ზუსტად მოიტანოს — ნუ გადატვირთავთ გონებას.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', '„მე თვითონ!“ — კანონი 👟', 'ფეხსაცმლის თასმის შეკვრა თავად სურს, თქვენ კი სახლიდან გასვლა უკვე 10 წუთით დაგიგვიანდათ. ნუ აჩქარდებით. მისი განვითარებისთვის დაუზიანებელი თვითშეფასება უფრო მნიშვნელოვანია, ვიდრე დარღვეული განრიგი.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'ჩურჩულის მისტიკური ძალა 🤫', 'საწოლში იმდენად აქტიურია, რომ ვერ იძინებს. ხმის აწევის ნაცვლად, მოულოდნელად დაუწიეთ ხმას და ჩურჩულით ესაუბრეთ. როცა ბავშვი თქვენს გასაგონად ყურადღებას მოიკრებს, მისი ტვინი ავტომატურად ძილის რეჟიმზე გადაერთვება.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'ღამის სიმშვიდე 🛁', 'მთელი დღის სირბილმა თქვენც და ბავშვიც დაგღალათ. თბილი აბაზანის მიღებისას ფონად ბუნების დამამშვიდებელი ხმები ჩართეთ. წყლის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ღრმა ძილისთვის მოამზადებს.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'შეხებით გადაღლა 🔋', 'მთელი დღე თქვენზე დაცოცავს, ჩახუტებას ითხოვს და თქვენი თმით თამაშობს. თქვენ კი უბრალოდ პირადი ფიზიკური სივრცე გჭირდებათ. შეხებით გადაღლა (touched out) რეალური მდგომარეობაა. თქვენ გაქვთ უფლება, სულ მცირე 15 წუთით განმარტოვდეთ ოთახში.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'აბაზანის სადრენაჟო ხვრელის შიში 🛀', 'ბავშვს, რომელსაც ადრე წყლიდან ამოსვლა არ სურდა, მოულოდნელად აბაზანის სადრენაჟო ხვრელის შეეშინდა და ტირილი დაიწყო? წარმოსახვის განვითარებასთან ერთად უსაფუძვლო შიშებიც ჩნდება. ხვრელს პლასტმასის სათამაშო გადააფარეთ და ბავშვი დაამშვიდეთ.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'დრო წყვილისთვის 🥂', 'ბავშვს ჩაეძინა. ახლა საოჯახო საქმეები გვერდზე გადადეთ. სულ მცირე 20 წუთის განმავლობაში პარტნიორს ესაუბრეთ ნებისმიერ თემაზე, გარდა ბავშვის, პრობლემებისა და ხარჯებისა. სანამ მშობლები გახდებოდით, თქვენ წყვილი იყავით!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'უსულო საგნებთან საუბარი 🗣️', 'პარკში ქვას ან სახლში სკამს სრული სერიოზულობით ელაპარაკება და საყვედურობს. სიმბოლური თამაშების საშუალებით ბავშვი სამყაროს აღიქვამს და აანალიზებს. განვითარების ტრეკერში აუცილებლად მონიშნეთ მისი ეს განსაკუთრებული სცენარები.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'მამის მასაჟის სეანსი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე და ბავშვის დევნაში წელი გტკივათ. როგორც კი ბავშვს ჩაეძინება, პარტნიორს სთხოვეთ, 10 წუთის განმავლობაში მხრების მასაჟი გაგიკეთოთ. თქვენ ოჯახის საყრდენი ხართ, საყრდენებს კი აუცილებლად სჭირდება აღდგენა.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'დაძინების გადადების ტაქტიკა ⏱️', 'როგორც კი დაძინების დრო მოდის, უცებ სწყურდება, ტუალეტში უნდება ან კედელს ემშვიდობება? დააყენეთ ტაიმერი. შემოიღეთ წესი — ზარის დარეკვისთანავე ყველა იძინებს — და ამ უსასრულო გამომშვიდობებას მოთმინებით დააღწიეთ თავი.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'დედის საკვები მარაგი 🥗', 'მის დასანაყრებლად უამრავი განსხვავებული მენიუ მოიფიქრეთ, თავად კი ისევ მშიერი დარჩით? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინითა და კალციუმით მდიდარი სადილი, რომელიც 10 წუთში მზადდება, და საკუთარ თავზეც იზრუნეთ.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'პატარა დამხმარე სარეცხთან 🧺', 'თქვენ დიდი მონდომებით კეცავთ ტანსაცმელს, ის კი ამბობს, რომ გეხმარებათ, და ყველაფერს ისევ ოთახში ფანტავს. გაბრაზების ნაცვლად საქმე თამაშად აქციეთ: ვნახოთ, ვინ უფრო სწრაფად ჩაყრის ამ წინდებს კალათაში?'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'ავანგარდული მოდის ხედვა 👗', 'ზამთრის სვიტერზე საზაფხულო შორტი ჩაიცვა და გახდა არ სურს? ამაში ცუდი არაფერია. ბავშვი, რომელიც საზოგადოებაში შეუფერებელი ჩაცმულობით გამოდის, სინამდვილეში საკუთარ გადაწყვეტილებას გაბედულად იცავს. ნუ გაუტეხთ ნებას.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'ღამის შიშის ამოცნობა 😭', 'შუაღამისას დახუჭული თვალებით ტირილით იღვიძებს და ვერავის ამჩნევს? გადაამოწმეთ ტირილის ანალიზით; თუ ეს ღამის შიშია, ნუ ეცდებით მის გაღვიძებას. უბრალოდ მის გვერდით იყავით და ჩუმად აგრძნობინეთ, რომ უსაფრთხოდაა.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'ამინდის გაფრთხილება ⛅', 'სასეირნოდ გასვლისას მხოლოდ ფანჯრიდან დანახულ ამინდს ნუ ენდობით. ამინდისა და ჩაცმის დამხმარის მეშვეობით გარეთ არსებულ ქარსა და ტემპერატურას ყველაზე შესაფერისი სამოსი შეუხამეთ და სახლიდან მშვიდად და მომზადებული გადით.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'საზოგადოება — თქვენი მესაიდუმლე 💬', 'ძალიან დაიღალეთ და არავისთვის არაფრის ახსნა არ გსურთ. შეუერთდით Anacan-ის საზოგადოებას და უბრალოდ მკითხველად დარჩით. სხვა დედების მსგავსი დაღლილობის დანახვა გაგიჩენთ განცდას, რომ მარტო არ ხართ — ზოგჯერ ეს საუკეთესო თერაპიაა.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'ცოცხალი კონცერტი და მეზობლები 🎤', 'კოვზს იღებს, ოთახის შუაგულში დგება და მთელი ხმით ყვირილით მღერის. ნუ იდარდებთ, რას იფიქრებენ მეზობლები. თქვენს სახლში ვარსკვლავი იზრდება — თქვენ კი უბრალოდ ტაში დაუკარით.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'მუსიკით დაძინება 🎶', 'სცადეთ, საღამოობით უმიზეზოდ ატეხილი ქარიშხალი მშვიდი კლასიკური მუსიკით დააცხროთ. ხშირად ეს მარტივი, მაგრამ ეფექტური ხერხი სახლში სასწაულს ახდენს და ოთახში სიმშვიდე შემოაქვს.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'ეკრანთან გატარებული დროის გამო დანაშაულის განცდა 📺', 'დღეს საქმეების გამო ბავშვს უფრო დიდხანს აყურებინეთ მულტფილმები და ახლა სინდისი გაწუხებთ? თავს ნუ დაიდანაშაულებთ. ზოგჯერ „ციფრული ძიძა“ ერთადერთი საშუალებაა, რომელიც ემოციური გამოფიტვისგან გიხსნით.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'ტელეფონის დამალვის ოპერაცია 📱', 'ვერ პოულობთ, სად დადეთ ტელეფონი, ცოტა ხნის შემდეგ კი ის სათამაშოების ყუთში აღმოჩნდება. ბავშვს არ სურს, თქვენი ყურადღება ტელეფონს გაუზიაროს. გადადეთ მოწყობილობა გვერდზე და 15 წუთის განმავლობაში მთელი ყურადღება მხოლოდ მას დაუთმეთ.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'სიჩუმის ციფრული საზომი 🤫', 'როგორც იქნა, დაიძინა! სახლში ჩამოწოლილი სიჩუმე დაუჯერებელია. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს შეხედეთ — ასე თვალნათლივ იგრძნობთ, როგორ ისვენებს თანდათან თქვენი გონება.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'ჩემს სათამაშოს არ მოგცემ! 🧸', 'პარკში სასრიალოზე ან ქვიშაში თამაშისას არავის უთმობს ადგილს და სათამაშოებს მაგრად ეჭიდება. ეს ეგოიზმი კი არა, საკუთარი საზღვრების დაცვაა. გაზიარებას ნუ აიძულებთ — თამაშის ფორმით ასწავლეთ მორიგეობით თამაში.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'მოწვევა სიბნელეში 🌙', 'საძინებელში შუქის ჩაქრობისას ღელავს? ოთახის ერთ კუთხეში პატარა, თბილი ფერის ღამის სანათი დადგით. ოთახის დანარჩენი ნაწილი კი ღრმა ძილისთვის სრულად ჩაბნელებული უნდა იყოს.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'როცა დედა იღლება 🛑', 'თქვენ რობოტი არ ხართ. თუ დღეს საჭმლის მოსამზადებლად ძალა არ გაქვთ, შეუკვეთეთ ან უბრალოდ მაკარონი მოხარშეთ. იდეალური დედობა ყველაფრის მარტო კეთებას არ ნიშნავს. მიეცით საკუთარ თავს ამის უფლება.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'სიურპრიზი სიაში 🛒', 'მაღაზიაში წასვლამდე საყიდლების სია გახსენით და დაინახეთ, როგორ მოგიახლოვდათ ბავშვი, ტელეფონის ეკრანს დააჭირა და სიაში რაღაცები ჩაწერა. დიახ, ის თქვენს ციფრულ ცხოვრებასაც ბაძავს!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'აღიარება განწყობის დღიურში 📝', 'აიღეთ ტელეფონი. სოციალურ ქსელში სხვების ცხოვრების თვალიერების ნაცვლად, გახსენით განწყობის დღიური და სამახსოვროდ ჩაიწერეთ დღევანდელი ყველაზე სასაცილო მომენტი. ციფრული თერაპია ნამდვილად მუშაობს.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'ადვოკატური მოლაპარაკება 🗣️', 'გეუბნებათ: „კიდევ სულ 5 წუთი ვითამაშებ და მერე ჩავიცვამ“? ის უკვე პროფესიონალურ მოლაპარაკებას გიმართავთ. მეტყველების განვითარება შესანიშნავია, მაგრამ არ დაგავიწყდეთ, სიყვარულით დაიცვათ თქვენი საზღვრები და წესები.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'სიმშვიდის საათი 🥱', 'არ სურს შუადღის ძილი და ტირის? ნუ დააძალებთ. ოთახში განათება შეამცირეთ, გამოაცხადეთ წიგნების ჩუმად თვალიერების საათი და შექმენით ახალი რუტინა, რომელიც ორივეს დაგასვენებთ.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'დღეს ამას არ ვჭამ 🥣', 'გუშინ სიამოვნებით მიირთმევდა წვნიანს, დღეს კი პირსაც არ აკარებს. თუ კბილებთან დაკავშირებული პრობლემა არ აქვს, ეს უბრალოდ ნებისყოფის გამოცდაა. კვების გეგმაში გაეცანით განსხვავებულ ალტერნატიულ რეცეპტებს, რომლებიც იმავე ვიტამინებით უზრუნველყოფს.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'მამის უცნაური ხმები 🤡', 'როდესაც თქვენი ხერხები აღარ ჭრის, მამის უცნაური ხმები და სასაცილო სახეები სიტუაციას მყისიერად შველის. საღამოს ჭირვეულობის დროს საქმე მაშინვე მას გადააბარეთ, თავად კი გვერდიდან მშვიდად უყურეთ და დაისვენეთ.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'ბუნების გამოცანა 🍁', 'სახლის მოსაწყენი გარემო ორივეს გღლით. წადით პარკში და ყველაზე უცნაური ფორმის ქვის მოსაძებნად გაემართეთ. ბუნება მისთვის უდიდესი ლაბორატორიაა და მთელ სტრესს მოუხსნის.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'წარმოსახვითი სტუმრები სუფრასთან ☕', 'ცარიელ ფინჯანს გაწვდით, გეუბნებათ, ჩაი დალიეთო, და ოთახში არარსებულ მეგობარს ესაუბრება? ეს წარმოსახვის განვითარების ნამდვილი შედევრია. ნუ შეწყვეტთ ოთახის კუთხეში მიმდინარე ამ წარმოდგენას — თქვენც დალიეთ ის ჩაი.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'მე ჭკვიან ზღაპარში 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით. გახსენით ჭკვიანი ზღაპრები, მთავარ გმირად თქვენი ბავშვი აქციეთ, დასაპყრობ ადგილად კი მისი ოთახი შეარჩიეთ და ძილის წინ უჩვეულო ზღაპრული თავგადასავალი შექმენით.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'სიმშვიდე აბაზანაში 🛀', 'წყლით თამაში იმდენად სასიამოვნოა, რომ თითების დანაოჭების მიუხედავად, აბაზანიდან ამოსვლა არ სურს. 5 წუთით ადრე გააფრთხილეთ და ტაიმერი დააყენეთ. წესი — „ზარი რომ დარეკავს, აბაზანიდან ამოვდივართ“ — ხშირად ამართლებს.'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', '„ხელი არ მომკიდო!“ — თავისუფლება 🚶‍♂️', 'ქუჩაში ხელის მოკიდებაზე კატეგორიულ უარს ამბობს და თავისუფლად სირბილი სურს. უსაფრთხო ადგილებში მიეცით ეს თავისუფლება. თვალი ადევნეთ და მიეცით საშუალება, საკუთარი ნაბიჯებით დაიპყროს სამყარო.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'განვითარების კვალი 📈', '3 წლის ასაკში ბავშვის მოტორული უნარები, ლექსიკური მარაგი და ემოციური ინტელექტი სწრაფად იცვლება. მისი პატარა აღმოჩენები რომ არ დაგავიწყდეთ, რეგულარულად ჩაინიშნეთ და შეინახეთ ისინი განვითარების ტრეკერში.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'ბოდიშის მოხდა და იმავეს გამეორება 🧸', 'ვინმეს დარტყმის ან რაიმეს გატეხვის გამო გულწრფელად იხდის ბოდიშს, მაგრამ 5 წუთის შემდეგ ზუსტად იმავეს იმეორებს? მას ჯერ არ შეუძლია საკუთარი იმპულსების მართვა. მოთმინებით, მრავალჯერ აუხსენით წესი.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'გულახდილი საუბრის საჭიროება 💬', 'რთული გადაწყვეტილება უნდა მიიღოთ? (საბავშვო ბაღი, ქოთანი, ძილი). Anacan-ის საზოგადოებაში გამოცდილი დედების რჩევები ცხოვრებისეული და ყველაზე რეალური გამოსავლებია, რომლებსაც ვერცერთ წიგნში ვერ იპოვით.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'ზღაპრის დასასრული თავად დაწეროს 🪄', 'კლასიკური წიგნებით ორივე დაიღალეთ. ამჯერად ჭკვიან ზღაპრებში ისტორიის დასასრული თქვენს ბავშვს აარჩევინეთ. ძილის წინ გაუღვივეთ ფანტაზია შეკითხვით: „შენი აზრით, ვინ დაეხმარა იმ გმირს?“'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'ჯანმრთელი დედა, ჯანმრთელი ბავშვი 🥑', 'ყოველდღიურ სირბილში სადილი ფეხზე მდგომმა არ მიირთვათ. დაჯექით, მოამზადეთ რკინითა და კალციუმით მდიდარი, განსხვავებული სალათა და გემრიელად მიირთვით. თქვენი ენერგია ამ სახლის ძრავაა — გაუფრთხილდით მას.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'სიჩუმის დასტური 🤫', 'ხმაურიანი დღის შემდეგ, როცა ბავშვი დაიძინებს, ხმის საზომით ოთახში სიჩუმის დონე გაზომეთ. ნულთან მიახლოებული ციფრების დანახვაც კი დედის ტვინზე საუკეთესო ვიზუალური მასაჟივით მოქმედებს.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'სამზარეულოს პატარა შემოტევა 🧑‍🍳', 'როცა ცომს აბრტყელებთ, ბავშვი აუცილებლად მოიდგამს გვერდით სკამს და პროცესში ჩაერთვება. მიეცით საკუთარი პლასტმასის ჯამი და აცადეთ, ფქვილი ჩაყაროს. სამზარეულო აირევა, მაგრამ მისი სერიოზული, საქმიანი გამომეტყველება ამდენ დალაგებად ნამდვილად ღირს.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'ერთმანეთისთვის მადლობის თქმა 🥂', 'რთული დღე უკან მოიტოვეთ. ბავშვის დაძინების შემდეგ პარტნიორთან ერთად ჩაი დაისხით და მადლობა გადაუხადეთ სიტყვებით: „ამ ქარიშხლიან დღეს ძალიან დამეხმარე“. გუნდური სულისკვეთება სწორედ ასე იქმნება.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'ხელოვნური ინტელექტი, რეალური პასუხი 🤖', 'რა მეცნიერული და პედიატრების მიერ დადასტურებული მიზეზები აქვს 3 წლის ასაკის კრიზისებს? ინტერნეტში შემაშფოთებელი კომენტარების კითხვის ნაცვლად, ბავშვის ფსიქოლოგიის შესახებ ზუსტი და პროფესიონალური ანალიზი პირდაპირ Anacan AI-ს სთხოვეთ.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'სენსორული გადატვირთვა 🔋', 'მთელი დღე თქვენზე დაცოცავდა, თმას გქაჩავდათ და ხმაურობდა. თქვენი ნერვული სისტემა განგაშის წითელ სიგნალს გაძლევთ. შეხებით გამოწვეული გადაღლა სრულიად რეალურია. ბავშვი პარტნიორს დაუტოვეთ და ცალკე ოთახში განმარტოვდით.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'უცნაური გამოთქმები 🗣️', 'სიტყვებს ისეთი უცნაური და თავისებური ინტონაციით წარმოთქვამს, რომ სიცილის შეკავება რთულია. სიცილით ნუ შეუსწორებთ; პირიქით, ყურადღებით მოუსმინეთ და პასუხად უბრალოდ წინადადების სწორი ფორმა გაუმეორეთ.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'მარკეტში გულმავიწყობის ამბავი 🛒', 'საკუთარ მეხსიერებას ენდეთ, მარკეტში წახვედით და ბავშვის საფენების ყიდვა დაგავიწყდათ? ასეც ხდება. მიეჩვიეთ, რომ ყველაფერი, რაც გჭირდებათ, დაუყოვნებლივ ჩაწეროთ საყიდლების სიაში — დაე, ციფრულმა მეხსიერებამ გიშველოთ.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'გადმოიტანეთ ემოციები ფურცელზე 📝', 'ვერავინ ამჩნევს, რამდენად დაიღალეთ? განწყობის დღიური მზადაა, მოგისმინოთ. ჩაწერეთ იქ ყველა ის წვრილმანი, რომელმაც დღეს ჭკუიდან გადაგიყვანათ, და გონება გაითავისუფლეთ.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'შექმენით პირობები ძილის ჰორმონისთვის 🌙', 'იმისთვის, რომ უფრო სწრაფად ჩაეძინოს, დაძინებამდე 1 საათით ადრე გამორთეთ ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი. ძილის ჰორმონი მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამომუშავდება.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'თავისუფლება პარკში 🌳', 'ოთხ კედელში ყოფნა მას აგრესიულს ხდის. ამინდისა და ჩაცმის დამხმარით შეარჩიეთ გარეთ არსებული ქარისთვის ყველაზე შესაფერისი სამოსი და წადით პარკში. მიეცით საშუალება, ქვიშაში ამოიგანგლოს და სირბილისას წაიქცეს. თავისუფლება მისი განვითარებისთვის საუკეთესო წამალია.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'მოულოდნელი ჩახუტება 💖', 'შუა ოთახში თამაშისას მოულოდნელად შემოგხედავთ, სირბილით მოვა და კისერზე მოგეხვევათ. ყველა უძილო ღამე და დაღლილობა ამად ღირს! დატკბით იმ ღრმა და განუმეორებელი სიმშვიდით, რომელიც ამ წამს მოაქვს.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'დროის აღქმა ყალიბდება ⏱️', 'ხშირად იყენებს სიტყვებს „ხვალ“, „გუშინ“ და „მერე“, თუმცა ზოგჯერ არასწორად? დროის აღქმა თანდათან ყალიბდება! ღიმილით მოუსმინეთ მის მცდელობებს.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'შესვენება დედისთვის ☕', 'როდესაც ბავშვი დამოუკიდებლად თამაშობს, მაშინვე სახლის საქმეების გასაკეთებლად ნუ გაიქცევით. ოთახში არეულობა არსად გაიქცევა, თქვენი ენერგია კი შეიძლება ამოიწუროს. ჩამოჯექით და ცხელი ყავა მიირთვით.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'საწოლიდან გაქცევის გეგმა 🛌', 'ცდილობს საწოლიდან გადმოძრომას? უსაფრთხოებისთვის ოთახი თავიდან შეამოწმეთ. უკვე ახლოვდება ბავშვის დიდ საწოლზე გადასვლის დრო.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'წარმოსახვითი სცენარები 🧸', 'სათამაშოებს აჭმევს ან მკურნალობს? სიმბოლური თამაშები ემპათიის საფუძველია. განვითარების ტრეკერში სიამაყით აღნიშნეთ ეს კოგნიტიური ნახტომი.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'ჯადოსნური ღამის ფონი 🪄', 'ჩაძინება უჭირს? „ჭკვიან ზღაპრებში“ შექმენით კბილების გახეხვის მოყვარული გმირი დათუნიას ამბავი და ახალი ჩვევები ზღაპრად აქციეთ.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'ურთიერთობა პარკში 🌳', 'სხვა ბავშვებთან თამაშის ნაცვლად, მათ გვერდით თავისთვის თამაშობს? პარალელური თამაში ამ ასაკისთვის სრულიად ბუნებრივია. ზეწოლის გარეშე შეუწყვეთ ხელი მის სოციალიზაციას.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'ბროკოლის დეტექტივი 🥦', 'წვნიანში ერთადერთ მწვანე ბოსტნეულს პოულობს და ჭამაზე უარს ამბობს? კვების გეგმაში აღმოაჩინეთ ბოსტნეულის ფერად მაკარონში შერევით ყურადღების გადატანისა და სასარგებლო საკვების დამალვის უგემრიელესი გზები.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'გრძნობების აღიარება 📝', 'თავს ცუდად გრძნობთ, რადგან მთელი დღე ყველაფერზე „არას“ ამბობთ? გახსენით განწყობის დღიური. დღეს დაუფარავად ჩაწერეთ თქვენი ყველაზე ბნელი ფიქრი — „ნეტავ მარტო ვიყო“. თავს ნუ დაიდანაშაულებთ, ყველა დედა ზოგჯერ იღლება და გაქცევა სურს.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'ეს ჩემი ბრალი არ არის! 🤷‍♂️', 'წყალი განზრახ დაღვარა იატაკზე, მაგრამ მაგიდას დააბრალა და თქვა: „მაგიდა გაცურდა“. ეს ტყუილი კი არა, ბავშვის ტვინის პასუხისმგებლობისგან თავის არიდებისა და თავდაცვის ინსტინქტია. ნუ შეეწინააღმდეგებით. უთხარით: „მოდი, მაგიდას დავეხმაროთ და ერთად გავწმინდოთ“ — ასე პასუხისმგებლობას მისთვის გულისტკენის გარეშე ასწავლით.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'ოთხ კედელში ყოფნის ფსიქოლოგია ⛅', 'სახლში ყოფნა გაწუხებთ, ბავშვი კი აგრესიული ხდება. შეამოწმეთ ამინდი, შეარჩიეთ შესაფერისი ტანსაცმელი და სასწრაფოდ პარკისკენ გაეშურეთ. ჟანგბადი და მოძრაობის თავისუფლება საუკეთესო განტვირთვა იქნება როგორც მისი გონებისთვის, ისე თქვენი გადაღლილი ნერვებისთვის.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'ტანსაცმლის დაკეცვის ოპერაცია 🧺', 'თქვენ დიდი მონდომებით კეცავთ სუფთა ტანსაცმელს, ის კი 2 წამში შიგნით ძვრება და ყველაფერს ყრის. ოთახში სამარისებური სიჩუმე ისადგურებს... ნერვები ზღვარზე გაქვთ? ღრმად ჩაისუნთქეთ. გადაეშვით დაყრილი ტანსაცმლის გროვაზე და სიცილით დანებდით ამ ქაოსს.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'ჭკვიანი ზღაპრის რეჟისორი 🪄', 'კლასიკური წიგნების გმირები ორივეს მოგბეზრდათ. გახსენით ჭკვიანი ზღაპრები და ამ საღამოს სიუჟეტის მოფიქრება მას მიანდეთ. ჰკითხეთ: „ახლა სად წავიდეს ეს მფრინავი დინოზავრი?“ — და მიეცით საშუალება, თავისივე გამოგონილ სამყაროში ჩაეძინოს.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'მამის ფრენის რეჟიმი ✈️', 'სახლში ენერგია ვერ დახარჯა და დასაძინებლად რომ არ წავიდეს, ათასგვარ მიზეზს იგონებს. მამას დაუძახეთ. როდესაც ის ბავშვს ჰაერში აიყვანს და თვითმფრინავის ფრენას გაითამაშებს, ოთახი სიცილით ივსება, დაგროვილი ფიზიკური დაძაბულობა კი ოფლის მოდენასთან ერთად ქრება.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', '„ცუდი დედა ხარ!“ — მტკივნეული დარტყმა 💔', 'სასურველი სათამაშო არ უყიდეთ და პირდაპირ სახეში გითხრათ, ცუდი ხარო? გულს ნუ გაიტეხთ. მას ჯერ არ შეუძლია საკუთარი გრძნობების სწორი სიტყვებით გამოხატვა — სინამდვილეში იმის თქმა სურს, რომ ძალიან გაბრაზებული და იმედგაცრუებულია. დაამყარეთ თვალით კონტაქტი და უბრალოდ აგრძნობინეთ, რომ მის ემოციას აღიარებთ.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', '„მე წავიყვან!“ — სიჯიუტე მაღაზიაში 🛒', 'სურს, სავაჭრო ურიკა თავად ატაროს, თაროებს ეჯახება და ყველას ყურადღებას იქცევს. როგორც კი ჩაერევით, ტირილს იწყებს. მიეცით საშუალება, ურიკა ერთად ატაროთ. რაიმე რომ არ დაგავიწყდეთ, აპში საყიდლების სია აქტიური გქონდეთ — ასე თქვენი გონებაც ნაკლებად გადაიღლება.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'ხმის საზომის სიჩუმე 🤫', 'როგორც იქნა, დაიძინა! სახლში გამეფებული სიჩუმე იმდენად ღრმაა, რომ ყურებში გიწუით. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს უყურეთ, რათა თვალნათლივ იგრძნოთ, როგორ მშვიდდება ნელ-ნელა თქვენი გონება.'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'საზოგადოება — თქვენი მესაიდუმლე 💬', 'ძალიან დაიღალეთ და არ გსურთ, ვინმეს რამე აუხსნათ. შედით Anacan-ის საზოგადოებაში და უბრალოდ მკითხველად დარჩით. სხვა დედების მსგავსი დაღლილობისა და მათი ბავშვების სასაცილო კრიზისების ნახვა გაგიჩენთ განცდას, რომ მარტო არ ხართ — ეს კი საუკეთესო დამამშვიდებელია.'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'სამზარეულოს პატარა მზარეული 🧑‍🍳', 'როცა ცომს აბრტყელებთ, აუცილებლად მოიდგამს გვერდით სკამს და პროცესში ჩაერთვება. მიეცით საკუთარი პლასტმასის ჯამი და საშუალება, შიგნით ფქვილი ჩაყაროს. სამზარეულო დასასუფთავებელი გახდება, მაგრამ მისი სერიოზული, საქმიანი სახე და განცდა — „მეც შემიძლია“ — ამად ნამდვილად ღირს.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'უკუღმა ჩაცმის სიამაყე 🧦', 'წინდების ქუსლი ტერფის ზემოთ აქვს მოქცეული, მაგრამ ამაყად დადის, რადგან თავად ჩაიცვა. საერთოდ ნუ ჩაერევით. მისი განცდა — „მე ეს შევძელი“ — მილიონჯერ უფრო ღირებული ფსიქოლოგიური საფუძველია, ვიდრე ესთეტიკა ან სწორად ჩაცმა. მიეცით საშუალება, მთელი დღე ასე გაატაროს.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'დედის ოფლაინ წუთები ☕', 'ის დამოუკიდებლად აწყობს ფაზლს და უკვე 10 წუთია ჩუმადაა. თქვენ კი ამ დროის სახლის დალაგებისთვის გამოყენება გინდათ. არა! წადით და დივანზე წამოწექით. თქვენი ელემენტიც უნდა დაიმუხტოს, რომ საღამომდე ამ ტემპს გაუძლოთ.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'სიბნელესთან დამეგობრება 🐰', 'დაძინება არ სურს და ამბობს, რომ ოთახში ჩრდილების ეშინია? ოთახი მთლიანად დააბნელეთ და კედელზე ხელებით ფრინველისა და ძაღლის ჩრდილები გამოსახეთ. შიშის გართობად ქცევით დაეხმარეთ, სიბნელეს დაუმეგობრდეს და საკუთარი წარმოსახვის მართვა ისწავლოს.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'ხელოვნური ინტელექტი და შფოთვა 🤖', 'შეგაშფოთათ იმან, რომ ბავშვი ზოგიერთ ბგერას ჯერ კიდევ სწორად ვერ წარმოთქვამს? დახურეთ ინტერნეტში არსებული შემაშინებელი ფორუმები. ჰკითხეთ Anacan AI-ს, როგორია მეტყველების განვითარების ნორმები დაახლოებით 38 თვის ასაკში და მიიღეთ მეცნიერულად დასაბუთებული, რეალობასთან შესაბამისი პასუხი.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'შენ იყავი ბავშვი, მე კი — დედა 👩‍👧', 'როლების გაცვლის თამაში დაიწყო! ის მითითებებს გაძლევთ: „აქ მოდი“, „საჭმელი ჭამე“, „არ იტირო“. დიდი სიამოვნებით მიიღეთ მისი ლიდერობის ეს გამოცდილება და უსიტყვოდ შეასრულეთ მისი ბავშვის როლი — ეს ემპათიის განვითარების ერთ-ერთი უმთავრესი გზაა.'),
  ('b97073a4-f745-41b1-953a-0e776ded1591', 'ჩააქრეთ შუქი, რომ ძილი მოვიდეს 🌙', 'დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ, რათა ბავშვს სწრაფად ჩაეძინოს. მელატონინი სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'თეატრი სარკის წინ 🎭', 'დილაადრიან სარკის წინ დგება და ტირილის, სიცილისა და გაოცების სხვადასხვა მიმიკას ავარჯიშებს. ის აღმოაჩენს, როგორ გამოხატოს საკუთარი ემოციები და როგორ იცვლება ამ დროს მისი სახე. ღიმილით ადევნეთ თვალი შორიდან ამ გენიალურ სამსახიობო წარმოდგენას.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'მამის ჯადოსნური მკლავები 🫂', 'მთელი დღე ხელში ტარებით მკლავები გწყდებათ, მას კი ისევ ჩახუტება სურს. მამას დაუძახეთ. მამის მკლავებში ფრენა ბავშვის ყურადღების მოთხოვნილებასაც დააკმაყოფილებს და თქვენს მკლავებსაც დამსახურებული დასვენების საშუალებას მისცემს.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'ნაგავი კი არა, ხელოვნება 🎨', 'ოთახის შუაგულში ქაღალდის პატარა ნაგლეჯებისა და დაჭრილი ძაფებისგან დიდი ხელოვნების ნიმუში შექმნა და მისი გადაგდების უფლებას არ გაძლევთ. სისუფთავისადმი ზედმეტი მიდრეკილება გვერდზე გადადეთ. პატივი ეცით მის მიერ შექმნილ ქაოსს — დალაგება ხვალამდეც მოიცდის.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', '„მე თვითონ!“ — წინააღმდეგობა 🛑', 'ფეხსაცმლის თასმის შეკვრა თავად სურს, თქვენ კი სახლიდან გასვლა უკვე 10 წუთით დაგაგვიანდათ. ნუ იჩქარებთ. მისი განვითარებისთვის დაგვიანებულ განრიგზე უფრო მნიშვნელოვანი ჯანსაღი თვითშეფასებაა. მიეცით ცდის საშუალება.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'ჩურჩულით მოყოლილი ამბები 🌙', 'დღეს იმდენი ილაპარაკეთ, რომ ხმა და ფილტვები დაგეღალათ. ჩააქრეთ შუქი, მის გვერდით დაწექით და დღის ამბები უბრალოდ ჩურჩულით მოუყევით ყურში. ჩურჩული მის ყურადღებას იპყრობს და ტვინს ჰიპნოზივით ამზადებს ღრმა ძილისთვის.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'მითები იდეალური დედის შესახებ 🛑', 'სოციალურ ქსელებში სხვა ბავშვებმა უკვე იციან ფერები და ინგლისურად თვლაც შეუძლიათ, თქვენს ბავშვს კი არ სურს? დაუყოვნებლივ შეწყვიტეთ შედარება! თითოეული ბავშვის განვითარების ტემპი უნიკალური და განსხვავებულია. ის თავის ტემპში სრულყოფილია.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'დღის ძილის დრო დასრულდა? ⏱️', 'საღამოს ჩაძინებას 1 საათზე მეტი სჭირდება? გადახედეთ ძილის ტაიმერის გრაფიკს. 3 წლის ასაკის რთულ პერიოდში შესაძლოა დადგა დრო, დღის ძილი სრულად გააუქმოთ და საღამოს დაძინების დრო გადმოწიოთ.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'დაუსრულებელი „რატომ?“ კითხვები 🌪️', '„თევზები რატომ არ დადიან?“, „მზე სად წავიდა?“ — დილაადრიან მისი გონება საათში 100 კითხვის სიჩქარით ეძებს პასუხებს. დაღლის მიუხედავად, გაეცით ლოგიკური და მოკლე პასუხები. ის სამყაროს საიდუმლოებებს თქვენი ხმის ტონიდან შეიცნობს.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'დასვრის სრული ნებართვა 🏖️', 'ტალახითა და ქვიშით თამაში სურს? მიეცით დასვრის უფლება! სენსორული განვითარების ხელშემწყობი ამ აქტივობებისთვის მარტივად გასაწმენდი ნივთები „რეკომენდებულ პროდუქტებში“ იპოვეთ და ბავშვს თავისუფლად თამაშის საშუალება მიეცით.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'ბრძოლა ჩრდილთან 👻', 'კედელზე საკუთარი ჩრდილის ეშინია და თქვენ უკან იმალება? წარმოსახვას საზღვრები არ აქვს. ჩააბნელეთ ოთახი და ფარნის შუქზე ხელებით კედელზე ჩრდილების თეატრი მოაწყვეთ.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'მუსიკით ძილისთვის მომზადება 🎶', 'სცადეთ, საღამოობით უმიზეზოდ ატეხილი ჭირვეულობა მშვიდი კლასიკური მუსიკით შეაჩეროთ. ხშირად ეს მარტივი, მაგრამ ეფექტური ხერხი სახლში სასწაულს ახდენს და ოთახში აუცილებლად სასიამოვნო, დამამშვიდებელი სიმშვიდე ისადგურებს.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'სხეულის განგაშის სიგნალი 🩸', 'ნუ დანებდებით უმიზეზო გაღიზიანებასა და დაღლილობას. შეამოწმეთ მენსტრუაციის ტრეკერი — თქვენი სხეული სიგნალს გაძლევთ. საკუთარი თავის დადანაშაულების ნაცვლად, დაისვენეთ და მაგნიუმით მდიდარი წასახემსებელი მიირთვით.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'სიტყვების განზრახ შეცვლა 🗣️', '„მანქანის“ ნაცვლად დაჟინებით „ქანმანას“ ამბობს და ელოდება, რომ გაგეცინებათ. ის უკვე იუმორის გრძნობას აღმოაჩენს. გაიცინეთ, მაგრამ არ დაგავიწყდეთ, ყოველ ჯერზე სწორი გამოთქმაც მსუბუქად გაუსვათ ხაზი, რათა მისმა ტვინმა სწორი ვარიანტიც დაიმახსოვროს.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'დედა, თავადაც დანაყრდით 🥗', 'მისთვის კვერცხი 4 სხვადასხვა წესით მოამზადეთ, მაგრამ თავად რა მიირთვით? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინითა და კალციუმით მდიდარი კერძი, რომლის მომზადებასაც 5 წუთი სჭირდება, დააჯილდოეთ საკუთარი თავი და შეინარჩუნეთ ენერგია.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'ძილის გადადების ტაქტიკა ⏱️', 'როგორც კი დაძინების დრო დგება, უცებ სწყურდება, ტუალეტში მოუნდება წასვლა ან კედელს ემშვიდობება? დააყენეთ ტაიმერი. შემოიღეთ წესი — „როცა ზარი დაირეკება, ყველა იძინებს“ — და ამ უსასრულო დამშვიდობებას მოთმინებითა და სიმშვიდით დაუსვით წერტილი.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'თათბირი სათამაშოებთან 🧸', 'ყველა დათუნიასა და მანქანას მწკრივში აყენებს და თითის ქნევით ძალიან სერიოზულად უხსნის რაღაცას? მას ლიდერობის უნარი და ყურადღების კონცენტრაცია უვითარდება. დადექით ოთახის კუთხეში და ამ გამოგონილ თათბირს ჩუმად, მისთვის ხელის შეუშლელად დააკვირდით.'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'მამის უცნაური ხმები 🤡', 'როცა თქვენი ხრიკები აღარ ჭრის, მამის მიერ გამოცემული ცხოველების უცნაური ხმები და სასაცილო სახეები სიტუაციას მაშინვე შველის. საღამოს ჭირვეულობის დროს ეს საქმე მას გადააბარეთ და გვერდიდან მხიარულ სიცილს უყურეთ.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'დღის ძილის წინააღმდეგ აჯანყება 🥱', 'საწოლში დაწოლა არ სურს და ტირის? ნუ აიძულებთ. ოთახში განათება შეამცირეთ, გამოაცხადეთ „წიგნის ჩუმად ფურცვლის საათი“ და შექმენით ახალი რუტინა, რომელიც ორივეს დაგასვენებთ — ასე თქვენც დაისვენებთ და ბავშვიც.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'ფიქრები საბავშვო ბაღზე 🏫', 'გრძნობთ, რომ მას უკვე უფრო მეტად სჭირდება სოციალიზაცია? შესაფერისი დროა საბავშვო ბაღისთვის? შეუერთდით Anacan-ის საზოგადოებას, გაეცანით სხვა დედების ადაპტაციის რეალურ გამოცდილებას და გაიმარტივეთ გადაწყვეტილების მიღება.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'უეცარი ბრაზის შეტევა 💥', 'თამაშისას უცებ გაბრაზდა და სათამაშოების სროლა დაიწყო? მას ჯერ არ შეუძლია საკუთარი ემოციების მართვა. ყვირილის ნაცვლად უთხარით: „ვხედავ, რომ გაბრაზდი. მოდი, ერთად ღრმად ჩავისუნთქოთ“, თანაგრძნობა გამოხატეთ და მასთან ემოციური კავშირი შეინარჩუნეთ.'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'ნერვიულობს, როცა საძინებელში შუქი ქრება? 🌙', 'ოთახის ერთ კუთხეში პატარა, თბილი ფერის ღამის სანათი დადგით. ოთახის დანარჩენი ნაწილი კი ღრმა ძილისთვის სრულიად ბნელი უნდა დარჩეს.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'უსულო საგნებთან საუბარი 🗣️', 'პარკში ქვას ან სახლში სკამს სრული სერიოზულობით რაღაცებს ეუბნება და ტუქსავს. სიმბოლური თამაშების მეშვეობით ბავშვი სამყაროს აღიქვამს და იაზრებს. განვითარების ტრეკერში აუცილებლად მონიშნეთ მისი ეს განსაკუთრებული სცენარები.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'თბილი წყლის სასწაული 🛀', 'ზოგჯერ არაფერი ჭრის და ბავშვი უბრალოდ ყველაფერზე ტირის. ჩასვით თბილი წყლით სავსე აბაზანაში და ცოტაოდენი ქაფი დაუმატეთ. წყლის ეს ჯადოსნური, დაძაბულობის მომხსნელი ძალა მყისიერად სიმშვიდეს მოჰგვრის როგორც მთელ ოთახს, ისე მის ნერვულ სისტემას.'),
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206', 'ამინდის გაფრთხილება ⛅', 'სასეირნოდ გასვლისას მხოლოდ ფანჯრიდან დანახულ ამინდს ნუ ენდობით. ამინდისა და ჩაცმულობის დამხმარის მეშვეობით გარეთ არსებულ ქარსა და ტემპერატურას ყველაზე შესაფერისი სამოსი შეურჩიეთ, სახლიდან მშვიდად და მომზადებული გახვიდეთ და ბავშვს საშუალება მისცეთ, ენერგია სუფთა ჰაერზე დახარჯოს.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'მულტფილმების კრიტიკოსი 📺', 'ნანახ მულტფილმს თავისი გრამატიკით გიყვებათ და სრული სერიოზულობით გიხსნით, ვინ სად წავიდა. ყურადღებით და გაოცებული სახით მოუსმინეთ. მიეცით საშუალება, თავი მსოფლიოში ყველაზე ჭკვიანად იგრძნოს.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'სრულყოფილება არ არსებობს 🛑', 'დღეს არაფერი წავიდა გეგმის მიხედვით? თავს ნუ დაიდანაშაულებთ. თქვენ ნამდვილი დედა ხართ და არა სოციალურ ქსელებში გაფილტრული ილუზია. თქვენს ბავშვს მხოლოდ თქვენი ღიმილი და ჩახუტება სჭირდება.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'ღამის ტერორის საიდუმლო 😭', 'შუაღამისას დახუჭული თვალებით ტირილით იღვიძებს და ვერავის ამჩნევს. გადაამოწმეთ ტირილის ანალიზით; თუ ეს ძილის ტერორია, ნუ ეცდებით მის გაღვიძებას. უბრალოდ მის გვერდით იყავით და ჩუმად აგრძნობინეთ, რომ უსაფრთხოდაა.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც თამაშია საჭირო, არც წიგნი და არც ზღაპარი. ამ საღამოს უბრალოდ გულში ჩაიკარით, ღრმად შეისუნთქეთ მისი მშვენიერი სურნელი და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'სახიფათო სიტყვები 🤐', 'სადღაც გაგონილ ცუდ სიტყვას სიცილით გიმეორებთ და თქვენს რეაქციას ელოდება? თქვენი ყველაზე ძლიერი იარაღი რეაქციის არქონაა. ნუ გაიცინებთ, ნუ გაბრაზდებით, უბრალოდ ყურადღება არ მიაქციოთ. მალე ამ სიტყვას დაივიწყებს.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'არეული სახლის ნებართვა 🌪️', 'დაიღალეთ ყოველდღე ერთი და იმავე სათამაშოების ალაგებით? დღეს ნუ აალაგებთ! სახლი მუზეუმი კი არა, სიცოცხლით სავსე ადგილია. უწესრიგობაზე კი არა, თქვენი ბავშვის თავისუფლად სწავლის სიხარულზე გაამახვილეთ ყურადღება და დაისვენეთ.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'ქვემოთ ჩაიხედეთ — რას აღმოაჩენს? 👣', 'მას სიამოვნებს ფეხშიშველი სიარული, ხალიჩასა თუ ოთახში არსებულ ქვებზე შეხება. ტერფებზე არსებული ნერვული დაბოლოებების გააქტიურება მისი წონასწორობისა და მოტორული უნარებისთვის ძალიან მნიშვნელოვანია, ამიტომ მიეცით საშუალება, წინდების გარეშე იაროს.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661'::uuid, 'პაუზა წყვილისთვის 🥂', 'ბავშვს ჩაეძინა. ახლა საოჯახო საქმეები გვერდზე გადადეთ. პარტნიორს მინიმუმ 20 წუთის განმავლობაში ესაუბრეთ ნებისმიერ თემაზე, გარდა ბავშვისა და ხარჯებისა. გახსოვდეთ, თქვენ წყვილიც ხართ!'),
  ('9d8da9d6-f615-4275-a01c-20687a161090', 'საყიდლების მხსნელი 🛒', 'მაღაზიაში წასვლისას ყოველთვის ყველაზე მნიშვნელოვანი რამ გავიწყდებათ? საყიდლების სია აპში გელოდებათ. საჭირო ნივთები იქ ჩაინიშნეთ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ზუსტად ის იყიდოს, რაც საჭიროა, თქვენ კი გონება აღარ გადაიტვირთოთ.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'გულის მოფხანა დღიურში 📝', 'ვინმემ გითხრათ: „სახლში ხარ და რა გღლის?“ მაშინვე გახსენით განწყობის დღიური და მთელი გაღიზიანება თითებით ეკრანზე გადმოიტანეთ. ხელოვნურად გაღიმების ნაცვლად ნამდვილი გრძნობების დაწერა თერაპიულია.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'მე აგიხსნი! ☝️', 'მოდის და იმას, რაც უკვე იცით, ძალიან სერიოზული და ჭკვიანური გამომეტყველებით გიხსნით. ასე საკუთარ ცოდნას ამოწმებს. მართალია, შეიძლება სიცილის შეკავება გაგიჭირდეთ, მაგრამ ყურადღებით და სერიოზულად მოუსმინეთ და მისი აზრი დაადასტურეთ.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'სიჩუმის ციფრული საზომი 🤫', 'ბოლოს და ბოლოს ჩაეძინა! სახლში გამეფებული სიჩუმე დაუჯერებელია. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს შეხედეთ — იგრძნობთ, როგორ ისვენებს ნელ-ნელა თქვენი გონება.'),
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1', 'ამინდის დაზვერვა ⛅', 'გარეთ ბოლომდე მოწმენდილი ამინდი არ არის? ამინდისა და ჩაცმულობის ხელსაწყო მყისიერად გეტყვით ფანჯრიდან შეუმჩნეველ ქარის სიჩქარეს და სწორად შერჩეულ სამოსს.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'ფეხსაცმელს თვითონ იხდის 👟', 'ჩაცმა უკვე ჭიდაობის სახეობად იქცა? ბავშვი წინდებსა და ფეხსაცმელს თვითონ იძრობს. აღფრთოვანდით მისი მოტორული უნარებით!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'მამის მხარდაჭერა 🫂', 'ღამით ბავშვის გაღვიძებისას ერთხელ თქვენ ადექით, ერთხელ კი — თქვენი მეუღლე. გუნდურად მოქმედებით დატვირთვა ზუსტად შუაზე გაინაწილეთ.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'ძილის შემაფერხებელი ტუალეტი 🚽', 'როგორც კი დაძინებას აპირებს, უცებ ამბობს, რომ ტუალეტში უნდა. მიგყავთ, მაგრამ არაფერი ხდება. ეს დაძინების გადადების ხელოვნებაში ყველაზე დახვეწილი ტაქტიკაა. ნუ დაუყვირებთ; მკაფიოდ დააწესეთ ზღვარი: „ბოლოჯერ მივდივართ და პირდაპირ საწოლში ვბრუნდებით“.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'საწოლებს შორის მოგზაური 🛏️', 'ღამეს თავის საწოლში იწყებს, დილით კი თქვენს საწოლში იღვიძებს — თანაც მთლიანად განივად გაწოლილი და ფეხებით თქვენს სახეზე. მის მიერ სივრცის ამგვარ დაპყრობას ღიმილით შეხვდით. თქვენი თბილი სურნელი მისთვის ყველაზე უსაფრთხო თავშესაფარია.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'ყუთის ჯადოსნობა 📦', 'თქვენ მიერ ნაყიდი ძვირადღირებული და ხმაურიანი სათამაშო გვერდზე მოისროლა და უკვე 1 საათია, მის ყუთს ეთამაშება? ბავშვის ტვინს მზა სცენარებზე მეტად ცარიელი ნივთები მოსწონს, რომელთა შევსებაც წარმოსახვით შეუძლია. მუყაოს ყუთი მისთვის კოსმოსური ხომალდია — ნუ შეეხებით.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'ზამთარში ზაფხულის ამბოხი ❄️', 'გარეთ ქარია, მას კი ჯიუტად სურს ზაფხულის შორტების ჩაცმა. ახსნა მხოლოდ დროის კარგვაა. გახსენით ამინდისა და ჩაცმულობის ხელსაწყო და ეკრანზე თბილად ჩაცმული ბავშვის სიმბოლო აჩვენეთ. ხრიკი — „ნახე, ტელეფონიც ამბობს, რომ დღეს შარვალი უნდა ჩავიცვათ“ — შესანიშნავად მუშაობს.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'წარმოსახვითი ჩაკბეჩა 🍏', 'ხელში არაფერი უჭირავს, მაგრამ თქვენთან მოდის და წარმოსახვით ვაშლს გიწვდით: „აიღე, ჩაკბიჩე“. როლური თამაშები პიროვნების ჩამოყალიბების ერთ-ერთი უმნიშვნელოვანესი ნაწილია. დიდი მადით ჩაკბიჩეთ ცარიელ სივრცეს, „ხრაშუნის“ ხმაც გამოსცეთ და დაუდასტურეთ, რომ ეს მსოფლიოში ყველაზე გემრიელი ვაშლია.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'ურჩხული ფანჯარასთან 👻', 'გარეთ მოქანავე ხის ჩრდილი ოთახში ეცემა, ბავშვს კი ეშინია და თქვენს ზურგს უკან იმალება. ოთახში შუქს ნუ აანთებთ. აიღეთ ფანარი, ჩრდილს მიანათეთ და უთხარით: „ნახე, ეს უბრალოდ ხის ცეკვაა“. ასე შიშს ჯადოსნურ ამბად გადააქცევთ.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', '„შემომხედე!“ მარათონი 👀', 'გაღვიძებისთანავე ზუსტად 40-ჯერ გითხრათ: „დედა, შემომხედე“? ხტება, ტრიალებს და თქვენს მოწონებას ელის. მოსწყვიტეთ თვალი ტელეფონს, მხოლოდ 3 წუთით მთლიანად მასზე გადაერთეთ და უთხარით: „არაჩვეულებრივი ხარ“. ეს უწყვეტი ყურადღება საკმარისი იქნება, რომ მისი მოთხოვნილება დაკმაყოფილდეს.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'დედის უფლება, იზარმაცოს 🍕', 'დღეს ყველაფერზე ყვირილი გინდათ? სახლი თავდაყირაა? დალაგებას თავი დაანებეთ და სამზარეულოშიც ნუ შეხვალთ. პიცა ან რამე მარტივი შეუკვეთეთ. დაანგრიეთ იდეალური დედის ილუზია — თქვენი ფსიქიკური ჯანმრთელობა სახლში მომზადებულ საჭმელზე გაცილებით ძვირფასია.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'წყვილის კომა 📺', 'ბავშვმა დაიძინა! როგორც იქნა, პარტნიორთან ერთად ფილმის საყურებლად დივანზე მოკალათდით, მაგრამ 10 წუთის შემდეგ ორივეს ჩაგეძინათ. ეს თქვენი რეალობაა. ერთმანეთზე მიყრდნობილი ორი დაღლილი, მაგრამ ტკბილად ჩაძინებული ადამიანის სურათი სწორედ რომ სიყვარულია.'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'საკვების არჩევითობაში ლოგიკა არ არსებობს. 🥦', 'გუშინდლამდე სიამოვნებით მიირთმევდა იმ სუპს, დღეს კი პირს არ აკარებს? გადადით ჯანსაღ რეცეპტებზე და აღმოაჩინეთ, როგორ დამალოთ ბოსტნეულის პიურე ფერადი მაკარონის სოუსებში. დაეუფლეთ შენიღბვის ხელოვნებას.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'წყალქვეშა სამეფო 🛀', 'აბაზანაში ბანაობა უკვე სისუფთავის პროცედურა კი არა, წყალქვეშა ნავის მისიაა. აცადეთ, წყალი ირგვლივ აშხეფოს. წყლის ეს ჯადოსნური ეფექტი მთელი დღის განმავლობაში მასში დაგროვილ ჯიუტ, უარყოფით ენერგიას ჩამორეცხავს და კანალიზაციაში გაატანს.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'გენიალური გამომგონებელი 👟', 'ფეხსაცმელს ყურთან მიიდებს და სერიოზული სახით ამბობს „ალო“, შემდეგ კი რაღაცებს ლაპარაკობს. ის ნივთებს ახალ ფუნქციებს უგონებს! არ გამოტოვოთ ეს აბსურდული და გენიალური კადრი. ბავშვის ფოტოსესიით აღბეჭდეთ ეს კომიკური გამომგონებელი და ფოტოების არქივში ყველაზე თვალსაჩინო ადგილი მიუჩინეთ.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'ციფრული სიჩუმის თერაპია 🤫', 'ოთახში როგორც იქნა სრული სიჩუმე დაისადგურა. ნუ იჩქარებთ ჭურჭლის სარეცხ მანქანაში ჭურჭლის ჩალაგებას. ჩართეთ ხმის საზომი ხელსაწყო, დააკვირდით, როგორ ეცემა ეკრანზე რიცხვები 0 დეციბელამდე და იგრძენით, როგორ ისვენებს თქვენი დაღლილი გონება.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'ნაგვის გამრავლების ოსტატი ✂️', 'სუფთა ფურცელს ხელში ჩაიგდებს, ათას პატარა ნაწილად აქუცმაცებს და ოთახში მიმოფანტავს? ასე წვრილი მოტორიკა ვითარდება! ნუ გაბრაზდებით და ნუ გაიქცევით ცოცხის მოსატანად. შეაგროვეთ ნაკუწები ყუთში და ითამაშეთ თოვლის მოსვლის თამაში.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'მეტოქე სარკეში 🪞', 'სარკის წინ დგას, საკუთარ თავს წარბებს უქშენს და გაბრაზებულ, უცნაურ სახეებს იღებს. ის ამოწმებს, როგორ აისახება ემოციები სახეზე. ჩუმად და ინტერესით უყურეთ ამ მინიატიურული თეატრის მსახიობის რეპეტიციას.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'მარტოობის მონატრება 🚪', 'მთელი დღე თქვენს სხეულზე აცოცებითა და მოფერებით დაღლილი ხართ. ტუალეტში შეხვედით, კარი ჩაკეტეთ და 5 წუთით მარტო დარჩით. დაუყოვნებლივ გახსენით განწყობის დღიური, ეკრანზე გადმოიტანეთ გულში დაგროვილი სიმძიმე და შვება იგრძენით.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'ამბის რეჟისორი 🪄', 'ამ საღამოს თქვენი ხმა დაიღალა. ჩართეთ ჭკვიანი ზღაპრები. უთხარით თქვენს ბავშვს: „დღეს მთავარი გმირი შენ ხარ, ფონად კი წვიმის ხმა ისმის“, შეუქმენით განსაკუთრებული, დამამშვიდებელი და პერსონალიზებული ხმოვანი გარემო და მშვიდად დააძინეთ.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'პირველი აბსურდული ხუმრობა 🤡', 'ამბობს: „ძაღლი მანქანაში ჩაჯდა და აფეთქდა!“ — და საკუთარ ხუმრობაზე ხმამაღლა კისკისებს. ამას არანაირი აზრი არ აქვს, მაგრამ ბავშვი იუმორის გრძნობას ახლა აღმოაჩენს. ლოგიკას ნუ დაუწყებთ ძებნას — თქვენც ხმამაღლა აჰყევით მის ამ გულწრფელ და მხიარულ სიცილს.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'სასრიალოს პოლიტიკა 🛝', 'პარკში სასრიალოს თავზე დგას და სხვა ბავშვებს ჩამოსრიალების საშუალებას არ აძლევს. ნუ შეგრცხვებათ და ძალით ნუ ჩამოიყვანთ. გარშემომყოფების ყურადღებას ნუ მიაქცევთ და მშვიდად შეახსენეთ, რომ ყველამ რიგი უნდა დაიცვას. ასე იცავს ბავშვი საკუთრების განცდას.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'ის უკვე ჩვილი აღარ არის! 🌟', 'ის სრულფასოვანი ადამიანია — საკუთარი გადაწყვეტილებებით, უცნაური კითხვებითა და უზარმაზარი გულით. დიდი მადლობა გადაუხადეთ საკუთარ თავს იმისთვის, რომ მის ძლიერ ხასიათს კი არ თრგუნავთ, არამედ სწორ მიმართულებას აძლევთ. თქვენ შესანიშნავად ართმევთ თავს.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'გამარჯვება შამპანურის გარეშე 🥂', 'რთული დღის შემდეგ ჭიქებში ჩვეულებრივი ცხელი ჩაი ჩამოასხით. თქვენს პარტნიორთან ერთად დივანზე პირისპირ დაჯექით, თქვით: „დღეს იმ ქაოსსაც გადავურჩით“ და ჭიქები მიუჭახუნეთ. თქვენ ამ სახლის მეთაურებიც ხართ და ერთი გუნდიც.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'საზოგადოების ძალა 💬', 'ფიქრი — „რატომ არის ჩემი ბავშვი ასეთი ჯიუტი?“ — მოსვენებას არ გაძლევთ. შეუერთდით Anacan-ის საზოგადოებას. როდესაც სხვა დედების ოჯახებში მომხდარ მსგავს აბსურდულ კრიზისებზე წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ და სრულიად ნორმალურ გზას გადიხართ.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'სინათლის რიტმი 🌙', 'იმისთვის, რომ ბავშვს უფრო სწრაფად ჩაეძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა, რაც საქმეს გაგიმარტივებთ.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'დინოზავრის საუზმე 🦖', 'საუზმობისას სურს, ხელების გამოუყენებლად, პირი პირდაპირ თეფშთან მიიტანოს და დინოზავრივით ჭამოს. ნუ ჩაუტარებთ აღზრდის გაკვეთილს! მიეცით საშუალება, 5 წუთით დინოზავრი იყოს — ეს თამაში მალე მობეზრდება და კოვზს ისედაც აიღებს.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', '„მე თვითონ“ სიჩქარე 🐢', 'სახლიდან უნდა გახვიდეთ, მაგრამ მას ფეხსაცმლის აუცილებლად თავად ჩაცმა სურს და კუს სიჩქარით ამას 15 წუთი სჭირდება. თუ ჩაერევით, ტირილის კრიზისი 30 წუთს გაგრძელდება. ყურადღება დაკარგულ დროზე კი არა, მის დაუზიანებელ თვითშეფასებაზე გაამახვილეთ და დაელოდეთ.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'გაუჩინარებული გასაღებები 🔑', 'სახლის გასაღებებს ვერ პოულობთ? მაცივარში ან ფეხსაცმლის კარადაში ჩაიხედეთ. ნივთების დამალვით ბავშვი ობიექტის მუდმივობის პრინციპს ამოწმებს. ამ სახალისო განძის ძიებისას გაბრაზების ნაცვლად სიცილი აირჩიეთ.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'ჩურჩულის ჰიპნოზი 🤫', 'საწოლში წევს, ფეხები ჰაერში აქვს აწეული და დაძინება არ სურს. ყვირილის ნაცვლად მოულოდნელად დაუწიეთ ხმას და მხოლოდ ჩურჩულით ესაუბრეთ. როდესაც ბავშვი თქვენს გასაგონად ყურადღებას მოიკრებს, მისი ტვინი თითქოს ავტომატურად მოექცევა ჰიპნოზის ქვეშ და ძილის რეჟიმზე გადაერთვება.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'ხელების დასვენება 🫂', 'მთელი დღე თქვენზე აცოცებისა და ჩახუტების მოთხოვნისგან სხეული გტკივათ. საღამოს ესტაფეტა მამას გადააბარეთ. როცა ის ბავშვს ზურგზე მოიკიდებს და ცხენობანას ეთამაშება, ბავშვს ყურადღების მოთხოვნილებაც დაუკმაყოფილდება და თქვენი ხელებიც დამსახურებულად დაისვენებს.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'დილის კონცერტი 🎤', 'მზე ჯერ ბოლომდე არც ამოსულა, ის კი საწოლზე ხტუნავს და თქვენთვის გაუგებარ ენაზე ხმამაღლა მღერის. დიახ, გეძინებათ, მაგრამ ოთახში მოფარფატე ეს სიცოცხლის ენერგია თქვენც გამოგაფხიზლებთ. უბრალოდ გაუღიმეთ მის ნამღერს.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'ხელოვნური ინტელექტი — თქვენი მხსნელი 🤖', 'დედა, მზე სად მიდის დასაძინებლად? ამ კითხვამ დაგაბნიათ? ახსნას ნუ გაართულებთ. დაუსვით ეს კითხვა Anacan AI-ს, მიუთითეთ ბავშვის ასაკი და მიღებული შესანიშნავი, ზღაპრული პასუხი, რომელსაც სამი წლის ბავშვიც ადვილად გაიგებს, მასაც მოუყევით.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'ჩუმი ცრემლები 💖', 'მთელი დღე ჭკუიდან გადაგიყვანათ. ახლა კი საწოლში ისე უმანკოდ სძინავს, რომ მის შემხედვარეს გული გიჩუყდებათ, არა? სწორედ ეს არის დედობის უდიდესი პარადოქსი. თვალიდან ჩამოგორებული ის ერთი წვეთი ცრემლი მადლიერებაა იმისთვის, რომ ის თქვენს ცხოვრებაშია.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'საიდუმლო კვების ოპერაცია 🥣', 'კვერცხი, რომელიც გუშინ უყვარდა, დღეს პირსაც არ აკარებს. მის ნებას ნუ შეებრძოლებით. ჯანსაღ რეცეპტებში გამოიყენეთ მოხერხებული წასახემსებლების იდეები, რომლებიც ცილოვან პროდუქტებს განსხვავებულ, ფერად და საინტერესო ფორმას მისცემს — და გამარჯვებული თქვენ დარჩით.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'ლოგიკის სრული კრახი 🛑', 'ყვირის, რომ წყალი წითელ ჭიქაში დაუსხათ, მაგრამ როგორც კი იქ დაუსხამთ, ტირილს იწყებს — აქ რატომ დამისხიო. აქ ლოგიკა არ არსებობს. ის უბრალოდ დაღლილია და ემოციების გამოხეთქვა სჭირდება. მშვიდად დაელოდეთ — ქარიშხალი თავისით ჩაცხრება.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'მოულოდნელად მოზღვავებული სიყვარული 🥰', 'თამაშის დროს უცებ სათამაშოს აგდებს, მორბის, კისერზე ხელებს გხვევთ და გეუბნებათ: „მიყვარხარ“. სწორედ ეს არის ის ჯადოსნური წამი, რომელიც მთელ დაღლილობასა და უძილობას აქარწყლებს. ძლიერ ჩაიხუტეთ გულში და მისი სურნელი ღრმად შეისუნთქეთ.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'მამის უცნაური ზღაპარი 📖', 'ამ საღამოს თქვენი ხმა დაიღალა. ზღაპრის წაკითხვა მამას გადააბარეთ. ის წიგნის ილუსტრაციისგან სრულიად განსხვავებულ, გამოგონილ და სასაცილო ამბავს მოჰყვება და ბავშვს გულიანად გააცინებს. თქვენ კი გვერდით მოკალათდით, ჩაი მოიმარჯვეთ და ამ სანახაობით დატკბით.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'სუპერმარკეტის ურიკის ქარიშხალი 🛒', 'მიუხედავად იმისა, რომ დიდი სუპერმარკეტის ურიკა მასზე დიდია, აუცილებლად თავად უნდა მისი ტარება. საზოგადოებრივი თავშეყრის ადგილას ტირილის თავიდან ასაცილებლად, მიეცით საშუალება, ხელები ურიკაზე ეჭიროს, თქვენ კი შეუმჩნევლად მართეთ მიმართულება.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'უკუღმა ჩაცმული თავისუფლება 👗', 'შარვალი უკუღმა ჩაიცვა და მტკიცედ ამბობს: „მე თვითონ ჩავიცვი“. ესთეტიკას ნუ მიაქცევთ ყურადღებას. მისი მზარდი თავდაჯერებულობა და დამოუკიდებლობის განცდა ბევრად უფრო მნიშვნელოვანია, ვიდრე ის, სწორად აცვია თუ არა ტანსაცმელი. იამაყეთ ამ პატარა მეამბოხით.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'ყავა ქაოსის შუაგულში ☕', 'ოთახის შუაგულში ყველა სათამაშო მიმოფანტა და თავისთვის ციხესიმაგრეს აშენებს. როგორც კი ამ არეულობას დაალაგებთ, ის კვლავ ყველაფერს მიმოფანტავს. ამიტომ შეწყვიტეთ ბრძოლა, ოთახის კუთხეში მოკალათდით, ყავა სანამ ცხელია მიირთვით და ქაოსს შორიდან მშვიდად უყურეთ.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'ჩრდილები ოთახში 🐰', 'სიბნელის შიში დაეწყო? ოთახი სრულად ჩააბნელეთ და პატარა ფანრით ჭერზე სინათლის ფიგურები და ცხოველების ჩრდილები შექმენით. სიბნელე, რომლისაც ეშინია, გართობად და ძილის წინ ერთად სიცილით სავსე პატარა თავგადასავლად აქციეთ.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'უწყვეტი ძილის იმედი 🤞', 'მას ჩაეძინა და სახლში ღრმა სიჩუმემ დაისადგურა. თქვენი ყველაზე დიდი სურვილია, ამაღამ არ გაიღვიძოს. ხმის საზომში ფონურ ხმებად არსებული ტყის ნაზი შრიალი დაბალ ხმაზე ჩართეთ, რათა მას ღრმა ძილის ფაზაში დარჩენაში დაეხმაროთ.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'ბუნების ლაბორატორია 🍂', 'სახლში ყოფნა უკვე გაწუხებთ, ბავშვი კი მოუსვენრადაა. შეამოწმეთ ამინდი, შესაბამისად ჩაიცვით და აუცილებლად გაიყვანეთ გარეთ. გამხმარი ტოტებისა და ფოთლების შეგროვების პატარა მისია მას ენერგიის დახარჯვაში დაეხმარება, თქვენ კი ოთხ კედელს დააღწევთ თავს და სუფთა ჰაერს ჩაისუნთქავთ.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'სათამაშოების დედა 🧸', 'ოთახიდან ხმა ისმის. ყურადღებით უსმენთ და აღმოაჩენთ, რომ ის თავის დათუნიას ზუსტად თქვენი ტონითა და თქვენი ფრაზებით საყვედურობს! ის თქვენი საუკეთესო ასლია. ეს შესანიშნავი შესაძლებლობაა, საკუთარ ქცევას გვერდიდან შეხედოთ.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'გაუზიარებელი საუზმე 🍳', 'თავის თეფშიდან არაფერს გინაწილებთ, მაგრამ მოდის და დაჟინებით ითხოვს, რომ თქვენი თეფშიდან კვერცხი ჭამოს. ბავშვები ყოველთვის უფრო მეტად ენდობიან მშობლების არჩევანს. ნუ შეეწინააღმდეგებით — თქვენი ლუკმა სიყვარულით გაუწოდეთ ამ პატარა ეგოისტს.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'სიის გარეშე დარჩენილი კატასტროფა 🛒', 'საკუთარ მეხსიერებას ენდეთ, სახლში დაბრუნებულმა კი აღმოაჩინეთ, რომ ბავშვისთვის ყველაზე მნიშვნელოვანი რამ — რძე — არ გიყიდიათ. თქვენი გონება ისედაც უამრავი საზრუნავითაა გადატვირთული. ამიერიდან საჭიროების გაჩენისთანავე ჩაიწერეთ ის აპლიკაციის საყიდლების სიაში — ეს ჩვევად აქციეთ და ზედმეტ სტრესს თავიდან აიცილებთ.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'ოკეანე აბაზანაში 🌊', 'აბაზანაში ბანაობა უკვე სისუფთავისთვის კი არა, ტალღების შესაქმნელ თამაშად იქცა. მიეცით წყალს საშუალება, ირგვლივ იშხეფოს. წყლის ეს მაგიური ეფექტი მთელი დღის განმავლობაში დაგროვილ ჯიუტ, უარყოფით ენერგიას ჩამორეცხავს, კანალიზაციაში გააყოლებს და ბავშვს უფრო ღრმად დაძინებაში დაეხმარება.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'თქვენ სრულყოფილი ხართ 🛑', 'სოციალურ ქსელებში ყოველდღე ხედავთ დედებს, რომლებიც ბავშვებთან ერთად ხელოვნების ნიმუშებს ქმნიან და რომელთა სახლებიც სისუფთავისგან ბრწყინავს, და ამის გამო საკუთარ თავს ადანაშაულებთ? ნუ ენდობით ამ ფილტრებს. თქვენი არეული, ხმაურიანი და ნამდვილი სახლი თქვენი შვილისთვის ყველაზე თბილი და სიყვარულით სავსე, სრულყოფილი ბუდეა.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'პატარა ადვოკატის არგუმენტი 🗣️', '„შოკოლადი უნდა ვჭამო, რადგან უკვე დიდი ვარ.“ ის უკვე მიზეზშედეგობრივ კავშირებს ამყარებს და ცდილობს, დაგითანხმოთ და მოგევაჭროთ! მისი მეტყველება შესანიშნავად ვითარდება. შეაქეთ, მაგრამ ამავდროულად კეთილად დაიცავით თქვენი საზღვრები და წესები.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'თერაპია სიჩუმით 🤫', 'როგორც იქნა, დაიძინა! ჩართეთ ხმის საზომი ხელსაწყო და ეკრანზე დააკვირდით ციფრებს, რომლებიც 0 დეციბელამდე ეცემა. იგრძენით, როგორ ისვენებს თქვენი დაღლილი გონება და როგორ გეფერებათ ეს ვიზუალური სიჩუმე.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'სამზარეულოს ინციდენტი 🧑‍🍳', 'სანამ ცომს აბრტყელებთ, ბავშვი მოდის, ფქვილში ხელს ყოფს და ყველაფერს ათეთრებს. დიახ, სამზარეულო აირია და საქმეც მოგემატათ. მაგრამ მისი სერიოზული, საქმიანი გამომეტყველება მაშინვე აღბეჭდეთ ბავშვის ფოტოსესიით. არეულობა გაქრება, ეს მოგონება კი დარჩება.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'იამაყეთ საკუთარი თავით 🚀', 'როცა უკან იხედებით, ხედავთ, როგორი ძლიერი პიროვნება ჩამოყალიბდა მისგან. დღეს დიდხანს უყურეთ და იამაყეთ საკუთარი თავით, რადგან ასეთი მშვენიერი ადამიანი გაზარდეთ.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'მადლობა გუნდურობისთვის 🥂', 'კიდევ ერთი რთული და ქარიშხლიანი დღე მოიტოვეთ უკან. როცა ბავშვი დაიძინებს, პარტნიორთან ერთად ჩაი დაისხით და უთხარით: „დღეს ძალიან დამეხმარე, მადლობა.“ მშობლობა მარტო გასავლელი გზა არ არის — ჯანსაღ გუნდთან ერთად ის უფრო მშვენიერი ხდება.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'ემპათიის ნიშნები 🧸', 'როცა სათამაშო უვარდება, ეფერება და ეუბნება: „არ იტირო“? ესე იგი, მას ემპათიის უნარი უვითარდება! ეს საყვარელი ეტაპი აუცილებლად მონიშნეთ განვითარების ტრეკერში.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'უკუღმა ჩაცმული ტანსაცმელი 👗', 'აუცილებლად უნდა, რომ მაისური უკუღმა ჩაიცვას? ნუ შეეწინააღმდეგებით. მიეცით საშუალება, ერთი დღე სახლში ასე იაროს — ნუ გატეხთ მის ნებას.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ პარტნიორს პირისპირ მიუჯექით და ერთმანეთს გულწრფელად ესაუბრეთ. ურთიერთმხარდაჭერა ტვირთს მართლაც შუაზე ყოფს.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'საბნის ინჟინერია 🛏️', 'აი, უკვე უნდა ჩაეძინოს და უცებ ტირილს იწყებს: საბნის კუთხე მოიკეცა! საბნის მილიმეტრული სისწორე მისთვის სასიცოცხლოდ მნიშვნელოვანია. ღრმად ჩაისუნთქეთ, საბანი უთოსავით გაასწორეთ და ამ სასაცილო პრეტენზიულობაზე უბრალოდ გაიღიმეთ.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'საეჭვო სიჩუმე 🤫', 'სახლში მოულოდნელად სრული სიჩუმე ჩამოვარდა. ხმის საზომი 0 დეციბელს აჩვენებს. თუ ბავშვი ჩუმადაა, ესე იგი, სადღაც დიდი აღმოჩენა კეთდება. ოთახში ფსიქოლოგიურად მომზადებული შედით — შეიძლება კედელზე ნახატები ან დაჭრილი ქაღალდები დაგხვდეთ.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'კამათს ნუ დაიწყებთ. 💼', '„მე ამ ფაფას არ შევჭამ, რადგან ყვითელია!“ იმდენად უნაკლო და დამაჯერებელი აბსურდული ლოგიკა აქვს, რომ კინაღამ თავს დამნაშავედ იგრძნობთ. კამათს ნუ დაიწყებთ. პატარა ადვოკატი ასე დაიყოლიეთ: „მართალი ხარ, ყვითელია. რას იტყვი, შიგნით წითელი კენკრა რომ ჩავყაროთ?“'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'სახლის მთავარი ექიმი 🩺', 'იღებს სათამაშო სტეტოსკოპს, მკერდზე გადებთ, წარბებს იკრავს და გეუბნებათ: „ისუნთქეთ“. თქვენ მორჩილი პაციენტი ხართ. ეს როლური თამაში შესაძლებლობად აქციეთ: თვალები დახუჭეთ და 3-წუთიანი გასინჯვის განმავლობაში უბრალოდ იატაკზე იწექით და ზურგი დაასვენეთ.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'მამის ვოკალური შესაძლებლობები 📖', 'დღეს ხმა დაგეღალათ და ყელი გაგიშრათ. საღამოს ზღაპრის მოყოლა მამას გადააბარეთ. ის წიგნის ილუსტრაციისგან სრულიად განსხვავებულ, სასაცილო და გამოგონილ ამბავს მოჰყვება და ბავშვს გულიანად გააცინებს. თქვენ კი ამ სასიამოვნო სანახაობას გვერდიდან, ცხელი ჩაის თანხლებით უყურეთ.'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', '„დედა, შემომხედე!“ პერიოდი 👀', 'დივნიდან ხტება, ერთსა და იმავე მოძრაობას ზუსტად 50-ჯერ იმეორებს და ყოველ ჯერზე გეუბნებათ: „დედა, შემომხედე!“ თვალი ტელეფონს მოსწყვიტეთ. ის თვითონ მოძრაობის გამო კი არა, თქვენს თვალებში მოწონების ნაპერწკლის დასანახად ხტება. 5 წუთის განმავლობაში მთელი ყურადღება დაუთმეთ, რათა ბოლომდე დატკბეს.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'მუსიკალური ჰიპნოზი 🎶', 'საღამოობით უმიზეზო ქარიშხლები და ტირილის შეტევები დაიწყო. გამორთეთ ტელევიზორი, ჩააქრეთ მკვეთრი განათება და ოთახში ძალიან ხმადაბლა ჩართეთ კლასიკური მუსიკა. მუსიკის ღრმა სიხშირეები ატმოსფეროს ჯადოსნურად შეცვლის და ოთახში სიმშვიდეს შემოიტანს.'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'მულტფილმის სცენარისტი 📺', 'ნანახ მულტფილმს იმდენად განსხვავებული სიუჟეტითა და დამაჯერებლად გიყვებათ, რომ ლამის დაიჯერებთ. შესანიშნავი წარმოსახვა უყალიბდება.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'დედის გადატვირთვის ღილაკი 🚪', 'ხმაური თავში გიბურღავთ და გინდათ, ყველას უყვიროთ. გახსენით განწყობის დღიური. იქ თავისუფლად აღწერეთ მთელი თქვენი გამოფიტულობა. ეს ხანმოკლე ციფრული თერაპია ძალების აღდგენაში დაგეხმარებათ.'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'მამას წყლის ბრძოლა 🛁', 'დღეს საღამოს აბაზანის რიტუალი მთლიანად მამას პასუხისმგებლობაა. მიეცით მათ წყლის ირგვლივ შხეფების საშუალება, თქვენ კი კარს მიღმა სრული სიჩუმით დატკბით.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'გარდერობის ამბოხი 🥽', 'სახლში საცურაო სათვალითა და ზამთრის ქუდით სიარული სურს. დაჟინებით მოითხოვს და არ იხდის. დაივიწყეთ საზოგადოებრივი ნორმები. მის შემოქმედებითობასა და არჩევანის თავისუფლებას რომ ხელი არ შეუშალოთ, მიეცით საშუალება, დღე ამ უჩვეულო, სასაცილო სამოსით გაატაროს.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'სიურპრიზი საყიდლების ურიკაში 🛒', 'სალაროსთან მისვლისას საყიდლების ურიკაში თქვენ მიერ არჩეული ნივთების გარდა 3 სხვადასხვა შოკოლადი და 1 უცნაური ფორმის საპონი აღმოაჩინეთ. სწრაფი მანევრით დააბრუნეთ ეს ნივთები. არაფერი რომ დაგავიწყდეთ და მიზანს არ გადაუხვიოთ, თვალი ყოველთვის საყიდლების სიაზე გეჭიროთ.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'სმენის აპარატი გამოირთო 🙉', 'ეუბნებით, სათამაშოები აალაგოს ან ხელები დაიბანოს, მაგრამ რეაქცია ნულოვანია. 3 წლის ასაკში თავის მოყრუება ერთ-ერთი საყვარელი ჰობია. ყვირილის ნაცვლად მასთან მიდით და ყურში ძალიან ჩუმად ჩასჩურჩულეთ. ხმის ტონის მოულოდნელი ცვლილება მის ყურადღებას მაშინვე მიიპყრობს.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'აბაზანის შანტაჟი 🛀', 'აბაზანაში შესვლისას ტიროდა, ახლა კი წყლიდან ამოსვლა რომ არ მოუწიოს, მთელი ხმით კივის. წყლის მაგნიტურმა ძალამ თითქოს მოაჯადოვა. 3 წუთით ადრე გააფრთხილეთ და ტაიმერი დააყენეთ. რიტუალი „ზარი რომ დარეკავს, თამაში მთავრდება“ ყოველთვის ამართლებს.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'საკვების დიზაინერი 🥦', 'თეფშზე საკვებს ფერისა და ფორმის მიხედვით ახარისხებს, მწვანე ნაჭრებს კი მაგიდის კიდისკენ სწევს. ჩართეთ კვების დაგეგმვის რეჟიმი. აღმოაჩინეთ, როგორ აქციოთ ბოსტნეული შეუმჩნეველ პიურედ და დამალოთ კატლეტებსა თუ სოუსებში — ასე ამ თამაშში გამარჯვებას შეძლებთ.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'ცეკვა სიბნელესთან 🌙', 'იმისთვის, რომ ბავშვს უფრო სწრაფად ჩაეძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი (ძილის ჰორმონი) სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა და ჩაძინებას უწყობს ხელს.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'ქუჩაში ნაპოვნი განძი 🍁', 'მიწაზე ნაპოვნ ჭუჭყიან ბოთლის თავსახურს ან უჩვეულო ფერის ქვას სიხარულით გაჩვენებთ, თითქოს ოქრო იპოვა. ნაცვლად იმისა, რომ უთხრათ: „გადააგდე, ჭუჭყიანია“, უთხარით: „რა უცნაური ფერი აქვს, მოდი, სახლში გავრეცხოთ“ და მისი აღმოჩენებისადმი ინტერესი დააფასეთ.'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'ფილოსოფიის საათი დაბრუნდა 🤔', 'რატომ ქრის ქარი? რატომ ცვივა ფოთლები? დილიდანვე ღრმა ფილოსოფიური კითხვები თავს გახვევთ. ახსნას ნუ გაართულებთ — ბუნება მისთვის გასაგები, ზღაპრული ენით აუხსენით. თქვენი ხმის ტონი მისთვის სამყაროს შეცნობის ყველაზე საიმედო გზაა.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'კონცერტი სამზარეულოში 🥄', 'ქვაბებსა და ხის კოვზებს იღებს და შუა სამზარეულოში კონცერტს მართავს. შეიძლება თავი აგტკივდეთ, მაგრამ ამ დროს მისი რიტმის შეგრძნება და შემოქმედებითობა ვითარდება. მაშინვე ნუ ჩაერევით — რამდენიმე წუთით მიეცით საშუალება, ამ გიჟურმა ენერგიამ ხმის ტალღებად მთელი ოთახი აავსოს.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'ნუგეში საზოგადოებაში 💬', 'ფიქრი — „რატომ არის ჩემი ბავშვი ასეთი ჯიუტი?“ — მოსვენებას არ გაძლევთ. შეუერთდით Anacan-ის საზოგადოებას. როცა სხვა დედების ოჯახებში მომხდარ მსგავს აბსურდულ კრიზისებზე წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ და სრულიად ნორმალურ, ჯანმრთელ ბავშვს ზრდით.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'მისი სუნთქვის სითბო 💖', 'მთელი დღე ჭკუიდან გადაგიყვანათ და ყველაფერზე ტიროდა. ახლა კი საწოლში მკერდზე გეკვრით და ოთახს მისი რიტმული, თბილი სუნთქვა ავსებს. სწორედ ეს არის დედობის უდიდესი ჯილდო. გულში ჩაიკარით და იგრძენით, როგორ ქრება მთელი დაღლილობა მის ყოველ ამოსუნთქვასთან ერთად.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'საწოლში მოგზაურობა 🛏️', 'ღამით სწორ პოზაში იძინებს, დილით კი ფეხები ბალიშზე აქვს, თავი — საწოლის სრულიად საპირისპირო კუთხეში. ძილშიც კი სამყაროს იკვლევს! სანამ გააღვიძებთ, სიცილით უყურეთ მის ამ სახალისო მოგზაურობას საწოლში.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'ფილოსოფიური ძილის გადადება 🦉', 'როგორც კი საწოლში წვება, ისეთ ღრმა კითხვებს სვამს, როგორიცაა: „დედა, ვარსკვლავები რატომ არ ცვივა?“ მიზანი მეცნიერების შესწავლა კი არა, ძილის გადადებაა. კითხვებს მოკლე, გამოგონილი და საყვარელი პასუხები გაეცით, შემდეგ კი ჭკვიანი ზღაპრებით ოთახში ძილის სიჩუმე სწრაფად დაამყარეთ.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'კოსტიუმიანი გმირი 🦸‍♂️', 'სახლში აუცილებლად ზამთრის ჩექმებით ან სუპერგმირის ნიღბით სიარული სურს? დაივიწყეთ საზოგადოებრივი ნორმები და ესთეტიკა. ასე ის საკუთარ პიროვნებას აღმოაჩენს. მიეცით საშუალება, ოთახში ჩექმებით გმირად იგრძნოს თავი.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'დინოზავრის კბილები 🦖', 'კატეგორიულად უარს ამბობს კბილების გახეხვაზე და ჯაგრისს აგდებს. ეს თამაშად აქციეთ! ხელში სათადარიგო ჯაგრისი მიეცით და უთხარით: „მოდი, ჯერ შენს სათამაშო დინოზავრს გავუხეხოთ კბილები“. სანამ ის დინოზავრს უხეხავს კბილებს, თქვენც ეშმაკურად გაუხეხეთ მას კბილები.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'დამოუკიდებლობის ლაქები 🥣', 'აუცილებლად ჩანგლით სურს იოგურტის ჭამა და ირგვლივ ყველაფერს სვრის. ნუ ჩაერევით და ნუ წაართმევთ. დაღვრილი საკვები გაიწმინდება, მაგრამ მისი „მე თვითონ ვაკეთებ“ განცდის აღდგენა რთულია. გაუკეთეთ სილიკონის წინსაფარი და ამ სანახაობას მოთმინებით უყურეთ.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', 'დედის 10 წუთი 🚪', 'ხმაურმა გონება დაგიღალათ. გახსენით განწყობის დღიური, ეკრანზე თავისუფლად გადმოიტანეთ ყველაფერი, რამაც დღეს ჭკუიდან გადაგიყვანათ, და თქვენს შინაგან გადატვირთვის ღილაკს დააჭირეთ.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'ნაგვის ყუთის ხიბლი 📦', 'ამდენი ძვირადღირებული, კაშკაშა სათამაშოს მიუხედავად, ის ცარიელი პლასტმასის წყლის ბოთლით ან მუყაოს ყუთით საათობით თამაშობს. ბავშვის ფანტაზიას მზა სცენარებზე მეტად შემოქმედებისთვის თავისუფალი, უბრალო ნივთები მოსწონს. დააკვირდით და ისწავლეთ.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'სიზმრის რევოლუცია ☁️', 'დილით გაღვიძებისთანავე წარბშეკრული გებუტებათ. მიზეზი? სიზმარში მისთვის სასურველი სათამაშო არ მიგიციათ! ბავშვის ტვინი ჯერ კიდევ ვერ ასხვავებს სრულად სიზმარსა და რეალობას. მთელი სერიოზულობით მოუბოდიშეთ, გულში კი ამ აბსურდულ სიტუაციაზე გაიღიმეთ.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'უხმო მზერა 🥂', 'ბავშვმა ბოლოს და ბოლოს დაიძინა. თქვენ და თქვენი პარტნიორი დივანზე გვერდიგვერდ სხედხართ და საუბრის ძალაც კი აღარ გაქვთ. უბრალოდ ჩუმად უყურებთ ერთმანეთს და იღიმით. დიახ, ეს უხმო მზერა ყველაზე ლამაზი გზაა იმის სათქმელად, რომ ამ ქაოსს ერთად ვუმკლავდებით.'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'თეატრი კედელზე 🐰', 'სიბნელის შიშს იმიზეზებს და საწოლიდან გარბის. ოთახში ყველა შუქი ჩააქრეთ, ფანარი აანთეთ და ხელებით კედელზე ჩიტებისა და ძაღლების ჩრდილები შექმენით. სიბნელე, რომლისაც ეშინოდა, მისთვის წამებში მსოფლიოში ყველაზე უსაფრთხო თეატრად გადაიქცევა.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'პარკიდან წამოსვლის ტაქტიკა 🌳', 'პარკიდან წამოსვლის დროა და ტირილის შეტევები იწყება. ნუ ეცდებით მის ძალით წამოყვანას. უთხარით: „ვნახოთ, მანქანამდე ვინ უფრო სწრაფად მიირბენს?“ — და შეჯიბრი მოაწყვეთ. ბავშვები შეჯიბრებასა და გამარჯვებაზე უარს არასდროს ამბობენ.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'უხილავი სტუმარი 👻', 'საუზმის დროს მოითხოვს, რომ მისი წარმოსახვითი მეგობრისთვისაც დადოთ თეფში მაგიდაზე. ეს ფსიქოლოგიური სიცარიელე კი არა, გონებრივი განვითარების ნახტომია. დადეთ თეფში და თქვენს სტუმარს წარმოსახვითი ჩაიც დაუსხით, რათა ამ შესანიშნავი თეატრის ნაწილი გახდეთ.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'გუნდური მუშაობის შედეგი 🥂', 'კიდევ ერთი რთული და ქარიშხლიანი დღე მოიტოვეთ უკან. მას შემდეგ, რაც ბავშვი დაიძინებს, პარტნიორთან ერთად ჩაი დაისხით და ერთმანეთს მადლობა გადაუხადეთ სიტყვებით: „დღეს ამ ქაოსსაც გადავურჩით — შესანიშნავი გუნდი ვართ“. მშობლობა მარტო გასავლელი გზა არ არის — მხარდაჭერით ის უფრო მშვენიერი ხდება.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'უკუღმა ჩაცმული ფეხსაცმელი 👟', 'ფეხსაცმელი უკუღმა ჩაიცვა, მაგრამ ისეთი ამაყი დადის, თითქოს მთელი მსოფლიო დაიპყრო. თუ ჩაერევით და გასწორებას ეცდებით, ყველაფერს გააფუჭებთ. მისი თავდაჯერებულობა და დამოუკიდებლობა ესთეტიკაზე მნიშვნელოვანია. მიეცით ამ პატარა მეამბოხეს საშუალება, ამაყად იაროს.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'დივერსია სამზარეულოში 🧑‍🍳', 'სანამ ცომს აბრტყელებთ, მოდის, ფქვილში ხელს ჰყოფს და ირგვლივ ყველაფერს ათეთრებს. დიახ, სამზარეულო აირია. მაგრამ მისი სერიოზული, საქმიანი გამომეტყველება ბავშვის ფოტოსესიით მაშინვე აღბეჭდეთ. დალაგებას ყოველთვის მოასწრებთ, ეს სახალისო კადრი კი სამუდამოდ დაგრჩებათ.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'ცოცხალი სარკე 🦜', 'სათამაშოს ზუსტად იმ მიმიკით ტუქსავს, რომელსაც თქვენ გაბრაზებისას იყენებთ. დაუყოვნებლივ შეხედეთ საკუთარ თავს გვერდიდან! ის იმას იმეორებს, რასაც ხედავს. ეს სახალისო, თუმცა დამაფიქრებელი სანახაობა შესანიშნავი სარკეა, რომელიც საკუთარ ქცევაზე მეტი ყურადღების გამახვილებაში დაგეხმარებათ.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'მე ჭკვიან ზღაპარში 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით და მათი კითხვით დაიღალეთ. გახსენით ჭკვიანი ზღაპრები. მთავარ გმირად თქვენი ბავშვი აქციეთ, ფონად კი ტყის დამამშვიდებელი ხმები შეარჩიეთ და შექმენით უჩვეულო, ძალისხმევის გარეშე ჩასატარებელი ძილის სეანსი.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'სუფთა ჰაერი ⛅', 'შეამოწმეთ ამინდი, შეურჩიეთ შესაბამისი ტანსაცმელი და აუცილებლად გაიყვანეთ გარეთ. გამხმარი ტოტებისა და ქვების შეგროვების მარტივი მისია დაეხმარება მას ენერგიის დახარჯვაში, თქვენ კი ოთხ კედელს დააღწევთ თავს და ღრმად ჩაისუნთქავთ.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'სიჩუმის დეციბელი 🤫', 'როგორც იქნა, დაიძინა! ოთახის დასალაგებლად ნუ გაიქცევით. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელის მაჩვენებელს შეხედეთ. სახლში გამეფებული სრული სიჩუმის ეს ვიზუალური დასტური თქვენს დაღლილ ტვინზე საუკეთესო მასაჟივით იმოქმედებს.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'ფილოსოფიის პროფესორი 🧐', 'ის აღარ გეკითხებათ: „დედა, მზე იქ რატომ არის?“ — ახლა უბრალოდ აინტერესებს: „მზე რატომ არის?“ მისი კითხვები სულ უფრო აბსტრაქტული ხდება. ნუ დაიღლით თავს საათობით მეცნიერული ახსნა-განმარტებებით. მოკლე, ზღაპრული და თბილი პასუხი, მაგალითად, „იმიტომ, რომ ჩვენი გათბობა უყვარს“, მას სრულიად დააკმაყოფილებს.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'ფეხები შვებულებაშია 🚶‍♂️', 'შუა ქუჩაში მოულოდნელად ჯდება და ამბობს: „ფეხები მომტყდა, ხელში ამიყვანე“. არა, არ დაღლილა — უბრალოდ გცდით. შანტაჟს ნუ დანებდებით. უთხარით: „ვნახოთ, მანქანამდე პინგვინივით როგორ მივალთ?“ და თამაშში აიყოლიეთ.'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'ფერადი დიეტა 🥕', 'დღეს გადაწყვიტა, მხოლოდ ნარინჯისფერი საკვები ჭამოს და ყველაფერ სხვაზე უარს ამბობს. ბავშვის ლოგიკა ისევ მოქმედებაშია! აღმოაჩინეთ, როგორ შენიღბოთ ბოსტნეული ჯანსაღ კერძებში. გოგრისა და სტაფილოს პიურით მომზადებული განსხვავებული რეცეპტებით ეს სიჯიუტე დაძლიეთ.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'დილის სოლისტი 🎤', 'ჯერ ისევ უთენია და სანამ თვალების გახელას ძლივს ახერხებთ, ის ოთახის შუაგულში სათამაშოთი ხელში კონცერტს მართავს. ნუ ეცდებით მის გაჩუმებას. ბავშვების ეს გიჟური, დაუშრეტელი სასიცოცხლო ენერგია სახლს სინამდვილეში სიხარულითა და კეთილდღეობით ავსებს. ღიმილით უყურეთ.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'სამკურნალო შეხება 💆‍♂️', 'საწოლში ვერაფრით მშვიდდება. ზღაპარი და მუსიკა გვერდზე გადადეთ. პატარა ფეხებზე ან ზურგზე ძალიან მსუბუქი, ნაზი მასაჟი გაუკეთეთ. ფიზიკური შეხება როგორც მის, ისე თქვენს ორგანიზმში კორტიზოლის (სტრესის ჰორმონის) დონეს მყისიერად შეამცირებს და ძილს მოგგვრით.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'უხილავი ნამცეცები 🧹', 'პატარა ცოცხით ხელში, სახეზე ძალიან სერიოზული გამომეტყველებით ხალიჩიდან უხილავ მტვერს წმენდს. ის უბრალოდ თქვენ გბაძავთ. აღბეჭდეთ მისი ეს პასუხისმგებლობით სავსე მომენტი ბავშვის ფოტოსესიაში — სახლის ყველაზე პატარა და საყვარელი დამლაგებელი საქმეს შეუდგა.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'ხმის საზომით თერაპია 🤫', 'სახლში დატრიალებული ის პატარა გიჟური ქარიშხალი, როგორც იქნა, საწოლს დანებდა. ოთახში ჭურჭლის სარეცხი მანქანის ხმის გარდა არაფერი ისმის. ჩართეთ ხმის საზომი, შეხედეთ ეკრანზე გამოსახულ დეციბელების მინიმალურ მაჩვენებელს და თვალები დახუჭეთ. ეს ვიზუალური სიჩუმე თქვენი ტვინისთვის საუკეთესო მასაჟია.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'კატასავით გაღვიძება 🐾', 'ამ დილით ის ადამიანი არ არის. ოთხზე დადის, ფეხზე გეხახუნებათ და მხოლოდ კნავილით ურთიერთობს. ეს წარმოსახვის ყველაზე საყვარელი და უმაღლესი გამოვლინებაა. წესების დაწესების ნაცვლად, თქვენც გაუწოდეთ რძით სავსე წარმოსახვითი ჯამი და ამ თამაშით დატკბით.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'გულახდილი საუბარი საზოგადოებაში 💬', 'დღეს ყველაფერზე ყვიროდით და თავს მსოფლიოში ყველაზე მოუთმენელ დედად გრძნობთ? გთხოვთ, გახსოვდეთ, რომ მარტო არ ხართ. შედით Anacan-ის საზოგადოებაში, წაიკითხეთ, რომ სხვა დედებიც დღეს თქვენნაირად გამოიფიტნენ, და სინდისის ქენჯნა დაიცხრეთ.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'მამის თავგადასავლებით სავსე ზღაპარი 📖', 'ამ საღამოს ოთახში თქვენი ხმა არ უნდა ისმოდეს. ზღაპრების წიგნი მამას მიეცით და ნება დართეთ, ამბავი განზრახ უკუღმა, სასაცილოდ და აბსურდულად მოჰყვეს. თქვენ კი გვერდიდან უყურეთ, როგორ სიამოვნებს ბავშვს მამის შესწორება და როგორ გულიანად იცინის მასთან ერთად.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'ავანგარდისტი არქიტექტორი 🥞', 'საუზმეზე ბლინებს ერთმანეთზე აწყობს და კოშკს აგებს, შუაში ხვრელს აკეთებს და თითს ჰყოფს. საკვებით თამაში მისთვის ახალი საინჟინრო პროექტია. ყურადღება არ მიაქციოთ დასვრილ მაგიდას — ასე ის საკვების ტექსტურას შეისწავლის.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'წარმოსახვითი მაღაზია 🍅', 'ოთახის ერთ კუთხეში სათამაშოებს აგროვებს და წარმოსახვით პომიდორს წარმოსახვით ფულზე გყიდით. ამ სავაჭრო თამაშს სრული სერიოზულობით მოეკიდეთ. იყიდეთ წარმოსახვითი პომიდორი და თავი ისე მოაჩვენეთ, თითქოს მადიანად მიირთმევთ. როლური თამაშები მისი სოციალური ინტელექტისა და მათემატიკური აზროვნების უმნიშვნელოვანესი საფუძველია.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'დედის საიდუმლო შოკოლადი 🍫', 'დედიკო, რომელიც სამზარეულოს კარადის უკან ბავშვისგან მალულად შოკოლადის ნაჭერს მიირთმევთ, ეს გლუკოზა თქვენი ბუნებრივი უფლებაა. მთელი დღე ამ ენერგიისა და დაუსრულებელი „რატომების“ გასაძლებად თქვენც აუცილებლად უნდა დაიმუხტოთ. ღრმად ჩაისუნთქეთ და ყოველი ლუკმით დატკბით.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'ღამის შიში 😭', 'შუაღამისას თვალდახუჭული და ტირილით იღვიძებს, თუმცა არავის ხმა არ ესმის. ტირილზე დაკვირვებით დარწმუნდით, რა ხდება; თუ ეს ღამის ტერორია, ნუ შეანჯღრევთ და ნუ ეცდებით მის გაღვიძებას. უბრალოდ ჩუმად დარჩით მის გვერდით და აგრძნობინეთ, რომ უსაფრთხოდაა — ეს გადაივლის.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'ყინულივით ცივი ლოგიკა 🥶', 'მაცივარს აღებს, ყინულის ფორმას ითხოვს და ხელების გაყინვის მიუხედავად, ხელს არ უშვებს. ის სითბოსა და სიცივის ცნებებს საკუთარი სხეულით ამოწმებს. ერთ ჭურჭელში თბილი, მეორეში კი ყინულიანი წყალი ჩაასხით და ეს აღმოჩენა პატარა სამეცნიერო ექსპერიმენტად აქციეთ — მისი სიჯიუტეც მაშინვე გაქრება.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'ბუნებაში გასვლა აუცილებელია ⛅', 'ოთხ კედელს შორის მისი ენერგია აგრესიად გარდაიქმნება და ყოველ წინადადებას „არათი“ იწყებს. ამინდისა და ჩაცმულობის მიუხედავად, სათანადოდ მოემზადეთ და აუცილებლად გაიყვანეთ გარეთ. მიწასთან შეხება მის ნერვულ სისტემას მაშინვე განტვირთავს.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'ღამის სანათი 🌙', 'საძინებელში შუქის ჩაქრობისას შფოთავს? ოთახის ერთ კუთხეში პატარა, თბილი ფერის (ნარინჯისფერი ან წითელი) ღამის სანათი დადგით. ოთახის დანარჩენი ნაწილი კი მელატონინის გამოყოფისა და ღრმა ძილისთვის სრულიად ბნელი უნდა დარჩეს.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'ციფრული სია — თქვენი მხსნელი 🛒', 'მაღაზიის შუაგულში დგახართ და ფიქრობთ: „აქ რის საყიდლად მოვედი?“ დედის გონება ისედაც ათას რამეზეა გადართული. მიეჩვიეთ, საჭირო ნივთი გაგახსენდებათ თუ არა, მაშინვე აპლიკაციის საყიდლების სიაში ჩაწეროთ — ასე ტვირთს შეიმსუბუქებთ.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', '„მეც დაგეხმარები!“ — პროვოკაცია 🧽', 'როცა ჭურჭელს რეცხავთ, აუცილებლად უნდა გვერდით სკამი მოიდგას და წყლით ითამაშოს? სინამდვილეში დახმარება კი არ უნდა, არამედ სურს, მოვლენების ეპიცენტრში იყოს. მიეცით პატარა პლასტმასის ჯამი და ღრუბელი. სამზარეულო წყლით დაიტბორება, სამაგიეროდ მისი თვითშეფასება საგრძნობლად გაიზრდება.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'მუსიკის ჯადოსნური სიხშირე 🎶', 'სცადეთ, საღამოობით უმიზეზოდ ატეხილი ქარიშხალი და ყვირილი მშვიდი კლასიკური მუსიკით შეაჩეროთ. ხშირად ეს მარტივი, მაგრამ ეფექტური ხერხი ოთახში დაძაბულ ატმოსფეროს ჯადოსნურად ცვლის და ბავშვს სიმშვიდეში ახვევს.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'გარდერობის ინჟინერი 👗', 'დღეს გარეთ სხვადასხვა წინდითა და უკუღმა ჩაცმული მაისურით გასვლა უნდა. დაივიწყეთ საზოგადოების წარმოდგენები იმის შესახებ, თუ რა რას უნდა შეესაბამებოდეს. საკუთარი გადაწყვეტილების მიღებისა და დაცვის თავისუფლება ფერების შეხამებაზე ბევრად მნიშვნელოვანი ცხოვრებისეული გაკვეთილია. მიეცით ამის უფლება.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'ხელოვნური ინტელექტი და სიმშვიდე 🤖', 'სამ-ნახევარი წლის ასაკის მოახლოებასთან ერთად ბავშვის ემოციების მკვეთრმა ცვალებადობამ შეგაშინათ? დახურეთ ინტერნეტში ნაპოვნი შემაშინებელი და ტრავმული ფორუმები. Anacan AI-სგან მიიღეთ ამ ასაკობრივი კრიზისების შესახებ მეცნიერულად და ფსიქოლოგიურად დასაბუთებული, დამამშვიდებელი პასუხი.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'სცენარი თავად დაწეროს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ და ოთახშიც მოსაწყენი განწყობაა. გახსენით ჭკვიანი ზღაპრები და ამ საღამოს სიუჟეტის წარმართვა მას მიანდეთ. ჰკითხეთ: „ახლა სად გაფრინდეს მფრინავი მანქანა?“ მიეცით საშუალება, წარმოსახვითი სამყაროს დაპყრობისას ჩაეძინოს.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'ჩურჩულის ჰიპნოზი 🤫', 'საწოლში წევს, ფეხებს ჰაერში იქნევს და დაძინებას საერთოდ არ აპირებს. ყვირილის ნაცვლად, მოულოდნელად დაუწიეთ ხმას და მხოლოდ ჩურჩულით ელაპარაკეთ. როცა ბავშვი თქვენ გასაგონად ყურადღებას მოიკრებს, მისი ტვინი ავტომატურად დამშვიდდება და ძილის რეჟიმზე გადაერთვება.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'Offline წუთები დედისთვის 🛋️', 'სანამ ის მულტფილმს უყურებს ან სათამაშოებითაა გართული, თქვენ ჭურჭლის სარეცხი მანქანის დაცლას ან სარეცხის გაფენას ჩქარობთ? შეჩერდით! ეს 10 წუთი უბრალოდ დივანზე წამოწოლას, ჭერის ყურებასა და არაფერზე ფიქრს დაუთმეთ. თქვენ რობოტი არ ხართ.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'დაასრულეთ დაუმთავრებელი წინადადებები 🗣️', 'როცა სიტყვა ავიწყდება, ხელებით განიშნებთ, წარბებს კრავს და ელოდება, რომ თქვენ გამოიცნობთ. მისი ლექსიკური მარაგი იზრდება, უბრალოდ ტვინი ენაზე სწრაფად მუშაობს. როცა მოთმინებით დაუსრულებთ წინადადებას, დააკვირდით მის სახეზე აღბეჭდილ შვებას: „ჰო, ზუსტად ამის თქმა მინდოდა“.'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'საკვების დიზაინერი 🥦', 'თეფშზე საჭმელს ფერისა და ფორმის მიხედვით ახარისხებს, მწვანე ნაჭრებს კი გვერდზე სწევს. გაეცანით ჯანსაღ რეცეპტებს. აღმოაჩინეთ, როგორ აქციოთ ბოსტნეული შეუმჩნეველ პიურედ და გემრიელ სოუსებში დამალოთ — ასე ამ თამაშში ჩუმად გაიმარჯვებთ.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'ცხენობანა მამის ზურგზე 🐴', 'ენერგია ბოლომდე ვერ დახარჯა და დაძინებას ეწინააღმდეგება. დასახმარებლად მამას უხმეთ. როცა ის ბავშვს ზურგზე შეისვამს და ცხენივით გააჭენებს, ოთახი სიცილით ივსება, დაგროვილი ფიზიკური დაძაბულობა და უსასრულო ენერგია კი ოფლის ღვრასთან ერთად წამებში ქრება.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'საშიში სიტყვები 🤐', 'ქუჩაში ან ტელევიზორში გაგონილ ცუდ სიტყვას სიცილით გიმეორებთ და დიდი ინტერესით ელოდება თქვენს რეაქციას. თქვენი ყველაზე ძლიერი იარაღი რეაქციის არქონაა. ნუ გაიცინებთ, ნუ გაბრაზდებით — უბრალოდ ყურადღება არ მიაქციოთ. ამ სიტყვას მალე დაივიწყებს.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'ოკეანე აბაზანაში 🌊', 'აბაზანაში ბანაობა უკვე სისუფთავეზე ზრუნვა კი არა, ტალღების შექმნის თამაშია. მიეცით საშუალება, წყალი ირგვლივ აშხეფოს და სააბაზანო დაასველოს. წყლის ეს მაგიური ეფექტი მთელი დღის განმავლობაში მასში დაგროვილ ჯიუტ, უარყოფით ენერგიას ჩამორეცხავს და კანალიზაციაში გაატანს.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'დახურული კარის საიდუმლოებები 🚪', 'თავის ოთახში შედის, კარს იკეტავს და მარტო დარჩენა სურს? მას პირადი სივრცის აღქმა და ინდივიდუალურობა უყალიბდება. უსაფრთხოების ზომები მიიღეთ და პირადი სივრცის ეს მცირე უფლება მიეცით. ის იზრდება.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'აღიარება განწყობის დღიურში 📝', 'აიღეთ ტელეფონი. სოციალურ ქსელებში სხვების იდეალური ცხოვრების თვალიერების ნაცვლად, გახსენით განწყობის დღიური და მომავლისთვის ჩაინიშნეთ მისი დღევანდელი ყველაზე სასაცილო საქციელი — მომენტი, რომელმაც ყველაზე მეტად გაგაცინათ. იქ წერა ყველაზე სუფთა თერაპიაა.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'შამპანური წყვილისთვის 🥂', 'ბავშვმა დაიძინა. შამპანური თუ არ გაქვთ, ჭიქებში ცხელი ჩაი ჩაასხით, პარტნიორს ჭიქა მიუჭახუნეთ და უთხარით: „ეს ქარიშხლიანი დღეც მშვიდობით გადავაგორეთ“. თქვენ ამ სახლის სარდლებიც ხართ და ურყევი გუნდიც.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'ალოგიკური ცრემლები 🐶', 'ქუჩაში ნანახმა ძაღლმა არ შეხედა ან ფოთოლი მიწაზე ჩამოვარდა და ამის გამო ხმამაღლა ატირდა? ამ სიტუაციაში ლოგიკას ნუ ეძებთ. მისთვის ეს მართლაც ღრმა მწუხარებაა. უბრალოდ დაუდასტურეთ მისი გრძნობა და უთხარით: „ვიცი, გინდოდა, რომ შენთვის შემოეხედა“.'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'პოლიტიკა სათამაშო მოედანზე 🤝', 'სურს, სასრიალოზე სხვა ბავშვს ხელი ჰკრას და თვითონ დაეშვას? გაზიარება მისთვის ჯერ კიდევ რთული და ბოლომდე გაუგებარი ცნებაა. შერცხვენის ან დასჯის ნაცვლად, უბრალოდ შეახსენეთ წესრიგი და უთხარით: „ახლა მისი ჯერია“.'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'სხეულის განგაში 🩸', 'ნუ დანებდებით უმიზეზო გაღიზიანებასა და დაღლილობას. შეამოწმეთ მენსტრუაციის ტრეკერი — თქვენი სხეული სიგნალს გაძლევთ. საკუთარი თავის დადანაშაულების ნაცვლად, დაისვენეთ და მაგნიუმით მდიდარი წასახემსებელი მიირთვით.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'ჩრდილთან ბრძოლა 👻', 'კედელზე საკუთარი ჩრდილის ეშინია და თქვენ უკან იმალება? 3 წლის შუა პერიოდისთვის წარმოსახვას საზღვრები აღარ აქვს. ჩააბნელეთ ოთახი და ფანრის შუქზე ხელებით კედელზე ჩრდილების თეატრი მოაწყვეთ. სიბნელე, რომლისაც ეშინია, მისთვის ყველაზე დიდ გასართობად აქციეთ.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'ზღაპრების ჯადოსნობა 🪄', 'კითხვის კლასიკური სტილი გვერდზე გადადეთ. ჩართეთ ჭკვიანი ზღაპრები. ზღაპარში ქარის ზუზუნის, კარის ჭრიალისა და გმირის ნაბიჯების ხმები პირით გამოსცით და ოთახში პატარა ხმოვანი თეატრი მოაწყვეთ. ის ამ წარმოდგენით აღფრთოვანებული დარჩება.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'ძილის გადადების ტაქტიკა ⏱️', 'როგორც კი დაძინების დრო დგება, მოულოდნელად სწყურდება, ტუალეტში მოუნდება წასვლა ან კედელს ემშვიდობება? დააყენეთ ტაიმერი. მოთმინებით დაასრულეთ ეს უსასრულო დამშვიდობება და ოსტატური მანიპულაცია წესით: „როცა ზარი დარეკავს, ყველა იძინებს“.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'სათამაშოების დედა 🧸', 'ოთახიდან ხმა ისმის. ყურადღებით უსმენთ და აღმოაჩენთ, რომ ის თავის დათუნიას ზუსტად თქვენი ხმის ტონითა და თქვენთვის დამახასიათებელი ფრაზებით საყვედურობს! ის თქვენი ყველაზე ზუსტი ასლია. ეს შესანიშნავი შესაძლებლობაა, საკუთარ ქცევას გვერდიდან შეხედოთ.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'ამინდის დაზვერვა ⛅', 'გარეთ ამინდი ბოლომდე ნათელი არ არის — მზე ანათებს, მაგრამ ქარიც ქრის? ამინდისა და ჩაცმულობის ხელსაწყო მყისიერად გეტყვით ქარის სიჩქარეს, რომელიც ფანჯრიდან არ ჩანს, და სწორ სამოსსაც შეგირჩევთ. ასე კართან ყოყმანში დროს აღარ დაკარგავთ და პირდაპირ სასეირნოდ გახვალთ.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'მამის საიდუმლო ტაქტიკა 👨‍🍼', 'დღის დაღლილობა და ხმაური თქვენთვის უკვე საკმარისია. საღამოს ბავშვის დასაძინებლად მომზადება და კბილების გახეხვა მამის თამაშით სავსე მიდგომას მიანდეთ, თავად კი განმარტოვდით სხვა ოთახში და სრულ სიჩუმეში აუცილებლად დაისვენეთ.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'დედის ენერგეტიკული ბარი 🥑', 'მის გამოსაკვებად მენიუ 4 სხვადასხვა ვარიანტად შეადგინეთ, მაგრამ თავად რა მიირთვით? ჯანსაღი რეცეპტებიდან შეარჩიეთ კალციუმით მდიდარი განსაკუთრებული წასახემსებელი, რომლის მომზადებასაც 5 წუთი სჭირდება, და თუნდაც ფეხზე დგომით, გემრიელად მიირთვით — თქვენ ამ სახლის მამოძრავებელი ძალა ხართ.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'გაუყოფელი საუზმე 🍳', 'თავის თეფშიდან არაფერს გინაწილებთ, მაგრამ დაჟინებით სურს, თქვენი თეფშიდან კვერცხი ან ყველი მიირთვას. ბავშვები ყოველთვის სრულად ენდობიან მშობლების არჩევანს. ნუ შეეწინააღმდეგებით — თქვენი ლუკმა სიყვარულით გაუნაწილეთ.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'გუნდური მასაჟი 💆‍♂️', 'ბავშვის დაძინების შემდეგ, დღის განმავლობაში დაგროვილი ფიზიკური და ემოციური დაძაბულობის მოსახსნელად, თქვენ და თქვენმა პარტნიორმა ერთმანეთს მხრების მასაჟი გაუკეთეთ. თქვენ მხოლოდ ერთ სახლში მცხოვრები მშობლები კი არა, ერთმანეთის ურყევი მხარდამჭერი გუნდი ხართ.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'ეს ჩემი ბრალი არ არის! 🤷‍♂️', 'წყალი განზრახ დაღვარა, მაგრამ ყველაფერი მაგიდას დააბრალა და თქვა: „მაგიდა გაცურდა“. ეს ტყუილი კი არა, თავდაცვის ინსტინქტია. ნუ შეეკამათებით; უთხარით: „მოდი, მაგიდას დავეხმაროთ და ერთად მოვწმინდოთ“, რათა პასუხისმგებლობის გრძნობა მისი წყენინების გარეშე განუვითაროთ.'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'საზოგადოების მხარდაჭერა 💬', 'ფიქრი — „ძველებურად თავისუფალი მე ვეღარასოდეს ვიქნები“ — მოულოდნელად გახრჩობთ? გაუზიარეთ ეს დროებითი, თუმცა ძალიან მძიმე და ღრმა განცდა Anacan-ის საზოგადოებაში მყოფ დედებს და მიიღეთ მათგან ნუგეში და მხარდაჭერა იმის ცოდნით, რომ მათაც იგივე გზა გაიარეს.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'ახალი ლექსიკური აღმოჩენები 🗣️', 'საგნებს სრულიად თავისივე მოგონილ, არცერთ ენაში არსებულ ახალ სახელებს არქმევს. და დაჟინებით მოითხოვს, რომ თქვენც იგივე სიტყვა გამოიყენოთ! გახსენით განვითარების ტრეკერი და აუცილებლად ჩაინიშნეთ მისი ეს სასაცილო სიტყვები, რათა მომავალში წაიკითხოთ და გაიცინოთ.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'სახლის საიდუმლო განძეული 🔑', 'სახლის გასაღებებს ან პულტს ვერ პოულობთ? ჩაიხედეთ სათამაშო ღუმელში ან ბავშვის საწოლის ქვეშ. ნივთების დამალვით ის სამყაროს გამოცდის. ამ სახალისო განძის ძიებისას გაბრაზების ნაცვლად, სიცილი და ღრმად ჩასუნთქვა აირჩიეთ.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'ბანაობის პარადოქსი 🛀', 'აბაზანაში შესვლა რომ არ უნდოდა, ტიროდა, ახლა კი იქიდან გამოსვლა არ უნდა და ყვირის! წყლის ჯადოსნურმა, დამამშვიდებელმა მოქმედებამ ის დააჰიპნოზა. წყლიდან ამოსვლა დრამად რომ არ იქცეს, პირსახოცს „თბილი ჩახუტება“ დაარქვით, შემოახვიეთ და ამოიყვანეთ.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'უბრალოდ ჩაეხუტეთ 🫂', 'არავითარი თამაში, ხმაურიანი წიგნი ან ზღაპარი არ არის საჭირო. ამ საღამოს უბრალოდ გულში ჩაიკარით, ღრმად შეისუნთქეთ მისი სუფთა სურნელი და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია ის თქვენთვის და როგორ გიყვართ.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', 'მარკეტში „მე წავიყვან!“ სიჯიუტე 🛒', 'სურს, მარკეტის ურიკა თავად წაიყვანოს და თაროებზე დაჯახებით ქაოსს ქმნის. საჯაროდ ატირებას სჯობს, ხელები ურიკის კიდეზე დაატოვებინოთ, თქვენ კი შეუმჩნევლად მართოთ. რაც დაგავიწყდათ, საყიდლების სიაში გადაამოწმეთ.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'სათამაშოების ქაოსი 🌪️', 'დაიღალეთ ყოველდღე ერთი და იმავე სათამაშოების ალაგებით? დღეს ნუ აალაგებთ! სახლი მუზეუმი კი არა, სიცოცხლით სავსე თბილი სივრცეა, სადაც პატარა მკვლევარი იზრდება. უწესრიგობაზე კი არა, თქვენი ბავშვის თავისუფალი აღმოჩენებით გამოწვეულ სიხარულზე გაამახვილეთ ყურადღება და დაისვენეთ.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'დაბლა ჩაიხედეთ — რას აღმოაჩენს? 👣', 'სიამოვნებს ფეხშიშველი სიარული და ხალიჩის, ოთახში არსებული ქვების ან ცივი კაფელის შეხება. ტერფებზე არსებული ნერვული დაბოლოებების გააქტიურება ძალიან მნიშვნელოვანია მისი წონასწორობისა და ნევროლოგიური განვითარებისთვის, ამიტომ წინდების გარეშე სიარულს ნუ დაუშლით.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'ხელოვნური ინტელექტი, რეალური გამოსავალი 🤖', 'შეგაშინათ იმან, რომ თქვენი ბავშვი ყველაფერზე მძაფრად რეაგირებს? დაივიწყეთ ინტერნეტში წაკითხული შემაშფოთებელი სტატიები. ჰკითხეთ Anacan AI-ს, ხომ არ არის ეს უბრალოდ სტრესზე დროებითი რეაქცია, მიიღეთ მეცნიერულად დასაბუთებული და პედიატრების მიერ დადასტურებული პასუხი და დამშვიდდით.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'ჩააქრეთ შუქი, რომ ძილი მოვიდეს 🌙', 'დაძინების დასაჩქარებლად, დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი (ძილის ჰორმონი) სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა, რაც დაძინებას უწყობს ხელს.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'მიიღეთ შთაგონება ბლოგებიდან 📱', 'როგორია ბავშვის განვითარების ნახტომები 40-ე თვისთვის? რისი კეთება უნდა შეეძლოს მას? გადახედეთ აპლიკაციაში განვითარების შესახებ ბლოგებს, ნახეთ, რამდენად დაწინაურებულია თქვენი შვილი აღქმასა და ლოგიკურ აზროვნებაში და გულში გაიხარეთ.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'დაუსრულებელი წინადადებების დასასრული 🗣️', 'როდესაც სიტყვა ავიწყდება, ხელით განიშნებთ, წარბებს კრავს და ელოდება, რომ თქვენ გამოიცნობთ. მოთმინებით დაუსრულეთ წინადადება და დააკვირდით, როგორ გამოეხატება სახეზე შვება: „ჰო, სწორედ ამის თქმა მინდოდა“. მისი თარჯიმანი მხოლოდ თქვენ ხართ.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'უეცარი შიმშილის სინდრომი 🥱', 'როგორც კი საწოლში წვება, ამბობს: „დედა, მომშივდა“ და სამზარეულოში გაქცევა უნდა. ძილის გადასადებად ეს ნამდვილი შედევრია! კვების გეგმაში საღამოსთვის ძილის ხელშემწყობი მცირე წასახემსებელი შეარჩიეთ და ეს საბაბი წინასწარ გააქრეთ.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', 'შანტაჟი — „ფეხები დამეღალა“ 🚶‍♂️', 'ქუჩაში სიარულისას მოულოდნელად ძირს ჯდება და ამბობს: „ფეხები მომტყდა, ხელში ამიყვანე“? ეს ფიზიკური დაღლილობა კი არა, უბრალოდ დედის მანიპულირების მცდელობაა. თამაშად აქციეთ: აბა, ვნახოთ, სახლამდე კურდღელივით ხტუნვით ვინ უფრო სწრაფად მივა?'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'დედის გადატვირთვის ღილაკი 🚪', 'ხმაური თავს გიხეთქავთ და გინდათ, ყველაფერზე იყვიროთ. გახსენით განწყობის დღიური. თავისუფლად ჩაწერეთ იქ ყველაფერი, რასაც გადაღლილობისგან გრძნობთ. ეს ხანმოკლე ციფრული თერაპია ძალების აღდგენაში დაგეხმარებათ.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', '„ჩემია!“ — სიჯიუტე 🧸', 'სახლში ნებისმიერ შემთხვევით ნივთს ეხუტება, ყვირის: „ეს ჩემია!“ და არავის აძლევს. ის საკუთრების საზღვრებს ეცნობა. ნუ დაადანაშაულებთ ეგოიზმში — უბრალოდ, იმ მომენტში მიიჩნიეთ, რომ ეს ნივთი მას ეკუთვნის.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'თქვენი ხმის შეფერილობა 🌙', 'ის წიგნში მოთხრობილი ზღაპრის სიუჟეტს კი არა, თქვენი ხმის ტონს უსმენს. ამ საღამოს სიუჟეტი დაივიწყეთ. ამბავი ნელა და გაწელილად, ნაზი მუსიკის მსგავსად, ხმადაბლა წაუკითხეთ და მის ნერვულ სისტემას პირდაპირ ძილის სიგნალი გაუგზავნეთ.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'სოციალური მედიის ილუზია 📱', 'ინტერნეტში იდეალურ დედებს ხედავთ და სახლში არეულობის გამო საკუთარ თავს ადანაშაულებთ? შეჩერდით. ნუ დაუჯერებთ იმ 15-წამიან, ფილტრებით დამუშავებულ ვიდეოებს.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'მამას ზღაპარი 📖', 'ამ საღამოს ხმა დაგეღალათ. ზღაპრის წაკითხვა მამას მიანდეთ. ის წიგნის ილუსტრაციისგან სრულიად განსხვავებულ, გამოგონილ და სასაცილო ამბავს მოჰყვება და ბავშვს გულიანად გააცინებს. თქვენ კი გვერდით მოკალათდით, ფინჯანი ჩაი მოიმარჯვეთ და ამ სანახაობით დატკბით.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'პატარა დამხმარე სამრეცხაოში 🧺', 'თქვენ დიდი მონდომებით კეცავთ ტანსაცმელს, ის კი დახმარების სურვილით ყველაფერს ისევ ოთახში ფანტავს. გაბრაზების ნაცვლად, საქმე თამაშად აქციეთ: ვნახოთ, ვინ ჩაყრის ამ წინდებს კალათაში უფრო სწრაფად და ზუსტად?'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'ბუნებაში გასვლა აუცილებელია ⛅', 'ოთხ კედელს შორის მისი ენერგია აგრესიად იქცევა და ყოველ წინადადებას „არათი“ იწყებს. ამინდისა და ჩაცმულობის მიუხედავად, სათანადოდ მოემზადეთ და აუცილებლად გაიყვანეთ გარეთ. მიწასთან შეხება მის ნერვულ სისტემას მყისიერად განტვირთავს.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'ლოგიკის სრული კრახი 🔴', 'ყვირის, რომ წყალი წითელ ჭიქაში ჩაუსხათ, ხოლო როცა უსხამთ, ტირის და გეკითხებათ, აქ რატომ ჩამისხიო. აქ ლოგიკა არ მუშაობს. ის უბრალოდ დაღლილია და ემოციებისგან დაცლა სჭირდება. მშვიდად დაელოდეთ — ქარიშხალი თავისით ჩაცხრება.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'ჯიბეში ნაპოვნი საგანძური 🪨', 'შარვლის გარეცხვისას ჯიბიდან 2 ქვა, ერთი გამხმარი ფოთოლი და ნახევარი ჩხირი ამოიღეთ? ეს ნივთები, რომლებიც თქვენთვის ნაგავია, ბავშვისთვის ძვირფასი კოლექციაა, რომელიც სამყაროს აღმოჩენისას შეაგროვა. გადაყრის ნაცვლად, პატარა საგანძურის ყუთში მოუყარეთ თავი.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'მე ჭკვიან ზღაპარში 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით. გახსენით ჭკვიანი ზღაპრები, მთავარ გმირად თქვენი ბავშვი აქციეთ, დასაპყრობ ადგილად კი მისი ოთახი შეარჩიეთ და უჩვეულო აუდიოძილის სეანსი ყოველგვარი ძალისხმევის გარეშე შექმენით.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'ნაგავი კი არა, ხელოვნებაა 🎨', 'მან ოთახის შუაგულში ქაღალდის პატარა ნაგლეჯებისა და დაჭრილი ძაფებისგან დიდი ხელოვნების ნიმუში შექმნა და მისი გადაყრის უფლებას არ გაძლევთ. ცოტა ხნით დაივიწყეთ სისუფთავისადმი ზედმეტი მოთხოვნილება. პატივი ეცით მის მიერ შექმნილ ქაოსს — დალაგება ხვალაც შეიძლება.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'ტირილის ანალიზის დახმარება😭', 'შუაღამისას თვალდახუჭული, ტირილით იღვიძებს და არავის ხმა არ ესმის. გადაამოწმეთ ტირილის ანალიზით; თუ ეს ღამის ტერორია, მის გაღვიძებას ნუ ეცდებით. უბრალოდ ჩუმად დარჩით მის გვერდით — რამდენიმე წუთში ისევ დაიძინებს.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'უსულო საგნებთან საუბარი 🗣️', 'პარკში ქვას ან სახლში სკამს სრული სერიოზულობით რაღაცებს უყვება და საყვედურობს. სიმბოლური თამაშების მეშვეობით ის სამყაროსა და წესებს იაზრებს. განვითარების ტრეკერში აუცილებლად მონიშნეთ მისი ეს განსაკუთრებული სცენარები.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'აბაზანაში თამაში 🌊', 'აბაზანაში ბანაობა უკვე სისუფთავისთვის კი არა, ტალღების შესაქმნელი თამაშია. მიეცით საშუალება, წყალი ირგვლივ აშხეფოს და აბაზანა დაასველოს. წყლის ეს მაგიური ეფექტი მთელი დღის განმავლობაში მასში დაგროვილ ჯიუტ, ნეგატიურ ენერგიას ჩამორეცხავს და კანალიზაციაში გაატანს.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'მიზანმიმართული ნგრევა 🧱', 'დიდი მონდომებით აშენებს კოშკს, შემდეგ კი სიცილით ერთი ხელის მოსმით ანგრევს. ასე ის ფიზიკასა და მიზეზშედეგობრივ კავშირს სწავლობს. ნუ გაბრაზდებით — დანგრეული კოშკები მის ტვინში წარმოქმნილი ახალი ნეირონული კავშირებია. დაეხმარეთ, თავიდან ააშენოს.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'დღის ძილის აჯანყება 🥱', 'არ სურს დასაძინებლად დაწოლა და ტირის? ნუ აიძულებთ. ოთახში განათება შეამცირეთ და „წიგნის ჩუმად თვალიერების საათი“ გამოაცხადეთ. ასე შექმნით ახალ რუტინას, რომელიც ორივეს დაგასვენებთ — უბრალოდ თითოეულს განსხვავებული გზით.'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'დილის დიქტატორი საქმეს შეუდგა 👑', 'იქ თქვენ ნუ დაჯდებით, დათუნია უნდა დაჯდეს! საუზმობისას მთელ მაგიდას ის განაგებს. ზედმეტად მკაცრად ნუ შეეწინააღმდეგებით მის ნებას — უთხარით: „კარგი, დათუნია იქ დაჯდეს, მე კი აქ დავჯდები“ და ასე შეინარჩუნეთ წონასწორობაც და სიმშვიდეც ოთახში.'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'ჩაი სანთლის შუქზე 🕯️', 'ბავშვს ჩაეძინა. ჩააქრეთ შუქი და მაგიდაზე ერთი სანთელი აანთეთ. ეს რომანტიკისთვის კი არა, უბრალოდ მთელი დღის განმავლობაში გაღიზიანებული ნერვებისა და ეკრანებითა და ხმაურით დაღლილი თვალების დასამშვიდებლადაა.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'შეხებით გადაღლა 🔋', 'მთელი დღე ზედ გაძვრებათ, ჩახუტებას ითხოვს და თქვენს თმას ეთამაშება. შეხებით გადაღლა (touched out) რეალური მდგომარეობაა. თქვენ გაქვთ უფლება, სულ მცირე 15 წუთით მარტო გახვიდეთ ცალკე ოთახში და იგრძნოთ, რომ თქვენი სხეული მხოლოდ თქვენ გეკუთვნით.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'მამას ზურგზე ცხენობანა 🐴', 'ბავშვმა ენერგია ბოლომდე ვერ დახარჯა და დაძინებას ეწინააღმდეგება. მამას დასახმარებლად უხმეთ. როცა ის ბავშვს ზურგზე შეისვამს და ცხენივით გააჭენებს, ოთახი სიცილით ივსება, დაგროვილი ფიზიკური დაძაბულობა და ეს დაუსრულებელი ენერგია კი წამებში, ოფლის ღვრასთან ერთად ქრება.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'გულწრფელი აღიარება საზოგადოებაში 💬', 'დღეს ყველაფერზე ყვიროდით და თავს მსოფლიოში ყველაზე მოუთმენელ დედად გრძნობთ? გთხოვთ, იცოდეთ, რომ მარტო არ ხართ. შედით Anacan-ის საზოგადოებაში, წაიკითხეთ, რომ დღეს სხვა დედებიც თქვენზე არანაკლებ გამოიფიტნენ, და შვებით ამოისუნთქეთ.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'მეტოქე სარკეში 🪞', 'სარკის წინ დგას, საკუთარ თავს წარბებს უქუფრავს და გაბრაზებულ თუ უცნაურ სახეებს იღებს. ის ამოწმებს, როგორ აისახება ემოციები სახეზე. ხმა არ ამოიღოთ და ინტერესით უყურეთ ამ პატარა თეატრის მსახიობის რეპეტიციას.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'წარმოსახვითი მაღაზია 🍅', 'ოთახის ერთ კუთხეში სათამაშოებს ალაგებს და წარმოსახვით პომიდორს წარმოსახვით ფულზე გყიდით. ამ სავაჭრო თამაშს სრული სერიოზულობით მოეკიდეთ. იყიდეთ წარმოსახვითი პომიდორი და ისე მოიქეცით, თითქოს მადიანად მიირთმევთ. როლური თამაშები მისი სოციალური ინტელექტის უმნიშვნელოვანესი საფუძველია.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'მუსიკალური ჰიპნოზი 🎶', 'საღამოობით უმიზეზო ქარიშხლები და ტირილის შეტევები დაიწყო. გამორთეთ ტელევიზორი, ჩააქრეთ განათება და ოთახში ძალიან ჩუმად ჩართეთ კლასიკური მუსიკა. მუსიკის ღრმა სიხშირეები გარემოს ჯადოსნურად შეცვლის.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'სრულყოფილება არ არსებობს 🛑', 'დღეს მოთმინება დაკარგეთ? თავს ცუდად ნუ იგრძნობთ. თავი შორს დაიჭირეთ ინტერნეტში შექმნილი უნაკლო დედის ილუზიებისგან. თქვენ ნამდვილი დედა ხართ და უფლება გაქვთ, განიცადოთ ემოციები და დაღლილობა.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'შოპინგის მხსნელი 🛒', 'მაღაზიაში წასვლისას ყოველთვის ყველაზე მნიშვნელოვანი ნივთი გავიწყდებათ? საყიდლების სია აპში გელოდებათ. საჭირო ნივთები იქ ჩაინიშნეთ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ყველაფერი ზუსტად შეიძინოს, თქვენ კი გონება აღარ გადაიღალოთ.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', '„დედა, შემომხედე!“ პერიოდი 👀', 'დივნიდან ხტება, ერთსა და იმავე მოძრაობას ზუსტად 50-ჯერ იმეორებს და ყოველ ჯერზე ამბობს: „დედა, შემომხედე!“ თვალი მოსწყვიტეთ ტელეფონს. ის თქვენს თვალებში მოწონებისა და მხარდაჭერის ნაპერწკლის დასანახად ხტება. დაუთმეთ 5 წუთი უწყვეტი ყურადღება, რათა თქვენი ყურადღებით გაძღეს.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'ჩურჩულით მოყოლილი ამბები 🌙', 'დღეს ბევრი ილაპარაკეთ და ფილტვებიც დაგეღალათ. ჩააქრეთ შუქი, გვერდით მიუწექით და დღის განმავლობაში მომხდარი ამბები ყურში მხოლოდ ჩურჩულით მოუყევით. ჩურჩული მის ყურადღებას ამახვილებს და ტვინს თითქმის ჰიპნოზურად ამზადებს ღრმა ძილისთვის.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'საკვების შენიღბვის ოპერაცია 🥣', 'კვერცხს, რომელიც გუშინ უყვარდა, დღეს პირსაც არ აკარებს. ნუ შეებრძოლებით მის ნებას. გაიმარჯვეთ პატარა ხრიკის დახმარებით — ჯანსაღ წასახემსებელ რეცეპტებში ცილოვანი პროდუქტები განსხვავებული, ფერადი და საინტერესო ფორმით შესთავაზეთ.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'სიჩუმის დასტური 🤫', 'ხმაურიანი დღის შემდეგ, როცა ბავშვს ჩაეძინება, ხმაურის საზომით ოთახში სიჩუმის დონე გაზომეთ. ნულთან მიახლოებული ციფრების დანახვა — ეს ვიზუალური სიმშვიდე — დედის ტვინზე საუკეთესო მასაჟივით მოქმედებს.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', 'მოულოდნელი „მიყვარხარ“ 💖', 'ოთახის შუაგულში თამაშისას მოულოდნელად შემოგხედავთ, სირბილით მოვა და კისერზე შემოგეხვევათ. ეს ყველა უძილო ღამედ და დაღლილობად ღირს! დატკბით იმ ღრმა და უნიკალური სიმშვიდით, რომელიც ამ წამს მოაქვს.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'ჩააქრეთ სინათლე — ძილის დროა 🌙', 'იმისთვის, რომ ბავშვს უფრო სწრაფად ჩაეძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი სინათლე ჩააქრეთ და პლანშეტის ეკრანი გამორთეთ. მელატონინი (ძილის ჰორმონი) სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამოიყოფა.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'ბოჭკოს საჭიროება 💩', 'ბევრს დარბის, მაგრამ წყლის დალევა ავიწყდება. ქოთანში განავალს დააკვირდით. თუ შეკრულობის რისკია, ეს აპლიკაციაში აღნიშნეთ და კვების კონტროლის ხელსაწყოს დახმარებით მენიუში დაუყოვნებლივ დაამატეთ შვრია და ქლიავი.'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'აკრძალული სიტყვები 🤐', 'ქუჩაში ან ტელევიზორში გაგონილ ცუდ სიტყვას სიცილით გიმეორებთ და დიდი ინტერესით ელოდება თქვენს რეაქციას. თქვენი ყველაზე ძლიერი იარაღი რეაქციის არქონაა. ნუ გაიცინებთ, ნუ გაბრაზდებით — უბრალოდ ყურადღება არ მიაქციოთ. მალე ეს სიტყვა დაავიწყდება.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'ზღაპრის დასასრული თავად დაწეროს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ. ამჯერად ინტერაქტიულ ზღაპრებში ისტორიის დასასრული თქვენს ბავშვს აარჩევინეთ. ჰკითხეთ: „როგორ ფიქრობ, გმირს ვინ დაეხმარა?“ და ძილის წინ მის წარმოსახვას თავისუფლება მიეცით.'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'ყინულივით ცივი ლოგიკა 🥶', 'მაცივარს აღებს, იქიდან ყინულის ფორმას ითხოვს და ხელების გაყინვის მიუხედავად, ხელს არ უშვებს. ასე საკუთარ სხეულზე ამოწმებს სითბოსა და სიცივის ცნებებს. ერთ ჭურჭელში თბილი, მეორეში კი ყინულიანი წყალი ჩაასხით და ეს აღმოჩენა პატარა სამეცნიერო ექსპერიმენტად აქციეთ.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'მამას პარკში სირბილი 👨‍👧', 'დედობა 24/7-ზე მიმდინარე მორიგეობა არ არის. ჩართეთ პარტნიორის რეჟიმი! დღეს ეს დაულეველი ენერგია მამასთან ერთად პარკში დახარჯოს, თქვენ კი სახლში სრული სიჩუმით დატკბით.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'კონცერტი სამზარეულოში 🥄', 'ქვაბებსა და ხის კოვზებს იღებს და შუა სამზარეულოში კონცერტს მართავს. შეიძლება თავი აგტკივდეთ, მაგრამ ასე მისი რიტმის შეგრძნება და შემოქმედებითი უნარები ვითარდება. მაშინვე ნუ ჩაერევით — რამდენიმე წუთით მიეცით საშუალება, ეს გიჟური ენერგია ბგერით ტალღებად მთელ ოთახში გაავრცელოს.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'ამინდის დაზვერვა ⛅', 'გარეთ ამინდი ბოლომდე ნათელი არ არის — მზე ანათებს, მაგრამ ქარიც უბერავს? ამინდისა და ჩაცმულობის ინსტრუმენტი მყისიერად გეტყვით ფანჯრიდან შეუმჩნეველი ქარის სიჩქარეს და შეგირჩევთ შესაფერის სამოსს, რათა კართან ყოყმანში დრო არ დაკარგოთ და სასეირნოდ გახვიდეთ.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'გუნდური მასაჟი 💆‍♂️', 'ბავშვის დაძინების შემდეგ დღის სტრესის მოსახსნელად პარტნიორთან ერთად ერთმანეთს მხრების მასაჟი გაუკეთეთ. თქვენ მხოლოდ ერთ სახლში მცხოვრები მშობლები კი არა, ერთმანეთის ურყევი მხარდამჭერი გუნდი ხართ.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'პატარა ბიზნესმენი 🍅', 'ოთახის ერთ კუთხეში სათამაშოებს აგროვებს და წარმოსახვით პომიდორს წარმოსახვით ფულზე გყიდით. ამ სავაჭრო თამაშს სრული სერიოზულობით მოეკიდეთ. იყიდეთ წარმოსახვითი პომიდორი და ისე მოიქეცით, თითქოს მადიანად მიირთმევთ. როლური თამაშები მისი სოციალური ინტელექტისა და მათემატიკური აზროვნების უმნიშვნელოვანესი საფუძველია.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'კალციუმის ფარი 🦴', 'სწრაფად მზარდი ძვლებისთვის კალციუმი აუცილებელია. რძეს არ სვამს? კვების კონტროლის ხელსაწყოს დახმარებით დღეს აუცილებლად აღრიცხეთ, რამდენი ყველი, იოგურტი ან ბროკოლი მიიღო.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'საწოლიდან გაქცევა 🏃‍♂️', '„წყალი მომეცი“, „ჩემი სათამაშო იპოვე“... 3 წლის ბავშვის ძილისგან თავის ასარიდებელი მიზეზები არ ილევა. ჩართეთ ძილის ტაიმერი და მტკიცედ დაიცავით საზღვრები.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'უზარმაზარი ტვირთი 🎒', 'თქვენი მძიმე ჩანთების ან დიდი ქოლგის ტარება აუცილებლად თვითონ სურს. ძლივს მიათრევს, მაგრამ დახმარებაზე კატეგორიულ უარს ამბობს. მიეცით საშუალება, საკუთარი ძალა მოსინჯოს — მას სურს, თავი ოჯახის ყველაზე ძლიერ გმირად იგრძნოს. ხელს ნუ შეუშლით მის დამოუკიდებლობას.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'ახალი იდენტობა 🕷️', 'დილით იღვიძებს და სრული სერიოზულობით გეუბნებათ: „მე ბავშვი კი არა, ობობა ვარ“. 40-ე თვისთვის წარმოსახვა ყოველგვარ საზღვარს სცდება. ნუ შეეკამათებით — საუზმის მჭამელი ობობის როლი მიეცით და ამ აბსურდულ თეატრში თქვენც ჩაერთეთ.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'დაუსრულებელი მიზეზები 🦶', 'როგორც კი თითქმის ჩაეძინება, საწოლიდან წამოდგომას იმ მიზეზით ცდილობს, რომ „ფეხის თითი ექავება“. ძილის გადადების ხელოვნება უკვე სრულყოფილად აითვისა. იყავით მტკიცე, ვითომ მოუფხანეთ ფეხი და გადაჭრით ჩააქრეთ შუქი — საზღვრებს თქვენ ადგენთ.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'ემოციების მკვეთრი ცვალებადობა 🤖', 'სამნახევარი წლის ასაკის მოახლოებასთან ერთად ბავშვის ემოციების მკვეთრმა ცვალებადობამ შეგაშინათ? დახურეთ ინტერნეტში ნაპოვნი შემაშინებელი და ტრავმული ფორუმები. Anacan AI-სგან მიიღეთ ამ ასაკობრივი კრიზისების შესახებ მეცნიერულად და ფსიქოლოგიურად დასაბუთებული, დამამშვიდებელი პასუხი.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'თბილი წყლის სასწაული 🛀', 'ზოგჯერ არაფერი ჭრის და ბავშვი ყველაფერზე ტირის. ჩასვით თბილი წყლით სავსე აბაზანაში და ცოტაოდენი ქაფიც დაუმატეთ. წყლის მისტიკური, დაძაბულობის მომხსნელი ძალა მყისიერად მოუტანს სიმშვიდეს როგორც მთელ ოთახს, ისე მის ნერვულ სისტემას.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'გარდერობის ინჟინერი 👗', 'დღეს გარეთ სხვადასხვა წინდითა და უკუღმა ჩაცმული მაისურით გასვლა სურს. ნუ მიაქცევთ ყურადღებას საზოგადოების შეხედულებებს იმის შესახებ, თუ რა რას უნდა უხდებოდეს. საკუთარი გადაწყვეტილების მიღებისა და დაცვის თავისუფლება ბევრად უფრო მნიშვნელოვანი ცხოვრებისეული გაკვეთილია, ვიდრე ფერების შეხამება. მიეცით ამის უფლება.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'ცოცხალი დიქტოფონი 🎙️', 'სიტყვას, რომელიც გუშინ მეუღლესთან საუბრისას შემთხვევით და, შესაძლოა, უადგილოდ გამოიყენეთ, ბავშვი ამ დილით თავის სათამაშოს ეუბნება! ის თქვენი ცოცხალი სარკეა. განსაკუთრებული ყურადღება მიაქციეთ, მის გვერდით რა ემოციებით საუბრობთ — ყველაფერს სათითაოდ იმეორებს.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'მამის მხიარული ზღაპარი 📖', 'ამ საღამოს ოთახში თქვენი ხმა კი არა, მამის ხმა გაჟღერდეს. ზღაპრების წიგნი მამას მიეცით და სთხოვეთ, ამბავი განზრახ არასწორად, სასაცილოდ და აბსურდულად მოჰყვეს. გვერდიდან უყურეთ, როგორ სიამოვნებს ბავშვს მისი შესწორება და როგორ კისკისებს მამასთან ერთად.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'საზოგადოების ძალა 💬', 'ფიქრი — „რატომ არის ჩემი ბავშვი ასეთი ჯიუტი?“ — მოსვენებას არ გაძლევთ. შეუერთდით Anacan-ის საზოგადოებას. როცა სხვა დედების ოჯახებში მომხდარ მსგავს აბსურდულ კრიზისებზე წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ და სრულიად ნორმალურ გზას ადგახართ.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'ამინდის დაზვერვა ⛅', 'მზე გამოვიდა, მაგრამ მას ზამთრის ქურთუკის ჩაცმა უნდა. ნუ შეეკამათებით. გახსენით ამინდისა და ტანსაცმლის ინსტრუმენტი და ეკრანზე თხლად ჩაცმული ბავშვის სიმბოლო აჩვენეთ. ხრიკი — „ნახე, ტელეფონი ამბობს, რომ დღეს ცხელა“ — ყოველთვის შესანიშნავად მუშაობს.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'სცენარი მის ხელშია 🪄', 'კლასიკური ზღაპრები მის ყურადღებას ვეღარ იპყრობს. გახსენით ჭკვიანი ზღაპრები და ჰკითხეთ: „ახლა ეს ჯადოსნური მატარებელი სად წავიდეს?“ მიეცით საშუალება, თავისივე მოფიქრებულ უცნაურ და სრულიად აბსურდულ დასასრულზე ოცნებაში ჩაიძიროს და დაიძინოს.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'სტომატოლოგთან ვიზიტი 🦷', 'ჯაგრისი აიღო და თქვენი კბილების სერიოზულად შემოწმება სურს. გააღეთ პირი და ამ მხიარულ ექიმს დაემორჩილეთ. როლური თამაშები პიროვნული განვითარებისა და შიშების დაძლევის ერთ-ერთი ყველაზე ეფექტური და სახალისო გზაა.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'ნაგავი კი არა, განძი 🍬', 'დიდი ამბავი ატყდა, რადგან ძველი შოკოლადის ქაღალდი გადააგდეთ, რომელსაც უკვე რამდენიმე დღე ინახავდა, თუმცა არ თამაშობდა? ის, რაც თქვენთვის ნაგავია, მისთვის შესაძლოა ძვირფასი კოლექციის ნაწილი იყოს. ტირილის შესაწყვეტად მისი ყურადღება მაშინვე უფრო საინტერესო ნივთზე გადაიტანეთ.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'გამარჯვება შამპანურის გარეშე 🥂', 'ბავშვმა დაიძინა. შამპანური თუ არ გაქვთ, ჭიქებში ცხელი ჩაი ჩამოასხით, თქვენს პარტნიორს ჭიქა მიუჭახუნეთ და უთხარით: „დღესაც მოვახერხეთ ამ ქარიშხლიანი ქაოსის მართვა.“ თქვენ ამ სახლის ურყევი და დაუღალავი გუნდი ხართ.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'ბროკოლის დეტექტივი 🥦', 'წვნიანში ერთადერთი მწვანე ბოსტნეული აღმოაჩინა და ჭამაზე უარს ამბობს? კვების გეგმაში გამოიყენეთ ყველაზე მოხერხებული ხერხები: ბოსტნეული ყურადღების გადასატანად ფერად მაკარონს შეურიეთ ან პიურედ აქციეთ და შეუმჩნევლად დაუმალეთ.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'მამის ქუდის პირობა 🧢', 'საწოლში დასაწოლად აუცილებლად მოითხოვს, რომ მამას ზამთრის ქუდი ეხუროს. დაე, მამამ ის ქუდი დაიხუროს და სასაცილო ხმები გამოსცეს. საღამოს ეს უცნაური აბსურდულობა ძილის წინ თქვენც გაგაცინებთ და ბავშვის სიჯიუტესაც მყისიერად გააქრობს.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'ფიზიკის კანონების გამომწვევი სიჯიუტე 💧', 'ქვითინებს და ამბობს, რომ წყალი მშრალი უნდა? შეუძლებელი რაღაცების მოთხოვნით ბავშვის გონება სინამდვილეში თქვენს სიმტკიცეს ამოწმებს. ამ დროს ლოგიკას ნუ ეძებთ — უბრალოდ სხვა ფერად საგანზე მყისიერად გადაატანინეთ ყურადღება.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'კარადაში გამეფებული სიჩუმე 🚪', 'სახლში მოულოდნელად სიჩუმე ჩამოვარდა და ბავშვი კარადაში დამალული, თავისთვის მოთამაშე იპოვეთ. ეს პირადი სივრცის ძიებაა. მაშინვე ნუ გამოიყვანთ იქიდან — მასაც სურს, ხმაურს გაერიდოს, ცოტა ხნით მარტო დარჩეს და გონება დაასვენოს.'),
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa', 'ჩუმი ბრაზი 😤', 'როცა სასურველს ვერ იღებს, ტირილის ნაცვლად ხელებს გულზე იკრეფს, კედელს უყურებს და გებუტებათ. ეს ემოციების მართვის ახალი და ძალიან მნიშვნელოვანი ეტაპია. ნუ დააძალებთ საუბარს — 3 წუთის შემდეგ ისე დაბრუნდება სიცილით, თითქოს არაფერი მომხდარა.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'ოქროს სიჩუმის გაზომვა 🤫', 'სახლში ხმაური ყურებს გიწუილებთ. როცა ბავშვი ბოლოს და ბოლოს დაიძინებს, ხმის საზომი ხელსაწყო ჩართეთ. ეკრანზე ნულთან მიახლოებული რიცხვებისა და ამ ციფრული სიჩუმის ყურება დაღლილი დედის გონებისთვის საუკეთესო ვიზუალური მასაჟია.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'ახალი ენის აღმოჩენა 🗣️', 'ბავშვმა აღმოაჩინა თავისივე მოგონილი რთული და უცნაური სიტყვები, მაგალითად, მფრენ-მორბენალი და ცხელი-ცივი. მისი ლექსიკური მარაგი საოცარი სისწრაფით ფართოვდება. განვითარების ტრეკერში აუცილებლად ჩაინიშნეთ ეს სასაცილო, მის მიერ მოგონილი სიტყვები, რათა სამახსოვრო არქივად შემოგრჩეთ.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'უცნაური თანამგზავრი 🥄', 'პარკში წასვლისას სათამაშო მანქანების ნაცვლად დაჟინებით ითხოვს, თან წაიღოს სამზარეულოში ნაპოვნი ჩამჩა. ხელს ნუ შეუშლით! დღეს ეს ჩამჩა პარკში ქვიშის სათხრელად მისი ყველაზე უჩვეულო, მაგრამ ყველაზე პრაქტიკული სათამაშო გახდება.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'კატებს წყლის ეშინიათ 🐈', 'აბაზანაში რომ არ შევიდეს, ამბობს: მე კატა ვარ, კატები არ ბანაობენო. მიიღეთ მისი როლი და თამაში განაგრძეთ: კი მაგრამ, ამ კატას საპნის ბუშტებით თამაში ხომ არ უნდა? — ასე დააინტერესეთ და შეზღუდვები წარმოსახვის ძალით გადალახეთ.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'პროფესიონალური ვაჭრობა 🛒', 'მაღაზიაში კანფეტის გამო ტირილის ნაცვლად გევაჭრებათ: ამას თუ ვიყიდით, სუპს შევჭამო. გილოცავთ, თქვენი პატარა ადვოკატი იზრდება! გულმავიწყობისგან თავის დასაზღვევად საყიდლების სია გახსნილი გქონდეთ, რათა მასთან კამათისას არაფერი გამოგრჩეთ.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', '„შემომხედე!“ პერიოდი 👀', 'დივნიდან ხტება, ზუსტად ერთსა და იმავე მოძრაობას 50-ჯერ იმეორებს და ყოველ ჯერზე თქვენს მოწონებას ელის. ტელეფონს თვალი მოსწყვიტეთ. ის თავად მოძრაობის გამო კი არ ხტება, არამედ მხოლოდ იმისთვის, რომ თქვენს თვალებში სიყვარულით სავსე მოწონების ნაპერწკალი დაინახოს.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'ჩუმი მესაიდუმლე 📝', 'გრძნობთ, რომ არავის ესმის თქვენი და სახლში მეტისმეტად იღლებით? ნაძალადევი ღიმილი გვერდზე გადადეთ. განწყობის დღიურში დაწერეთ, სინამდვილეში რამდენად გამოფიტული ხართ დღეს. ეკრანზე გადატანილი ყოველი სიტყვა მხრებიდან მძიმე ტვირთს მოგიხსნით.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'იატაკზე ჩაძინება 🥱', 'დღისით დაძინებაზე უარი თქვა და ჯიუტობდა, თუმცა ბოლოს სათამაშოებს შორის, ხალიჩაზე მოკუნტული ჩაეძინა. საწოლში გადასაყვანად ნუ გააღვიძებთ — დატოვეთ ოთახის შუაგულში მშვიდად მძინარე, დატკბით ამ უმანკო სანახაობით და თქვენც 1 საათით დაისვენეთ.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'სიბნელის ეშინია? 👻', 'დაახლოებით 3.5 წლის ასაკში სიბნელის შიში ხშირად იჩენს თავს. ოთახში პატარა ღამის სანათი დადგით და „ჭკვიან ზღაპრებში“ მამაცი გმირების შესახებ ისტორიები შექმენით.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'დედების საუბარი 💬', 'გღლით ფიქრი: „რატომ ვერ მიეჩვია ჩემი ბავშვი ჯერ კიდევ ბოლომდე ქოთანს?“ შეუერთდით Anacan-ის საზოგადოებას და დაინახავთ, რომ ყველა ბავშვს განვითარების საკუთარი ტემპი აქვს.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'სიტყვებს ცვლის? 🗣️', 'ზოგ ასოს განზრახ ცვლის, სასაცილო ბგერებს გამოსცემს და ამაზე იცინის? ის ენის მოქნილობას აღმოაჩენს. თქვენც აჰყევით და სიტყვებით ითამაშეთ.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'მეგობრობის განცდა 👫', 'პარკში უკვე ცდილობს სხვა ბავშვებთან ერთად თამაშს — არა პარალელურად, არამედ უშუალო ურთიერთობით? სოციალიზაცია ოფიციალურად იწყება! შორიდან დააკვირდით და საჭიროების შემთხვევაში დასახმარებლად მზად იყავით.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'სია თქვენს ჯიბეში 🛒', 'ყოველდღიურ ქაოსში შამპუნი გაგითავდათ თუ სველი ხელსახოცები? ნუ ეცდებით ყველაფრის დამახსოვრებას — მაშინვე ჩაწერეთ საყიდლების სიაში და თქვენს პარტნიორთან დაასინქრონეთ.'),
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1', 'სიჩუმის საჭიროება 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმის საზომით გარემოში დეციბელების დონე შეამოწმეთ და მეზობელ ოთახში ტელევიზორის ხმას დაუწიეთ.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'მისი სუნთქვის სითბო 💖', 'მთელი დღე ჭკუიდან გადაჰყავდით და ყველაფერზე ჯიუტობდა. ახლა კი საწოლში მკერდზე მოგეკრათ და ოთახს მისი რიტმული სუნთქვა ავსებს. დედობის ყველაზე დიდი ჯილდო სწორედ ეს არის. გულში ჩაიკარით და მთელი დაღლილობა დაივიწყეთ.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'უკუღმა ჩაცმული ფეხსაცმლით სიამაყე 👟', 'ფეხსაცმელი უკუღმა ჩაიცვა, მაგრამ ისეთი ამაყი დადის, თითქოს მთელი სამყარო დაიპყრო. ნუ ჩაერევით და ნუ ეცდებით გასწორებას. ბავშვის თავდაჯერებულობა და დამოუკიდებლობა მილიონჯერ უფრო მნიშვნელოვანია, ვიდრე ტანსაცმლის ესთეტიკური იერი.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'ემპათიის მწვერვალი 🩹', 'სათამაშო დათუნიას ხელი სტკივა და ამიტომ პლასტირი დააკრა და აკოცა? აღფრთოვანდით მისი დიდი და კეთილი გულით. განვითარების ტრეკერში სიამაყით მონიშნეთ ეს ღრმა ემპათია, როგორც მისი ხასიათის ერთ-ერთი ყველაზე მშვენიერი თვისება.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'მამის სათამაშო მოედანი 👨‍👧', 'მოთმინება გეწურებათ? ოთახის კარი დახურეთ და ბავშვი მამასთან მარტო დატოვეთ. დაე, ამ საღამოს სახლში თამაშების ერთადერთი ხელმძღვანელი მამა იყოს, თქვენ კი დაისვენეთ.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'ნახეთ, რას ვაკეთებ! 🤸‍♂️', 'ცდილობს ცალ ფეხზე დადგეს ან იხტუნაოს, რომ თქვენი ყურადღება მიიქციოს? მას თქვენი მოწონება სურს. განვითარების ტრეკერში მონიშნეთ ეს ფიზიკური წონასწორობის უნარი და ტაში დაუკარით.'),
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697', 'ბოსტნეულის ომები 🥦', 'თეფშზე დადებულ მწვანე ბოსტნეულს გვერდზე სწევს? ნუ შეებრძოლებით. ჯანსაღ რეცეპტებში მოძებნეთ ეშმაკური ხერხები, რომ ბოსტნეული კექსში ან კატლეტში დამალოთ.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'ხელოვნება სხეულზე 🖍️', 'უეცარმა სიჩუმემ დაგაეჭვათ და აღმოაჩინეთ, რომ ბავშვი ფლომასტერით ხელებზე ხელოვნების ნიმუშს ქმნის. ნუ გაბრაზდებით. ის ნატიფ მოტორულ უნარებს ივითარებს, კანი კი წყლით მაინც გაიწმინდება. ღრმად ჩაისუნთქეთ და ეს სახალისო მომენტი ვიდეოზე გადაიღეთ.'),
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf', 'ჩურჩულის ჰიპნოზი 🤫', 'საწოლში იმდენად აქტიურია, რომ ვერ იძინებს. ხმის აწევის ნაცვლად, მოულოდნელად დაუწიეთ ხმას. მხოლოდ ჩურჩულით ესაუბრეთ. როცა ბავშვი თქვენ გასაგონად ყურადღებას დაძაბავს, მისი ტვინი ავტომატურად ძილის რეჟიმზე გადაერთვება.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'დედების საზოგადოების ძალა 💬', 'ფიქრი, რომ ეს ბავშვი არასდროს დამშვიდდება, გღლით? შეუერთდით Anacan-ის საზოგადოებას. როცა იქ სხვა დედების მსგავს და კიდევ უფრო სახალისო სიჯიუტის ამბებს წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ, და შვებით ამოისუნთქავთ.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'ფილოსოფიის პროფესორი 🤔', 'რატომ არ ჩანს ქარი? რატომ ცვივა ფოთლები? ასეთი ღრმა კითხვები დილიდანვე თავს გატეხინებთ. ნუ ეცდებით საათობით მეცნიერული ახსნა-განმარტებების მიცემას. ამ ასაკში მას სავსებით დააკმაყოფილებს გამოგონილი და საყვარელი პასუხები, მაგალითად: იმიტომ, რომ ხეები ტანსაცმელს იცვლიან.'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'ცეკვა ჩრდილებთან 🐰', 'სიბნელის შიშს იმიზეზებს და საწოლიდან გარბის. ოთახში ყველა შუქი ჩააქრეთ, ფანარი აანთეთ და კედელზე ხელებით ფრინველებისა და ძაღლების ჩრდილები შექმენით. სიბნელე, რომლისაც ეშინოდა, მისთვის წამებში თეატრად გადაიქცევა.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'ხელოვნური ინტელექტი — თქვენი მხსნელი 🤖', 'ბავშვის კითხვებზე ან უცნაურ ქცევებზე პასუხს ვერ პოულობთ? მიმართეთ Anacan AI-ს. ის მშვიდად და მოკლედ, პედიატრის ენით აგიხსნით, როგორ მუშაობს 3 წელს გადაცილებული ბავშვების ტვინი.')
) AS v(id, t, b)
WHERE x.id = v.id;
